static int GlyphCount(const char* s) {
    if (!s) {
        return 0;
    }
    int len = (int)str::Len(s);
    int i = 0;
    int n = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (cp > 32 && cp != 0x3000) {
            n++;
        }
    }
    return n;
}

static int GlyphCountRange(const char* s, int from, int to) {
    if (!s || from >= to) {
        return 0;
    }
    int len = (int)str::Len(s);
    if (to > len) {
        to = len;
    }
    if (from < 0) {
        from = 0;
    }
    int i = from;
    int n = 0;
    while (i < to) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (cp > 32 && cp != 0x3000) {
            n++;
        }
    }
    return n;
}

static bool IsTocHeadingSpaceCp(int cp) {
    return cp <= 32 || cp == 0x3000;
}

static bool IsTocHeadingLeadPunctCp(int cp) {
    return cp == '(' || cp == '[' || cp == '{' || cp == '<' || cp == 0x3010 || cp == 0x300A || cp == 0x3008 ||
           cp == 0x300C || cp == 0xFF08 || cp == 0xFF3B;
}

static bool IsTocHeadingTrailPunctCp(int cp) {
    return cp == ':' || cp == 0xFF1A || cp == '.' || cp == 0x3002 || cp == 0xFF0E;
}

static void CompactAsciiLowerCopy(const char* s, char* dst, int dstCap) {
    dst[0] = 0;
    if (!s || dstCap < 2) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    int o = 0;
    while (i < len && o + 1 < dstCap) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (IsTocHeadingSpaceCp(cp)) {
            continue;
        }
        if (cp >= 'A' && cp <= 'Z') {
            cp = cp - 'A' + 'a';
        }
        if (cp < 128) {
            dst[o++] = (char)cp;
        } else {
            break;
        }
    }
    dst[o] = 0;
}

// "contents of the package" after the heading token, not "ContentsA".
static bool RestLooksLikeContentsSentence(const char* rest) {
    char compact[96];
    CompactAsciiLowerCopy(rest, compact, (int)sizeof(compact));
    if (!compact[0]) {
        return false;
    }
    return str::StartsWith(compact, "ofthe") || str::StartsWith(compact, "ofthis") || str::StartsWith(compact, "ofa") ||
           str::StartsWith(compact, "ofan") || str::StartsWith(compact, "ofour") || str::StartsWith(compact, "are") ||
           str::StartsWith(compact, "may") || str::StartsWith(compact, "will") || str::StartsWith(compact, "include") ||
           str::StartsWith(compact, "inthis") || str::StartsWith(compact, "inthe") ||
           str::StartsWith(compact, "listed");
}

struct PrintedTocHeadingInfo {
    bool matched = false;
    bool english = false;
    int headingEnd = 0;
};

// Heading token at the start (spaces ignored). Remainder may be a glued title.
static bool MatchPrintedTocHeading(const char* s, PrintedTocHeadingInfo* out) {
    if (out) {
        *out = {};
    }
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    struct Map {
        int from = 0;
        int to = 0;
        int cp = 0;
        int low = 0;
    };
    Map map[160];
    int nMap = 0;
    int i = 0;
    while (i < len && nMap < (int)dimof(map)) {
        int from = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (IsTocHeadingSpaceCp(cp)) {
            continue;
        }
        int low = cp;
        if (low >= 'A' && low <= 'Z') {
            low = low - 'A' + 'a';
        }
        map[nMap].from = from;
        map[nMap].to = i;
        map[nMap].cp = cp;
        map[nMap].low = low;
        nMap++;
    }
    int start = 0;
    while (start < nMap && IsTocHeadingLeadPunctCp(map[start].cp)) {
        start++;
    }
    auto seqIs = [&](int at, const char* ascii, int n) -> bool {
        if (at < 0 || n < 1 || at + n > nMap) {
            return false;
        }
        for (int k = 0; k < n; k++) {
            if (map[at + k].low != (unsigned char)ascii[k]) {
                return false;
            }
        }
        return true;
    };
    if (seqIs(start, "the", 3) && start + 3 < nMap) {
        int nxt = start + 3;
        if (seqIs(nxt, "table", 5) || seqIs(nxt, "contents", 8)) {
            start = nxt;
        }
    }
    int tok = 0;
    bool english = false;
    if (seqIs(start, "tableofcontents", 15)) {
        tok = 15;
        english = true;
    } else if (seqIs(start, "contents", 8)) {
        tok = 8;
        english = true;
    } else if (start + 1 < nMap) {
        int a = map[start].cp;
        int b = map[start + 1].cp;
        // 目录 / 目次, plus OCR 日录 / 自录.
        if ((a == 0x76EE && (b == 0x5F55 || b == 0x6B21)) || ((a == 0x65E5 || a == 0x81EA) && b == 0x5F55)) {
            tok = 2;
            english = false;
        }
    }
    if (tok < 1) {
        return false;
    }
    int last = start + tok - 1;
    int headingEnd = map[last].to;
    int scan = headingEnd;
    while (scan < len) {
        int save = scan;
        int cp = Utf8CodepointNext(s, len, scan);
        if (IsTocHeadingSpaceCp(cp) || IsTocHeadingTrailPunctCp(cp)) {
            headingEnd = scan;
            continue;
        }
        scan = save;
        break;
    }
    if (english && RestLooksLikeContentsSentence(s + headingEnd)) {
        return false;
    }
    if (out) {
        out->matched = true;
        out->english = english;
        out->headingEnd = headingEnd;
    }
    return true;
}

static bool LooksLikePrintedTocHeading(const char* s) {
    return MatchPrintedTocHeading(s, nullptr);
}

static bool LooksLikeEnglishTocHeading(const char* s) {
    PrintedTocHeadingInfo info;
    return MatchPrintedTocHeading(s, &info) && info.english;
}

bool LineLooksLikePrintedTocHeading(const char* s) {
    return LooksLikePrintedTocHeading(s);
}

bool LineLooksLikeEnglishTocHeading(const char* s) {
    return LooksLikeEnglishTocHeading(s);
}

int PrintedTocHeadingPrefixLen(const char* s) {
    PrintedTocHeadingInfo info;
    if (!MatchPrintedTocHeading(s, &info) || !info.matched) {
        return 0;
    }
    return info.headingEnd;
}

static bool HasLetterOrCjk(const char* s);
static bool LineLooksLikePageNumber(const char* s);

static void SplitGluedPrintedTocHeadings(Vec<ScanLine>& lines) {
    Vec<ScanLine> out;
    for (int i = 0; i < lines.Size(); i++) {
        if (!lines[i].text) {
            continue;
        }
        int prefix = PrintedTocHeadingPrefixLen(lines[i].text);
        char* rest = nullptr;
        if (prefix > 0) {
            int len = (int)str::Len(lines[i].text);
            if (prefix < len) {
                rest = DupTrimmed(lines[i].text + prefix);
                lines[i].text[prefix] = 0;
                str::TrimWSInPlace(lines[i].text, str::TrimOpt::Both);
                if (rest && (!rest[0] || !HasLetterOrCjk(rest))) {
                    str::Free(rest);
                    rest = nullptr;
                }
            }
        }
        out.Append(lines[i]);
        lines[i].text = nullptr;
        if (!rest) {
            continue;
        }
        bool prepended = false;
        int g = GlyphCount(rest);
        if (g >= 1 && g <= 3) {
            for (int j = i + 1; j < lines.Size(); j++) {
                if (!lines[j].text || lines[j].srcPage != out[out.Size() - 1].srcPage) {
                    continue;
                }
                if (LineLooksLikePageNumber(lines[j].text) || LooksLikePrintedTocHeading(lines[j].text)) {
                    break;
                }
                if (str::StartsWithI(lines[j].text, rest)) {
                    break;
                }
                char* joined = str::Join(rest, " ", lines[j].text);
                str::Free(lines[j].text);
                lines[j].text = joined;
                prepended = true;
                break;
            }
        }
        if (prepended) {
            str::Free(rest);
            continue;
        }
        ScanLine extra = out[out.Size() - 1];
        extra.text = rest;
        extra.x += 8;
        extra.y += extra.dy > 8 ? extra.dy * 0.35f : 12;
        out.Append(extra);
    }
    lines.Reset();
    for (int i = 0; i < out.Size(); i++) {
        lines.Append(out[i]);
        out[i].text = nullptr;
    }
}

static bool IsListBulletCp(int cp) {
    return cp == '.' || cp == 0xFF0E || cp == 0x00B7 || cp == 0x2022 || cp == 0x30FB || cp == 0x2024 || cp == 0x2219 ||
           cp == 0xFF65;
}

static bool IsLeaderCp(int cp) {
    return cp == '.' || cp == 0xFF0E || cp == 0x00B7 || cp == 0x2026 || cp == 0x30FB || cp == 0x2500 || cp == 0x2014 ||
           cp == 0x2013 || cp == '_' || cp == '-' || cp == 0x3000 || cp == ' ' || cp == 0x2022 || cp == 0xFF0D ||
           cp == 0x00B7 || cp == 0x2024 || cp == 0x2219 || cp == 0x00A8 || cp == 0xFF65 || cp == 0x22EF ||
           cp == 0x2025 || cp == '/' || cp == 0xFF0F || cp == 0x2215 || cp == 0x2044;
}

static bool IsDigitCp(int cp) {
    return (cp >= '0' && cp <= '9') || (cp >= 0xFF10 && cp <= 0xFF19);
}

static int DigitValue(int cp) {
    if (cp >= '0' && cp <= '9') {
        return cp - '0';
    }
    if (cp >= 0xFF10 && cp <= 0xFF19) {
        return cp - 0xFF10;
    }
    return -1;
}

static bool IsCnDateUnitCp(int cp) {
    return cp == 0x5E74 || cp == 0x6708 || cp == 0x65E5; // 年月日
}

// i is the first character after a numbering dot. "4.6月30日" is a list "4." plus a date, not section 4.6.
static bool DottedFollowedByDate(const char* s, int len, int i) {
    if (!s || i >= len) {
        return false;
    }
    int look = Utf8CodepointNext(s, len, i);
    if (!IsDigitCp(look)) {
        return false;
    }
    while (i < len) {
        int save = i;
        int d = Utf8CodepointNext(s, len, i);
        if (!IsDigitCp(d)) {
            i = save;
            break;
        }
    }
    while (i < len) {
        int save = i;
        int sp = Utf8CodepointNext(s, len, i);
        if (sp > 32 && sp != 0x3000) {
            i = save;
            break;
        }
    }
    if (i >= len) {
        return false;
    }
    int unit = Utf8CodepointNext(s, len, i);
    return IsCnDateUnitCp(unit);
}

// Consecutive ASCII digits starting at i. Used to reject phone/ID runs after "2."
// (e.g. "2.12333电话…") so they stay simple ArabicDot rank 3, not dotted rank 2.
static int CountAsciiDigitsFrom(const char* s, int len, int i) {
    int n = 0;
    while (i < len) {
        int save = i;
        int d = Utf8CodepointNext(s, len, i);
        if (!IsDigitCp(d)) {
            i = save;
            break;
        }
        n++;
    }
    return n;
}

static bool HasLetterOrCjk(const char* s);
static bool LooksLikeUrlStart(const char* s);
static bool LooksLikeDomainOrEmailFragment(const char* s);
static bool LooksLikeUrlListTitle(const char* s);
static void CompactSpacedUrlInTitle(char* s);
static void ShortenOfficialUrlListTitle(char* s);
static bool LooksLikeArchiveJunk(const char* s);
static bool LineLooksLikeRomanPage(const char* s);
static bool LineLooksLikePageNumber(const char* s);
static int ParseBarePrintedPage(const char* s);
static bool StartsWithXinDeHeading(const char* s);

static bool ParsePrintedTocLine(const char* raw, char** titleOut, int* pageOut) {
    *titleOut = nullptr;
    *pageOut = 0;
    char* s = DupTrimmed(raw);
    if (!s || !s[0]) {
        str::Free(s);
        return false;
    }
    if (LooksLikePrintedTocHeading(s)) {
        str::Free(s);
        return false;
    }
    int len = (int)str::Len(s);
    int page = 0;
    int nDigits = 0;
    int scan = len;
    int last = Utf8CodepointPrev(s, len, scan);
    while (last > 0 && (last == ' ' || last == 0x3000)) {
        last = Utf8CodepointPrev(s, len, scan);
    }
    if (last == ')' || last == 0xFF09) {
        last = Utf8CodepointPrev(s, len, scan);
        while (last > 0 && (last == ' ' || last == 0x3000)) {
            last = Utf8CodepointPrev(s, len, scan);
        }
    }
    int digitBuf[8];
    while (last > 0 && nDigits < 8) {
        if (IsDigitCp(last)) {
            digitBuf[nDigits++] = DigitValue(last);
            last = Utf8CodepointPrev(s, len, scan);
            int holdScan = scan;
            int holdLast = last;
            while (last > 0 && (last == ' ' || last == 0x3000)) {
                last = Utf8CodepointPrev(s, len, scan);
            }
            if (!IsDigitCp(last)) {
                scan = holdScan;
                last = holdLast;
                break;
            }
            continue;
        }
        break;
    }
    if (nDigits < 1) {
        str::Free(s);
        return false;
    }
    for (int i = nDigits - 1; i >= 0; i--) {
        page = page * 10 + digitBuf[i];
    }
    if (page < 1 || page > 9999) {
        str::Free(s);
        return false;
    }
    while (last > 0 && (IsLeaderCp(last) || last == ')' || last == 0xFF09 || last == '(' || last == 0xFF08 ||
                        last == 0x3008 || last == 0x3009)) {
        last = Utf8CodepointPrev(s, len, scan);
    }
    if (last <= 0 || scan < 0) {
        str::Free(s);
        return false;
    }
    int end = scan;
    Utf8CodepointNext(s, len, end);
    s[end] = 0;
    str::TrimWSInPlace(s, str::TrimOpt::Both);
    if (GlyphCount(s) < 1 || !HasLetterOrCjk(s)) {
        str::Free(s);
        return false;
    }
    *titleOut = s;
    *pageOut = page;
    return true;
}

static bool IsCnNumeral(int cp) {
    return cp == 0x4e00 || cp == 0x4e8c || cp == 0x4e09 || cp == 0x56db || cp == 0x4e94 || cp == 0x516d ||
           cp == 0x4e03 || cp == 0x516b || cp == 0x4e5d || cp == 0x5341 || cp == 0x767e || cp == 0x5343 || cp == 0x96f6;
}

static int CnNumeralValue(int cp) {
    if (cp == 0x4e00) {
        return 1;
    }
    if (cp == 0x4e8c) {
        return 2;
    }
    if (cp == 0x4e09) {
        return 3;
    }
    if (cp == 0x56db) {
        return 4;
    }
    if (cp == 0x4e94) {
        return 5;
    }
    if (cp == 0x516d) {
        return 6;
    }
    if (cp == 0x4e03) {
        return 7;
    }
    if (cp == 0x516b) {
        return 8;
    }
    if (cp == 0x4e5d) {
        return 9;
    }
    if (cp == 0x5341) {
        return 10;
    }
    return 0;
}

// 第X<unit> outline depth: 编/章/篇/回/课/讲=1, 节/条=2, 款=3, 项=4.
static int DepthFromDiUnit(int mark) {
    if (mark == 0x7F16 || mark == 0x7AE0 || mark == 0x7BC7 || mark == 0x56DE || mark == 0x8BFE || mark == 0x8BB2) {
        return 1;
    }
    if (mark == 0x8282 || mark == 0x6761) {
        return 2;
    }
    if (mark == 0x6B3E) {
        return 3;
    }
    if (mark == 0x9879) {
        return 4;
    }
    return 0;
}

static bool DiUnitIsChapter(int mark) {
    return mark == 0x7F16 || mark == 0x7AE0 || mark == 0x7BC7 || mark == 0x56DE || mark == 0x8BFE || mark == 0x8BB2;
}

static bool IsParenOpenCp(int cp) {
    // OCR often reads fullwidth （ as CJK 〈 (U+3008) instead of U+FF08 or '('.
    return cp == 0xFF08 || cp == '(' || cp == 0x3008;
}

static bool IsParenCloseCp(int cp) {
    return cp == 0xFF09 || cp == ')' || cp == 0x3009;
}

static bool IsOcrYiDashCp(int cp) {
    return cp == '-' || cp == '_' || cp == 0x2010 || cp == 0x2011 || cp == 0x2012 || cp == 0x2013 || cp == 0x2014 ||
           cp == 0x2015 || cp == 0x2212 || cp == 0xFF0D || cp == 0x2500 || cp == 0xFE58;
}

// i is already past the opening （ or (. Consume 一/十一/12 then ） or ).
static bool ConsumeParenNumberingAfterOpen(const char* s, int len, int& i) {
    int i0 = i;
    int nInside = 0;
    int nDash = 0;
    while (i < len && nInside < 6) {
        int t = i;
        int n = Utf8CodepointNext(s, len, i);
        if (IsCnNumeral(n) || IsDigitCp(n)) {
            nInside++;
            continue;
        }
        i = t;
        break;
    }
    if (nInside < 1) {
        i = i0;
        while (i < len && nDash < 3) {
            int t = i;
            int n = Utf8CodepointNext(s, len, i);
            if (!IsOcrYiDashCp(n)) {
                i = t;
                break;
            }
            nDash++;
        }
        if (nDash >= 1) {
            nInside = 1;
        } else {
            i = i0;
        }
    }
    int close = i < len ? Utf8CodepointNext(s, len, i) : 0;
    bool ok = nInside > 0 && IsParenCloseCp(close);
    // #region agent log
    if (Dbg92Interesting(s)) {
        int peek = i0;
        int d0 = peek < len ? Utf8CodepointNext(s, len, peek) : 0;
        char extra[192];
        snprintf(extra, (int)sizeof(extra), "ok=%d nInside=%d nDash=%d d0=U+%04X close=U+%04X", (int)ok, nInside, nDash,
                 d0, close);
        Dbg92a48e("A", "ExtractPdfToc.cpp:ConsumeParenNumberingAfterOpen", s, extra);
    }
    // #endregion
    return ok;
}

enum class MarkerType {
    None,
    ChineseDunhao, // 一、 一. 一．
    ChineseParen,  // （一）
    ArabicDot,     // 1.  1、  1.1
    ArabicParen,   // （1）
    Chapter,       // 第一章
    Section,       // 第一节
    Article,       // 第一条
    Appendix,      // 附件
    FormTable,     // 表一 表二 表1： 附表
    YiShi,         // 一是
    DiYiComma      // 第一，
};

struct HeadingMarker {
    MarkerType type = MarkerType::None;
    int number = -1;
    int subNumber = 0; // 附件1-1 → number=1, subNumber=1
    int prefixLength = 0;
    int rank = 0;
};

// OCR/PDF fonts often draw 顿号 as fullwidth grave `｀` (U+FF40) or ASCII backtick.
static bool IsOcrDunhaoLookalikeCp(int cp) {
    return cp == '`' || cp == 0xFF40 || cp == 0x00B4 || cp == 0x02CB || cp == 0x2018 || cp == 0x2019 || cp == 0xFF07;
}

static bool IsDunhaoSepCp(int cp) {
    return cp == 0x3001 || cp == '.' || cp == 0xFF0E || IsOcrDunhaoLookalikeCp(cp);
}

// "1." / "1．" / "1、" / OCR "1。" (ideographic full stop used as a list dot)
static bool IsSimpleArabicListSepCp(int cp) {
    return cp == '.' || cp == 0xFF0E || cp == 0x3001 || cp == 0x3002;
}

// "2.0、涉密…" mixes decimal "." with 顿号. 一、 and 1、 are fine; （一）、 / （1）、 are not.
static bool NextNonSpaceIsDunhao(const char* s, int len, int i) {
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 32 && cp != 0x3000) {
            i = save;
            break;
        }
    }
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return cp == 0x3001;
}

static bool NextNonSpaceIsParenClose(const char* s, int len, int i) {
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 32 && cp != 0x3000) {
            i = save;
            break;
        }
    }
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return IsParenCloseCp(cp);
}

static bool IsIdeoCommaCp(int cp) {
    return cp == 0xFF0C || cp == ',';
}

static int ConsumeOfficialNumber(const char* s, int len, int& i) {
    int n = 0;
    int nTok = 0;
    while (i < len) {
        int save = i;
        int next = Utf8CodepointNext(s, len, i);
        if (IsDigitCp(next)) {
            n = n * 10 + DigitValue(next);
            nTok++;
            continue;
        }
        if (IsCnNumeral(next)) {
            int cv = CnNumeralValue(next);
            if (cv == 10 && n == 0) {
                n = 10;
            } else if (cv == 10 && n > 0 && n < 10) {
                n = n * 10;
            } else if (n == 10 && cv > 0 && cv < 10) {
                n += cv;
            } else if (n >= 20 && (n % 10) == 0 && n < 100 && cv > 0 && cv < 10) {
                n += cv;
            } else if (n == 0 && cv > 0) {
                n = cv;
            } else {
                // #region agent log
                {
                    char extra[96];
                    snprintf(extra, (int)sizeof(extra), "stop n=%d cv=%d", n, cv);
                    Dbg92a48e("U", "ExtractPdfToc.cpp:ConsumeOfficialNumber.stop", s, extra);
                }
                // #endregion
                i = save;
                break;
            }
            nTok++;
            continue;
        }
        i = save;
        break;
    }
    return nTok > 0 ? n : -1;
}

static void SkipSpacesUtf8(const char* s, int len, int& i) {
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 32 && cp != 0x3000) {
            i = save;
            return;
        }
    }
}

static bool IsOfficialAttachHyphenCp(int cp) {
    return cp == '-' || cp == 0xFF0D || cp == 0x2013 || cp == 0x2014 || cp == 0x2212;
}

// After 附件N, consume "-1" / "－2" and an optional "." / "、" / "：".
static bool ConsumeOfficialAttachSubNumber(const char* s, int len, int& i, int* subOut) {
    int peek = i;
    SkipSpacesUtf8(s, len, peek);
    int hy = peek < len ? Utf8CodepointNext(s, len, peek) : 0;
    if (!IsOfficialAttachHyphenCp(hy)) {
        return false;
    }
    SkipSpacesUtf8(s, len, peek);
    int n = ConsumeOfficialNumber(s, len, peek);
    if (n < 1 || n > 40) {
        return false;
    }
    int after = peek;
    SkipSpacesUtf8(s, len, after);
    int next = after < len ? Utf8CodepointNext(s, len, after) : 0;
    if (next == 0x7B2C) { // 第 — "附件1-第二章"
        return false;
    }
    i = peek;
    if (IsSimpleArabicListSepCp(next) || next == ':' || next == 0xFF1A) {
        i = after;
    }
    if (subOut) {
        *subOut = n;
    }
    return true;
}

// "1-1.标题" / "1-1 标题" / "2-2、标题"
static bool ParseOfficialAttachFormSerial(const char* s, int* majorOut, int* subOut, const char** titleOut) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int major = ConsumeOfficialNumber(s, len, i);
    if (major < 1 || major > 40) {
        return false;
    }
    int sub = 0;
    if (!ConsumeOfficialAttachSubNumber(s, len, i, &sub)) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    if (titleOut) {
        *titleOut = s + i;
    }
    if (majorOut) {
        *majorOut = major;
    }
    if (subOut) {
        *subOut = sub;
    }
    return titleOut ? s[i] != 0 : true;
}

// After 附件N, leftover ) / ）。 from a wrapped "见附件N）。" is not a title.
static bool OfficialAppendixRestIsCitePunct(const char* s, int len, int i) {
    SkipSpacesUtf8(s, len, i);
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32 || cp == 0x3000) {
            continue;
        }
        if (cp == 0x3002 || cp == 0xFF0E || cp == '.' || cp == 0xFF1B || cp == ';' || cp == 0x3001 || cp == 0xFF0C ||
            cp == ',') {
            continue;
        }
        return false;
    }
    return true;
}

static bool LooksLikeOfficialAppendixCiteAfterNumber(const char* s, int len, int i) {
    SkipSpacesUtf8(s, len, i);
    if (!NextNonSpaceIsParenClose(s, len, i)) {
        return false;
    }
    Utf8CodepointNext(s, len, i);
    return OfficialAppendixRestIsCitePunct(s, len, i);
}

// Body wrap "附件2)。" / "附件2）" is a citation fragment, not an 附件N start.
static bool LooksLikeOfficialAppendixCiteFragment(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp != 0x9644) { // 附
        return false;
    }
    int cp2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp2 != 0x4EF6) { // 件
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    int peek = i;
    int open = peek < len ? Utf8CodepointNext(s, len, peek) : 0;
    if (open == '(' || open == 0xFF08 || open == 0x3008) {
        return false;
    }
    int n = ConsumeOfficialNumber(s, len, i);
    if (n < 1) {
        SkipSpacesUtf8(s, len, i);
        const char* rest = s + i;
        // Form footer "附件与本表同时归档)" is not 附件1.
        return str::StartsWith(rest, "\xE4\xB8\x8E\xE6\x9C\xAC\xE8\xA1\xA8") ||           // 与本表
               str::StartsWith(rest, "\xE5\x90\x8C\xE6\x97\xB6\xE5\xBD\x92\xE6\xA1\xA3"); // 同时归档
    }
    return LooksLikeOfficialAppendixCiteAfterNumber(s, len, i);
}

// Gantt / 计划表 cells: "9.06.10", "19.06.21", "9.10.05 19.10.16", "9.06.1013 原型…".
// Do not treat "2.10 编制…" or "1.2.3 标题" as dates (no leading-zero month/day).
static bool LooksLikeNumericScheduleDate(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int groups = 0;
    bool leadZero = false;
    int gLen[6] = {};
    int gVal[6] = {};
    while (groups < 6 && i < len) {
        int peekPos = i;
        int peek = peekPos < len ? Utf8CodepointNext(s, len, peekPos) : 0;
        if (!IsDigitCp(peek)) {
            break;
        }
        int nDig = 0;
        int val = 0;
        bool z = false;
        while (i < len) {
            int save = i;
            int dcp = Utf8CodepointNext(s, len, i);
            if (!IsDigitCp(dcp)) {
                i = save;
                break;
            }
            int d = DigitValue(dcp);
            if (nDig == 0 && d == 0) {
                z = true;
            }
            val = val * 10 + d;
            nDig++;
            if (nDig > 4) {
                return false;
            }
        }
        if (nDig < 1) {
            break;
        }
        if (z && nDig >= 2) {
            leadZero = true;
        }
        gLen[groups] = nDig;
        gVal[groups] = val;
        groups++;
        SkipSpacesUtf8(s, len, i);
        int sepPos = i;
        int sep = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (sep == '.' || sep == 0xFF0E) {
            continue;
        }
        i = sepPos;
        break;
    }
    if (groups < 2) {
        return false;
    }
    if (leadZero) {
        return true;
    }
    if (gLen[0] == 2 && gVal[0] >= 18 && gVal[0] <= 30 && gVal[1] >= 1 && gVal[1] <= 12) {
        return true;
    }
    return false;
}

// "9.9698万元" / "32.6万元" are amounts, not "9. 标题" / section 32.6.
static bool LooksLikeAmountTail(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (IsDigitCp(cp) || cp == ',' || cp == 0xFF0C) {
            continue;
        }
        i = save;
        break;
    }
    SkipSpacesUtf8(s, len, i);
    int unit = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (unit == 0x4E07 || unit == 0x4EBF || unit == 0x5143 || unit == 0xFF05 || unit == '%') {
        return true;
    }
    if (unit == 0x5206) { // 分 as in 0.1分 / —0.2分, not 分类
        int next = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (next <= 0 || next == ';' || next == 0xFF1B || next == 0x3002 || next == '.' || next == ',' ||
            next == 0xFF0C || next == ')' || next == 0xFF09) {
            return true;
        }
    }
    return str::FindI(s, "kva") || str::FindI(s, "kw") || str::Find(s, "mm") || str::Find(s, "MM");
}

// 招标规格 / 附件填表说明: "1、标准机柜尺寸为600mm" / "5.表中列对关系"
// "600mm" is a spec unit. ".com" / "qq.com" is not (email 1.任务 would be dropped).
static bool LineHasMmAsLengthUnit(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    const char* p = s;
    while (p && p[0]) {
        const char* hit = str::FindI(p, "mm");
        if (!hit) {
            return false;
        }
        if (hit > s && hit[-1] == '.') {
            p = hit + 2;
            continue;
        }
        return true;
    }
    return false;
}

static bool LooksLikeOfficialSpecOrFormLine(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (str::Find(s, "表中列") || str::Find(s, "本表中") || str::Find(s, "列对关系") || str::Find(s, "列对应关系") ||
        str::Find(s, "此表一式") || str::Find(s, "黑色水笔") || str::Find(s, "填写本表") || str::Find(s, "填表日期") ||
        str::Find(s, "字迹工整") || str::Find(s, "汇总相关资料") || str::Find(s, "填表说明") ||
        str::Find(s, "填写说明") || str::Find(s, "单位“收入”") || str::Find(s, "单位收入中不含") ||
        str::Find(s, "“人数”为") || str::Find(s, "涉改重新组建")) {
        return true;
    }
    {
        int len = (int)str::Len(s);
        int i = 0;
        while (i < len) {
            int cp = Utf8CodepointNext(s, len, i);
            if (cp == 0x5217 && i < len) {
                int save = i;
                int d = Utf8CodepointNext(s, len, i);
                if (IsDigitCp(d)) {
                    return true;
                }
                i = save;
            }
        }
    }
    if (str::FindI(s, "kva") || str::Find(s, "UPS") || LineHasMmAsLengthUnit(s) || str::Find(s, "㎡") ||
        str::Find(s, "平米") || str::Find(s, "平方米") || str::Find(s, "承重")) {
        return true;
    }
    if (str::Find(s, "机柜尺寸") || str::Find(s, "标准机柜") || str::Find(s, "非标机柜") || str::Find(s, "电源插座") ||
        str::Find(s, "监控摄像头") || str::Find(s, "根据采购要求") || str::Find(s, "根据采购需要") ||
        str::Find(s, "根据以上两点")) {
        return true;
    }
    if (str::Find(s, "度电") || str::Find(s, "阶梯电价") || str::Find(s, "商业用电") || str::Find(s, "工业用电") ||
        str::Find(s, "农业生产用电")) {
        return true;
    }
    return false;
}

static bool OfficialHeadingIsSpecFormOrBidJunk(const char* s) {
    if (LooksLikeOfficialSpecOrFormLine(s)) {
        return true;
    }
    if (!s || !s[0]) {
        return false;
    }
    return str::Find(s, "采购标的") || str::Find(s, "招标控制价") || str::Find(s, "控制价编制") ||
           str::Find(s, "采购预算审核");
}

static bool LooksLikeOfficialFillNotesHeader(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    return str::StartsWith(s, "填表说明") || str::StartsWith(s, "填写说明") || str::Find(s, "填表说明：") ||
           str::Find(s, "填表说明:") || str::Find(s, "填写说明：");
}

static bool LooksLikeOfficialTableNoiseTitle(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (str::Find(s, "序号") && (str::Find(s, "单位") || str::Find(s, "扣分") || str::Find(s, "扣分原因"))) {
        return true;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int save = i;
    int minus = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (minus == '-' || minus == 0x2014 || minus == 0x2013 || minus == 0xFF0D) {
        SkipSpacesUtf8(s, len, i);
    } else {
        i = save;
    }
    int lead = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (lead != '0' && lead != 0xFF10) {
        return false;
    }
    int dot = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return dot == '.' || dot == 0xFF0E;
}

static HeadingMarker ParseHeadingMarker(const char* s) {
    HeadingMarker m;
    if (!s || !s[0]) {
        return m;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int start = i;
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp <= 0) {
        return m;
    }
    if (IsListBulletCp(cp)) {
        int after = i;
        SkipSpacesUtf8(s, len, after);
        int look = 0;
        if (after < len) {
            int t = after;
            look = Utf8CodepointNext(s, len, t);
        }
        if (IsDigitCp(look) || IsCnNumeral(look) || IsParenOpenCp(look) || look == 0x9644) {
            i = after;
            start = i;
            cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
            if (cp <= 0) {
                return m;
            }
        }
    }
    if (cp == 0x9644) { // 附
        int cp2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (cp2 == 0x4EF6) { // 件
            m.type = MarkerType::Appendix;
            SkipSpacesUtf8(s, len, i);
            int bangAt = i;
            int bang = bangAt < len ? Utf8CodepointNext(s, len, bangAt) : 0;
            if (bang == '!' || bang == 0xFF01) {
                i = bangAt;
                m.number = 1;
            } else {
                m.number = ConsumeOfficialNumber(s, len, i);
                if (m.number < 0) {
                    int peekAt = i;
                    SkipSpacesUtf8(s, len, peekAt);
                    int peek = peekAt < len ? Utf8CodepointNext(s, len, peekAt) : 0;
                    // "附件与本表同时归档)" / "附件中…" is body, not 附件1.
                    if (peek == 0x4E0E || peek == 0x540C || peek == 0x4E2D || peek == 0x540E ||
                        peek == 0x5185) { // 与 同 中 后 内
                        HeadingMarker empty;
                        return empty;
                    }
                    // "附件：1-1.…" / "附件：" is a cover list, not a numbered attachment.
                    if (peek == ':' || peek == 0xFF1A) {
                        m.number = 0;
                        m.prefixLength = i;
                        m.rank = 1;
                        return m;
                    }
                    // Preserve an unnumbered “附件” as such. Its position in
                    // a document is not evidence that the author called it
                    // “附件1”. Later attachment-sequence handling may fill a
                    // number only when an explicit sibling proves one exists.
                    m.number = 0;
                }
            }
            // "见附件2)。" wrap: leftover "附件2)" / "附件2）。" is not a heading.
            if (m.number >= 1 && LooksLikeOfficialAppendixCiteAfterNumber(s, len, i)) {
                HeadingMarker empty;
                return empty;
            }
            if (m.number >= 1) {
                int sub = 0;
                if (ConsumeOfficialAttachSubNumber(s, len, i, &sub)) {
                    m.subNumber = sub;
                }
            }
            m.prefixLength = i;
            m.rank = 1;
            return m;
        }
        if (cp2 == 0x8868) { // 表 → 附表 / 附表N
            int peekAt = i;
            int peek = peekAt < len ? Utf8CodepointNext(s, len, peekAt) : 0;
            if (peek == 0x683C || peek == 0x4E2D) { // 表格 表中
                return m;
            }
            int numAt = i;
            SkipSpacesUtf8(s, len, numAt);
            int n = ConsumeOfficialNumber(s, len, numAt);
            // "（填写附表三）" wrap: "表三）" / "附表二），总结…" is a citation, not 表N.
            if (NextNonSpaceIsParenClose(s, len, numAt)) {
                return m;
            }
            m.type = MarkerType::FormTable;
            i = numAt;
            if (n >= 1 && n <= 40) {
                m.number = n;
            } else {
                m.number = 0;
            }
            SkipSpacesUtf8(s, len, i);
            int look = i;
            int sep = look < len ? Utf8CodepointNext(s, len, look) : 0;
            if (sep == ':' || sep == 0xFF1A || IsDunhaoSepCp(sep)) {
                i = look;
            }
            m.prefixLength = i;
            m.rank = 2;
            return m;
        }
        return m;
    }
    if (cp == 0x8868) { // 表
        SkipSpacesUtf8(s, len, i);
        int n = ConsumeOfficialNumber(s, len, i);
        if (n >= 1 && n <= 40) {
            int peekPos = i;
            int peek = peekPos < len ? Utf8CodepointNext(s, len, peekPos) : 0;
            if (IsParenCloseCp(peek) || NextNonSpaceIsParenClose(s, len, peekPos)) {
                return m;
            }
            if (peek != 0x683C && peek != 0x4E2D) { // 表格 表中
                SkipSpacesUtf8(s, len, i);
                int look = i;
                int dig = look < len ? Utf8CodepointNext(s, len, look) : 0;
                if (IsDigitCp(dig)) {
                    int after = look;
                    SkipSpacesUtf8(s, len, after);
                    int afterDig = after < len ? Utf8CodepointNext(s, len, after) : 0;
                    if (afterDig == ':' || afterDig == 0xFF1A || IsDunhaoSepCp(afterDig)) {
                        i = look;
                    }
                }
                SkipSpacesUtf8(s, len, i);
                look = i;
                int sep = look < len ? Utf8CodepointNext(s, len, look) : 0;
                if (sep == ':' || sep == 0xFF1A || IsDunhaoSepCp(sep)) {
                    i = look;
                }
                m.type = MarkerType::FormTable;
                m.number = n;
                m.prefixLength = i;
                m.rank = 2;
                // #region agent log
                {
                    char extra[96];
                    snprintf(extra, (int)sizeof(extra), "biao n=%d prefix=%d", n, m.prefixLength);
                    DbgFace09("T", "ExtractPdfToc.cpp:ParseHeadingMarker.biao", s, extra);
                }
                // #endregion
                return m;
            }
        }
        return m;
    }
    if (cp == 0x7B2C) { // 第
        SkipSpacesUtf8(s, len, i);
        int n = ConsumeOfficialNumber(s, len, i);
        if (n < 0) {
            return m;
        }
        SkipSpacesUtf8(s, len, i);
        int markPos = i;
        int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
        int depth = DepthFromDiUnit(mark);
        if (depth > 0) {
            if (DiUnitIsChapter(mark)) {
                m.type = MarkerType::Chapter;
            } else if (mark == 0x8282) {
                m.type = MarkerType::Section;
            } else {
                m.type = MarkerType::Article;
            }
            m.number = n;
            m.prefixLength = i;
            m.rank = depth;
            // "第8条是…" / "第2条就是…" cites an item in running text, not 管理办法 第N条.
            if (m.type == MarkerType::Article) {
                int restPos = i;
                SkipSpacesUtf8(s, len, restPos);
                int r1 = restPos < len ? Utf8CodepointNext(s, len, restPos) : 0;
                bool shi = r1 == 0x662F;    // 是
                if (!shi && r1 == 0x5C31) { // 就
                    int r2 = restPos < len ? Utf8CodepointNext(s, len, restPos) : 0;
                    shi = r2 == 0x662F;
                }
                if (shi) {
                    // #region agent log
                    DbgFace09("N", "ExtractPdfToc.cpp:ParseHeadingMarker.articleShi", s, "article-citation");
                    // #endregion
                    HeadingMarker empty;
                    return empty;
                }
            }
            return m;
        }
        i = markPos;
        SkipSpacesUtf8(s, len, i);
        int commaPos = i;
        int comma = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (IsIdeoCommaCp(comma)) {
            m.type = MarkerType::DiYiComma;
            m.number = n;
            m.prefixLength = i;
            m.rank = 0;
            return m;
        }
        i = commaPos;
        if (mark == 0x7AE5) { // 童, OCR of 章
            i = markPos;
            Utf8CodepointNext(s, len, i);
            m.type = MarkerType::Chapter;
            m.number = n;
            m.prefixLength = i;
            m.rank = 1;
            return m;
        }
        return m;
    }
    if (cp == 0x5E8F) { // 序章 / 序篇
        SkipSpacesUtf8(s, len, i);
        int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (DiUnitIsChapter(mark)) {
            m.type = MarkerType::Chapter;
            m.number = 0;
            m.prefixLength = i;
            m.rank = 1;
            return m;
        }
        return m;
    }
    if (cp == 0x672B) { // 末章
        SkipSpacesUtf8(s, len, i);
        int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (DiUnitIsChapter(mark)) {
            m.type = MarkerType::Chapter;
            m.number = 0;
            m.prefixLength = i;
            m.rank = 1;
            return m;
        }
        return m;
    }
    if (IsParenOpenCp(cp)) {
        int inner = i;
        int firstInner = inner < len ? Utf8CodepointNext(s, len, inner) : 0;
        int tmp = i;
        if (ConsumeParenNumberingAfterOpen(s, len, tmp)) {
            int numAt = i;
            int n = ConsumeOfficialNumber(s, len, numAt);
            i = tmp;
            m.number = n > 0 ? n : 1;
            m.prefixLength = i;
            if (NextNonSpaceIsDunhao(s, len, i)) {
                HeadingMarker empty;
                return empty;
            }
            if (IsDigitCp(firstInner)) {
                // Books put printed pages in parens: "(144) 不适于…". 公文 clauses are
                // (1)(2)(3) or （十）. A two-digit+ Arabic paren is a page, not a level.
                if (n >= 10) {
                    HeadingMarker empty;
                    return empty;
                }
                m.type = MarkerType::ArabicParen;
                m.rank = 4;
            } else if (IsCnNumeral(firstInner) || IsOcrYiDashCp(firstInner)) {
                m.type = MarkerType::ChineseParen;
                m.rank = 2;
            } else {
                m.type = MarkerType::ChineseParen;
                m.rank = 3;
            }
            return m;
        }
        return m;
    }
    if (IsCnNumeral(cp)) {
        i = start;
        int n = ConsumeOfficialNumber(s, len, i);
        SkipSpacesUtf8(s, len, i);
        int sepPos = i;
        int sep = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (IsDunhaoSepCp(sep)) {
            m.type = MarkerType::ChineseDunhao;
            m.number = n > 0 ? n : 1;
            m.prefixLength = i;
            m.rank = 1;
            return m;
        }
        if (sep == 0x662F) { // 是
            m.type = MarkerType::YiShi;
            m.number = n > 0 ? n : 1;
            m.prefixLength = i;
            m.rank = 0;
            return m;
        }
        i = sepPos;
        return m;
    }
    if (IsDigitCp(cp)) {
        i = start;
        int dots = 0;
        int n = 0;
        while (i < len) {
            int save = i;
            int next = Utf8CodepointNext(s, len, i);
            if (IsDigitCp(next)) {
                n = n * 10 + DigitValue(next);
                continue;
            }
            if (next == '.' || next == 0xFF0E) {
                if (DottedFollowedByDate(s, len, i)) {
                    i = save;
                    break;
                }
                int after = i;
                int look = after < len ? Utf8CodepointNext(s, len, after) : 0;
                if (IsDigitCp(look)) {
                    // "2.10" stays dotted; "2.12333电话…" is a list "2." plus a phone/ID run.
                    if (CountAsciiDigitsFrom(s, len, i) >= 4) {
                        i = save;
                        break;
                    }
                    dots++;
                    i = after;
                    n = DigitValue(look);
                    continue;
                }
                i = save;
                break;
            }
            if (next == 0x3001) {
                i = save;
                break;
            }
            i = save;
            break;
        }
        if (dots >= 1) {
            if (!HasLetterOrCjk(s + i)) {
                return m;
            }
            int leadAt = start;
            int lead = leadAt < len ? Utf8CodepointNext(s, len, leadAt) : 0;
            // Table scores "0.1分" / "0.2 政务数据…" are not 1.1-style sections.
            if (lead == '0' || lead == 0xFF10) {
                return m;
            }
            if (LooksLikeAmountTail(s + i) || LooksLikeDomainOrEmailFragment(s + i) ||
                LooksLikeNumericScheduleDate(s)) {
                // #region agent log
                if (DbgFace09Hit(s) || LooksLikeNumericScheduleDate(s)) {
                    DbgFace09("N", "ExtractPdfToc.cpp:ParseHeadingMarker.dotted.reject", s,
                              LooksLikeNumericScheduleDate(s) ? "schedule-date" : "domain-or-amount");
                }
                // #endregion
                return m;
            }
            if (NextNonSpaceIsDunhao(s, len, i)) {
                return m;
            }
            m.type = MarkerType::ArabicDot;
            m.number = n;
            m.prefixLength = i;
            m.rank = dots + 1;
            // #region agent log
            if (Dbg92Interesting(s) || str::Find(s, "万")) {
                char extra[192];
                snprintf(extra, (int)sizeof(extra), "dotted n=%d dots=%d rank=%d rest=%.48s", n, dots, m.rank, s + i);
                Dbg92a48e("C", "ExtractPdfToc.cpp:ParseHeadingMarker.dotted", s, extra);
            }
            // #endregion
            return m;
        }
        SkipSpacesUtf8(s, len, i);
        int save = i;
        int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (IsSimpleArabicListSepCp(mark)) {
            const char* rest = s + i;
            if (!HasLetterOrCjk(rest) && !LooksLikeUrlStart(rest)) {
                return m;
            }
            if (LooksLikeAmountTail(rest) || LooksLikeDomainOrEmailFragment(rest)) {
                // #region agent log
                if (Dbg92Interesting(s) || str::Find(s, "万") || DbgFace09Hit(s)) {
                    Dbg92a48e("B", "ExtractPdfToc.cpp:ParseHeadingMarker.simpleDot.rejectAmount", s, "rejected");
                    DbgFace09("N", "ExtractPdfToc.cpp:ParseHeadingMarker.simpleDot.reject", s, "domain-or-amount");
                }
                // #endregion
                return m;
            }
            m.type = MarkerType::ArabicDot;
            m.number = n;
            m.prefixLength = i;
            m.rank = 3;
            // #region agent log
            if (Dbg92Interesting(s) || str::Find(s, "万")) {
                char extra[192];
                snprintf(extra, (int)sizeof(extra), "simpleDot n=%d rest=%.48s", n, rest ? rest : "");
                Dbg92a48e("B", "ExtractPdfToc.cpp:ParseHeadingMarker.simpleDot", s, extra);
            }
            // #endregion
            return m;
        }
        i = save;
        return m;
    }
    return m;
}

static int HeadingLevelFromText(const char* s) {
    if (!s || !s[0]) {
        return 0;
    }
    if (str::StartsWithI(s, "chapter") || str::StartsWithI(s, "part ") || str::StartsWithI(s, "appendix")) {
        return 1;
    }
    if (str::StartsWithI(s, "section")) {
        return 2;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp <= 0) {
        return 0;
    }
    // 总序
    if (cp == 0x603B) {
        int cp2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (cp2 == 0x5E8F) {
            return 1;
        }
    }
    // 后记
    if (cp == 0x540E) {
        int j = i;
        int cp2 = j < len ? Utf8CodepointNext(s, len, j) : 0;
        if (cp2 == 0x8BB0) {
            return 1;
        }
    }
    if (str::Find(s, "\xE5\x8F\x82\xE8\x80\x83\xE6\x96\x87\xE7\x8C\xAE")) { // 参考文献
        return 1;
    }
    // 前言
    if (cp == 0x524D) {
        int j = i;
        int cp2 = j < len ? Utf8CodepointNext(s, len, j) : 0;
        if (cp2 == 0x8A00) {
            return 1;
        }
    }
    if (StartsWithXinDeHeading(s)) {
        return 1;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    return m.rank;
}

// Numbered 公文 headings may skip a level (一、 then 1. with no （一）).
// Only font-guessed headings are squeezed into consecutive outline depths.
static int ClampOutlineLevel(int numbered, int lvl, int prevLevel, bool hasPrev) {
    if (lvl < 1) {
        return lvl;
    }
    if (numbered < 1 && hasPrev && lvl > prevLevel + 1) {
        lvl = prevLevel + 1;
    }
    if (lvl > 6) {
        lvl = 6;
    }
    return lvl;
}

struct ParsedNumbering {
    char raw[40] = {};
    int comp[4] = {};
    int nComp = 0;
    int depth = 0;
    bool isChapter = false;
    bool hadTrailingDot = false;
};

static void ParseHeadingNumbering(const char* s, ParsedNumbering* out) {
    out->raw[0] = 0;
    out->nComp = 0;
    out->depth = 0;
    out->isChapter = false;
    out->hadTrailingDot = false;
    for (int k = 0; k < 4; k++) {
        out->comp[k] = 0;
    }
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int save = i;
        int c = Utf8CodepointNext(s, len, i);
        if (c > 32 && c != 0x3000) {
            i = save;
            break;
        }
    }
    int numStart = i;
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp <= 0) {
        return;
    }
    if (cp == 0x7B2C) {
        SkipSpacesUtf8(s, len, i);
        int n = 0;
        int nDigits = 0;
        while (i < len) {
            int save = i;
            int next = Utf8CodepointNext(s, len, i);
            if (IsDigitCp(next)) {
                n = n * 10 + DigitValue(next);
                nDigits++;
                continue;
            }
            if (IsCnNumeral(next)) {
                int cv = CnNumeralValue(next);
                if (cv == 10 && n == 0) {
                    n = 10;
                } else if (n == 10 && cv > 0 && cv < 10) {
                    n += cv;
                } else if (n == 0 && cv > 0) {
                    n = cv;
                }
                nDigits++;
                continue;
            }
            i = save;
            break;
        }
        SkipSpacesUtf8(s, len, i);
        int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
        int depth = DepthFromDiUnit(mark);
        if (nDigits > 0 && (depth > 0 || mark == 0 || mark == 0x7AE5)) {
            out->isChapter = mark == 0 || mark == 0x7AE5 ? true : DiUnitIsChapter(mark);
            out->nComp = 1;
            out->comp[0] = n;
            out->depth = mark == 0 || mark == 0x7AE5 ? 1 : depth;
            int rawLen = i - numStart;
            if (rawLen > 0 && rawLen < (int)sizeof(out->raw)) {
                memcpy(out->raw, s + numStart, (size_t)rawLen);
                out->raw[rawLen] = 0;
            }
            return;
        }
        return;
    }
    if (!IsDigitCp(cp)) {
        return;
    }
    int v = DigitValue(cp);
    int nDig = 1;
    while (i < len && nDig < 4 && out->nComp < 4) {
        int save = i;
        int next = Utf8CodepointNext(s, len, i);
        if (IsDigitCp(next)) {
            v = v * 10 + DigitValue(next);
            nDig++;
            continue;
        }
        if (next == '.' || next == 0xFF0E) {
            int after = i;
            int look = after < len ? Utf8CodepointNext(s, len, after) : 0;
            if (IsDigitCp(look) && DottedFollowedByDate(s, len, i)) {
                out->comp[out->nComp++] = v;
                out->hadTrailingDot = true;
                nDig = 0;
                break;
            }
            // "1.12333电话…" is list "1." plus a phone/ID run, not section 1.1233.
            if (IsDigitCp(look) && CountAsciiDigitsFrom(s, len, i) >= 4) {
                out->comp[out->nComp++] = v;
                out->hadTrailingDot = true;
                nDig = 0;
                break;
            }
            out->comp[out->nComp++] = v;
            v = 0;
            nDig = 0;
            if (IsDigitCp(look)) {
                i = after;
                v = DigitValue(look);
                nDig = 1;
                continue;
            }
            out->hadTrailingDot = true;
            i = save;
            break;
        }
        i = save;
        break;
    }
    if (nDig > 0 && out->nComp < 4) {
        out->comp[out->nComp++] = v;
    }
    int rawLen = i - numStart;
    if (rawLen > 0 && rawLen < (int)sizeof(out->raw)) {
        memcpy(out->raw, s + numStart, (size_t)rawLen);
        out->raw[rawLen] = 0;
    }
    if (out->nComp >= 2) {
        out->depth = out->nComp;
    } else if (out->nComp == 1 && out->hadTrailingDot) {
        out->depth = 3;
    }
}

static bool NumberingIsBareArabicChapter(const ParsedNumbering& num, const char* title) {
    if (num.nComp != 1 || num.hadTrailingDot || num.isChapter || num.comp[0] < 1) {
        return false;
    }
    if (!title || !num.raw[0]) {
        return false;
    }
    int len = (int)str::Len(title);
    int start = 0;
    SkipSpacesUtf8(title, len, start);
    int first = start < len ? Utf8CodepointNext(title, len, start) : 0;
    if (!IsDigitCp(first)) {
        return false;
    }
    int n = (int)str::Len(num.raw);
    if (n >= len) {
        return false;
    }
    int i = n;
    int cp = Utf8CodepointNext(title, len, i);
    if (cp > 32 && cp != 0x3000) {
        return false;
    }
    return HasLetterOrCjk(title + i);
}

static int LevelFromPrintedTitle(const char* title) {
    ParsedNumbering num;
    ParseHeadingNumbering(title, &num);
    if (num.isChapter || NumberingIsBareArabicChapter(num, title)) {
        return 1;
    }
    if (num.depth > 0) {
        return num.depth;
    }
    int hl = HeadingLevelFromText(title);
    if (hl > 0) {
        return hl;
    }
    if (num.nComp == 1) {
        return 1;
    }
    return 1;
}

static bool StartsWithXinDeHeading(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int c1 = i < len ? Utf8CodepointNext(s, len, i) : 0;
    int c2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (c1 != 0x5FC3 || c2 != 0x5F97) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    int n = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (IsCnNumeral(n) || IsDigitCp(n) || IsParenOpenCp(n)) {
        return true;
    }
    // OCR often reads 心得一 as 心得－ / 心得—.
    return n == 0xFF0D || n == 0x2013 || n == 0x2014 || n == 0x2015 || n == '-';
}

static bool LineLooksLikeBookPartTitle(const char* s) {
    if (!s || !s[0] || LooksLikePrintedTocHeading(s) || StartsWithXinDeHeading(s)) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 4 || g > 16) {
        return false;
    }
    if (!HasLetterOrCjk(s)) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::None) {
        return false;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    if (num.nComp >= 1) {
        return false;
    }
    return !str::Find(s, "，") && !str::Find(s, "。");
}

static bool LineLooksLikeChapterSubtitle(const char* s) {
    if (!s || !s[0] || LooksLikePrintedTocHeading(s) || StartsWithXinDeHeading(s)) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::None || HeadingLevelFromText(s) >= 1) {
        return false;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    if (num.nComp >= 1) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 4 || g > 18) {
        return false;
    }
    if (!HasLetterOrCjk(s)) {
        return false;
    }
    if (str::Find(s, "，") || str::Find(s, "。") || str::Find(s, "？") || str::Find(s, "?") || str::Find(s, "！") ||
        str::Find(s, "是错误的") || str::StartsWith(s, "认为")) {
        return false;
    }
    return true;
}

static void StripLeadingSubtitleDash(char** titleOut) {
    char* s = *titleOut;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp == '~' || cp == 0xFF5E || cp == 0x2014 || cp == 0x2013 || cp == 0xFF0D || cp == '-' || cp == 0x2500 ||
            cp == 0x2015) {
            continue;
        }
        i = save;
        break;
    }
    if (i < 1) {
        return;
    }
    memmove(s, s + i, (size_t)(len - i + 1));
    str::TrimWSInPlace(s, str::TrimOpt::Both);
}

static bool BookTitleIsSpine(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (str::StartsWithI(s, "chapter") || str::StartsWithI(s, "part ")) {
        return true;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    if (num.isChapter) {
        return true;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type == MarkerType::Chapter) {
        return true;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp != 0x7B2C) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    int n = ConsumeOfficialNumber(s, len, i);
    if (n < 0) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return mark == 0x8BB2 || mark == 0x8BFE || mark == 0x5377; // 讲 课 卷
}

static int BookSpineNumber(const char* s) {
    if (!s || !s[0]) {
        return 0;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    if (num.comp[0] > 0 && (num.isChapter || BookTitleIsSpine(s))) {
        return num.comp[0];
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type == MarkerType::Chapter && m.number > 0) {
        return m.number;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp != 0x7B2C) {
        return num.comp[0] > 0 ? num.comp[0] : 0;
    }
    SkipSpacesUtf8(s, len, i);
    int n = ConsumeOfficialNumber(s, len, i);
    return n > 0 ? n : 0;
}

static bool ParseBookLabelSerial(const char* s, int* prefixKey, int* numOut) {
    if (prefixKey) {
        *prefixKey = 0;
    }
    if (numOut) {
        *numOut = 0;
    }
    if (!s || !s[0] || BookTitleIsSpine(s)) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::None) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int preStart = i;
    int nPre = 0;
    while (i < len && nPre < 4) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp >= 0x4E00 && cp <= 0x9FFF && !IsCnNumeral(cp)) {
            nPre++;
            continue;
        }
        i = save;
        break;
    }
    if (nPre < 1) {
        return false;
    }
    int preEnd = i;
    SkipSpacesUtf8(s, len, i);
    int n = ConsumeOfficialNumber(s, len, i);
    if (n < 1) {
        return false;
    }
    unsigned uh = 0;
    for (int k = preStart; k < preEnd; k++) {
        uh = uh * 131u + (unsigned char)s[k];
    }
    if (prefixKey) {
        *prefixKey = (int)(uh % 100000u);
    }
    if (numOut) {
        *numOut = n;
    }
    return true;
}

static int BookPrintedSchemeKey(const char* title, int* numOut) {
    if (numOut) {
        *numOut = 0;
    }
    if (!title || !title[0]) {
        return 0;
    }
    HeadingMarker m = ParseHeadingMarker(title);
    if (m.type != MarkerType::None && m.number > 0) {
        if (numOut) {
            *numOut = m.number;
        }
        switch (m.type) {
            case MarkerType::Chapter:
                return 10;
            case MarkerType::Appendix:
                return 15;
            case MarkerType::FormTable:
                return 18;
            case MarkerType::ChineseDunhao:
                return 20;
            case MarkerType::Section:
                return 25;
            case MarkerType::Article:
                return 28;
            case MarkerType::ChineseParen:
                return 30;
            case MarkerType::ArabicDot:
                return m.rank <= 2 ? 35 : 40;
            case MarkerType::ArabicParen:
                if (m.number >= 10) {
                    return 0;
                }
                return 50;
            default:
                break;
        }
    }
    ParsedNumbering num;
    ParseHeadingNumbering(title, &num);
    if (num.isChapter || BookTitleIsSpine(title)) {
        int spine = BookSpineNumber(title);
        if (numOut) {
            *numOut = spine > 0 ? spine : 1;
        }
        return 10;
    }
    if (num.nComp >= 2) {
        if (numOut) {
            *numOut = num.comp[num.nComp - 1];
        }
        return 35;
    }
    int prefixKey = 0;
    int serial = 0;
    if (ParseBookLabelSerial(title, &prefixKey, &serial)) {
        if (numOut) {
            *numOut = serial;
        }
        return 60 + (prefixKey % 30);
    }
    return 0;
}

static bool LooksLikeTocNumToken(const char* s) {
    if (!s || !s[0] || HasLetterOrCjk(s)) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 2 || g > 12) {
        return false;
    }
    if (LineLooksLikePageNumber(s) || ParseBarePrintedPage(s) > 0) {
        return false;
    }
    return HeadingLevelFromText(s) >= 2;
}

static void EnsureNumberingSpaceInTitle(char** titleOut) {
    char* s = *titleOut;
    if (!s || !s[0]) {
        return;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    if (!num.raw[0]) {
        return;
    }
    int n = (int)str::Len(num.raw);
    if (!s[n] || s[n] == ' ' || s[n] == '\t') {
        return;
    }
    int len = (int)str::Len(s);
    int after = n;
    int cp = after < len ? Utf8CodepointNext(s, len, after) : 0;
    if (cp == 0x3001 || cp == 0xFF0C || cp == 0xFF1A || cp == 0xFF1B || cp == 0x3002) {
        return;
    }
    char* neu = str::Join(num.raw, " ", s + n);
    if (!neu) {
        return;
    }
    str::Free(s);
    *titleOut = neu;
}

static void NormalizeDiUnitComma(char** titleOut) {
    char* s = *titleOut;
    if (!s || !s[0]) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::Chapter || m.prefixLength < 1) {
        return;
    }
    int len = (int)str::Len(s);
    int next = m.prefixLength;
    SkipSpacesUtf8(s, len, next);
    int afterMark = next;
    int cp = Utf8CodepointNext(s, len, afterMark);
    if (cp != 0xFF0C && cp != ',' && cp != 0x3001) {
        return;
    }
    char prefix[64];
    if (m.prefixLength >= (int)sizeof(prefix)) {
        return;
    }
    memcpy(prefix, s, (size_t)m.prefixLength);
    prefix[m.prefixLength] = 0;
    char* neu = str::Join(prefix, " ", s + afterMark);
    if (!neu) {
        return;
    }
    str::Free(s);
    *titleOut = neu;
}

// Drop printed-TOC "．．．． (37)" / "……… （1 1)" glued onto a heading. Dest page
// is a bookmark field; it must not appear in the visible title.
static void StripTrailingGluedPage(char* s) {
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int scan = len;
    int last = Utf8CodepointPrev(s, len, scan);
    while (last > 0 && (last == ' ' || last == 0x3000)) {
        last = Utf8CodepointPrev(s, len, scan);
    }
    if (last == ')' || last == 0xFF09) {
        last = Utf8CodepointPrev(s, len, scan);
        while (last > 0 && (last == ' ' || last == 0x3000)) {
            last = Utf8CodepointPrev(s, len, scan);
        }
    }
    int nDig = 0;
    while (last > 0 && nDig < 8) {
        if (IsDigitCp(last)) {
            nDig++;
            last = Utf8CodepointPrev(s, len, scan);
            int holdScan = scan;
            int holdLast = last;
            while (last > 0 && (last == ' ' || last == 0x3000)) {
                last = Utf8CodepointPrev(s, len, scan);
            }
            if (!IsDigitCp(last)) {
                scan = holdScan;
                last = holdLast;
                break;
            }
            continue;
        }
        break;
    }
    if (nDig < 1 || nDig > 4) {
        return;
    }
    while (last > 0 && (IsLeaderCp(last) || last == ')' || last == 0xFF09 || last == '(' || last == 0xFF08 ||
                        last == 0x3008 || last == 0x3009)) {
        last = Utf8CodepointPrev(s, len, scan);
    }
    if (last <= 0) {
        return;
    }
    int end = scan;
    Utf8CodepointNext(s, len, end);
    char save = s[end];
    s[end] = 0;
    if (!HasLetterOrCjk(s)) {
        s[end] = save;
        return;
    }
    str::TrimWSInPlace(s, str::TrimOpt::Both);
}

static void PolishPrintedHitTitle(char** titleOut) {
    EnsureNumberingSpaceInTitle(titleOut);
    NormalizeDiUnitComma(titleOut);
    if (titleOut && *titleOut) {
        StripTrailingGluedPage(*titleOut);
    }
}

static float MedianPositive(Vec<float>& v) {
    int n = v.Size();
    if (n < 1) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (v[j] < v[i]) {
                float t = v[i];
                v[i] = v[j];
                v[j] = t;
            }
        }
    }
    return v[n / 2];
}

static void FreeScanLines(Vec<ScanLine>& lines) {
    for (int i = 0; i < lines.Size(); i++) {
        str::Free(lines[i].text);
        lines[i].text = nullptr;
    }
    lines.Reset();
}

static void RebuildVisualLines(Vec<ScanLine>& pageLines);

static int LeadingDirtDotBytes(const char* s, const Rect* coords, int n, int* dx0Out, int* dx1Out, int* sameOut) {
    if (dx0Out) {
        *dx0Out = 0;
    }
    if (dx1Out) {
        *dx1Out = 0;
    }
    if (sameOut) {
        *sameOut = 0;
    }
    if (!s || n < 1) {
        return 0;
    }
    int i = 0;
    int cp0 = Utf8CodepointNext(s, n, i);
    if (!IsListBulletCp(cp0) || i >= n) {
        return 0;
    }
    if (ParseHeadingMarker(s + i).rank < 1) {
        return 0;
    }
    int j = i;
    int cp1 = j < n ? Utf8CodepointNext(s, n, j) : 0;
    int cp2 = j < n ? Utf8CodepointNext(s, n, j) : 0;
    Rect r0 = coords ? coords[0] : Rect{};
    Rect r1 = (coords && i < n) ? coords[i] : Rect{};
    if (dx0Out) {
        *dx0Out = r0.dx;
    }
    if (dx1Out) {
        *dx1Out = r1.dx;
    }
    bool same = r0.dx > 0 && r0.x == r1.x && r0.dx == r1.dx && r0.y == r1.y;
    if (sameOut) {
        *sameOut = same ? 1 : 0;
    }
    bool periodAfterDigit = IsDigitCp(cp1) && IsListBulletCp(cp2);
    bool tiny = r0.dx > 0 && r1.dx > 0 && !same && r0.dx * 2 <= r1.dx;
    bool overlap = r0.dx > 0 && r1.dx > 0 && !same && r0.x + r0.dx > r1.x + r1.dx / 4;
    if (periodAfterDigit || tiny || overlap || same) {
        return i;
    }
    return 0;
}

static bool AppendUtf8ScanLine(const char* text, const Rect* coords, int start, int end, int pageNo,
                               Vec<ScanLine>& out) {
    if (!text || !coords || end <= start) {
        return false;
    }
    int n = end - start;
    int dx0 = 0, dx1 = 0, sameBox = 0;
    int skip = LeadingDirtDotBytes(text + start, coords + start, n, &dx0, &dx1, &sameBox);
    int from = start + skip;
    if (from >= end) {
        return false;
    }
    Rect bbox;
    bool has = false;
    float hSum = 0;
    int nH = 0;
    for (int k = from; k < end; k++) {
        Rect r = coords[k];
        if (r.dx || r.x) {
            if (!has) {
                bbox = r;
                has = true;
            } else {
                bbox = bbox.Union(r);
            }
            if (r.dy > 0) {
                hSum += (float)r.dy;
                nH++;
            }
        }
    }
    ScanLine sl;
    sl.text = str::Dup(text + from, (size_t)(end - from));
    str::TrimWSInPlace(sl.text, str::TrimOpt::Both);
    if (!sl.text[0] || LooksLikeArchiveJunk(sl.text)) {
        str::Free(sl.text);
        return false;
    }
    sl.srcPage = pageNo;
    sl.x = (float)bbox.x;
    sl.y = (float)bbox.y;
    sl.dx = (float)bbox.dx;
    sl.dy = (float)bbox.dy;
    sl.fontSize = nH > 0 ? hSum / (float)nH : (float)bbox.dy;
    sl.bold = false;
    out.Append(sl);
    return true;
}

// Rightmost large x-gap whose right span is a printed page token (13 / ··13 / (13)).
static int FindTocPageSpanSplit(const char* text, const Rect* coords, int start, int end) {
    if (!text || !coords || end - start < 3) {
        return -1;
    }
    float dxSum = 0;
    int nDx = 0;
    Rect prev{};
    bool have = false;
    int bestSplit = -1;
    int i = start;
    while (i < end) {
        unsigned char b = (unsigned char)text[i];
        bool glyphStart = (b & 0xC0) != 0x80;
        if (glyphStart) {
            Rect r = coords[i];
            if (r.dx > 0) {
                dxSum += (float)r.dx;
                nDx++;
            }
            if (have && (r.dx || r.x)) {
                float gap = (float)r.x - ((float)prev.x + (float)prev.dx);
                float avg = nDx > 0 ? dxSum / (float)nDx : 8.f;
                float need = avg * 2.5f;
                if (need < 20.f) {
                    need = 20.f;
                }
                if (gap >= need) {
                    bestSplit = i;
                }
            }
            if (r.dx || r.x) {
                prev = r;
                have = true;
            }
        }
        i++;
    }
    if (bestSplit <= start || bestSplit >= end) {
        return -1;
    }
    char* left = str::Dup(text + start, (size_t)(bestSplit - start));
    char* right = str::Dup(text + bestSplit, (size_t)(end - bestSplit));
    str::TrimWSInPlace(left, str::TrimOpt::Both);
    str::TrimWSInPlace(right, str::TrimOpt::Both);
    bool ok = left[0] && right[0] && HasLetterOrCjk(left) && LineLooksLikePageNumber(right);
    str::Free(left);
    str::Free(right);
    return ok ? bestSplit : -1;
}

static void CollectLinesFromUtf8(const char* text, Rect* coords, int len, int pageNo, Vec<ScanLine>& out) {
    if (!text || !coords || len <= 0) {
        return;
    }
    int i = 0;
    while (i < len) {
        while (i < len && text[i] == '\n') {
            i++;
        }
        if (i >= len) {
            break;
        }
        int start = i;
        while (i < len && text[i] != '\n') {
            i++;
        }
        if (i - start < 1) {
            continue;
        }
        int split = FindTocPageSpanSplit(text, coords, start, i);
        if (split > start) {
            AppendUtf8ScanLine(text, coords, start, split, pageNo, out);
            AppendUtf8ScanLine(text, coords, split, i, pageNo, out);
        } else {
            AppendUtf8ScanLine(text, coords, start, i, pageNo, out);
        }
    }
}

static int ScanLinesGlyphCount(const Vec<ScanLine>& page) {
    int n = 0;
    for (int i = 0; i < page.Size(); i++) {
        n += GlyphCount(page[i].text);
    }
    return n;
}

// Sideways 报名表 / 清单. Prefer OCR after 90°/270°.
// A) native stext is one glyph per tall box (90° text matrix).
// B) scanned landscape table with a shattered upright overlay: dozens of
//    1–4 glyph chips and almost no prose (e.g. 附件 continuation pages).
//    Skip B when the page already has /Rotate 90/270: a portrait 审批表
//    (姓名/关系 cells) looks like chips after a wrong 90 baked over 270.
static bool ScanLinesLookSideways(const Vec<ScanLine>& page, bool afterSideways = false,
                                  bool allowShatteredOverlay = true) {
    int n = 0;
    int tall = 0;
    int shortG = 0;
    int short4 = 0;
    int long8 = 0;
    for (int i = 0; i < page.Size(); i++) {
        if (!page[i].text || !page[i].text[0]) {
            continue;
        }
        n++;
        int g = GlyphCount(page[i].text);
        if (g <= 2) {
            shortG++;
        }
        if (g <= 4) {
            short4++;
        }
        if (g >= 8) {
            long8++;
        }
        if (page[i].dy > page[i].dx * 1.4f && page[i].dy > 10.f) {
            tall++;
        }
    }
    // A portrait Chinese cover or a page full of round seals also has many
    // one-glyph tall boxes. It cannot establish the first rotated page by
    // itself; only continue an already confirmed landscape table run.
    if (afterSideways && n >= 6 && shortG * 2 >= n && tall * 2 >= n) {
        return true;
    }
    // 公文 body is ~15–25 long lines; these pages have 100+ chips.
    int minChips = afterSideways ? 20 : 50;
    if (allowShatteredOverlay && afterSideways && n >= minChips && short4 * 5 >= n * 4 && long8 * 20 < n) {
        return true;
    }
    return false;
}

static bool CpIsCommonCnProse(int cp);
static bool FileNameHasOfficialKind(const char* filePath);

// Upright 竖版书: tall CJK columns with prose, not a sideways 报名表.
static bool ScanLinesLookLikeVerticalBook(const Vec<ScanLine>& page) {
    int n = 0;
    int tall = 0;
    int long8 = 0;
    int common = 0;
    for (int i = 0; i < page.Size(); i++) {
        if (!page[i].text || !page[i].text[0]) {
            continue;
        }
        n++;
        int g = GlyphCount(page[i].text);
        if (g >= 8) {
            long8++;
        }
        if (page[i].dy > page[i].dx * 1.4f && page[i].dy > 10.f) {
            tall++;
        }
        int len = (int)str::Len(page[i].text);
        int b = 0;
        while (b < len) {
            int cp = Utf8CodepointNext(page[i].text, len, b);
            if (cp <= 0) {
                break;
            }
            if (CpIsCommonCnProse(cp)) {
                common++;
            }
        }
    }
    if (n < 8 || tall * 2 < n) {
        return false;
    }
    if (common < 3 && long8 < 2) {
        return false;
    }
    return true;
}

// Fangzheng / Identity-H CJK with no ToUnicode: MuPDF emits dingbats, bopomofo,
// enclosed numbers, or random Han. Looks like a text layer, so Auto OCR skips it.
static bool CpIsHanUnified(int cp) {
    return (cp >= 0x4E00 && cp <= 0x9FFF) || (cp >= 0x3400 && cp <= 0x4DBF);
}

static bool CpIsCommonCnProse(int cp) {
    switch (cp) {
        case 0x7684: // 的
        case 0x662F: // 是
        case 0x4E86: // 了
        case 0x4E0D: // 不
        case 0x5728: // 在
        case 0x4EBA: // 人
        case 0x6709: // 有
        case 0x4E2D: // 中
        case 0x5927: // 大
        case 0x548C: // 和
        case 0x5DE5: // 工
        case 0x4F5C: // 作
        case 0x5E74: // 年
        case 0x53D1: // 发
        case 0x5C55: // 展
            return true;
        default:
            return false;
    }
}

static bool CpIsCidMappedJunk(int cp) {
    if (cp == 0xFFFD) {
        return true;
    }
    if (cp < 0x20) {
        return cp != '\t' && cp != '\n' && cp != '\r';
    }
    if (cp >= 0x7F && cp < 0xA0) {
        return true;
    }
    if (cp >= 0x2700 && cp <= 0x27BF) {
        return true;
    }
    if (cp >= 0x2460 && cp <= 0x24FF) {
        return true;
    }
    if (cp >= 0x3200 && cp <= 0x32FF) {
        return true;
    }
    if ((cp >= 0x3100 && cp <= 0x312F) || (cp >= 0x31A0 && cp <= 0x31BF)) {
        return true;
    }
    if (cp >= 0x2E80 && cp <= 0x2FDF) {
        return true;
    }
    if (cp >= 0xE000 && cp <= 0xF8FF) {
        return true;
    }
    if (cp >= 0x1950 && cp <= 0x197F) {
        return true;
    }
    if (cp >= 0x1200 && cp <= 0x137F) {
        return true;
    }
    if (cp >= 0x1000 && cp <= 0x109F) {
        return true;
    }
    return false;
}

static bool ScanLineHasUsableOfficialMarker(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (LooksLikePrintedTocHeading(s)) {
        return true;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    return m.type == MarkerType::ChineseDunhao || m.type == MarkerType::ChineseParen || m.type == MarkerType::Chapter ||
           m.type == MarkerType::Section || m.type == MarkerType::Article || m.type == MarkerType::Appendix ||
           m.type == MarkerType::FormTable;
}

// Identity-H maps the right glyph to the wrong Han: 人社→人汴, 通办→通亦, 部门→部11.
// A page can still have 一、 / （二） / 1. so we must not treat a marker as "good text".
static bool OfficialHeadingRestLooksLikeCidMash(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    const char* rest = (m.rank >= 1 && m.prefixLength > 0) ? s + m.prefixLength : s;
    int rlen = (int)str::Len(rest);
    int ri = 0;
    SkipSpacesUtf8(rest, rlen, ri);
    rest += ri;
    if (!rest[0]) {
        return false;
    }
    if (str::Find(rest, "人汴") || str::Find(rest, "通亦") || str::Find(rest, "对林") || str::Find(rest, "推阐") ||
        str::Find(rest, "部11") || str::Find(rest, "合量子") || str::Find(rest, "｜") || str::Find(rest, "|")) {
        return true;
    }
    return false;
}

static bool ScanLinesLookLikeCidFontGarbage(const Vec<ScanLine>& page) {
    int nGlyph = 0;
    int nHan = 0;
    int nJunk = 0;
    int nCommon = 0;
    int nMash = 0;
    int nMarker = 0;
    for (int i = 0; i < page.Size(); i++) {
        const char* s = page[i].text;
        if (!s || !s[0]) {
            continue;
        }
        if (ScanLineHasUsableOfficialMarker(s) || ParseHeadingMarker(s).rank >= 1) {
            nMarker++;
            if (OfficialHeadingRestLooksLikeCidMash(s)) {
                nMash++;
            }
        }
        int len = (int)str::Len(s);
        int b = 0;
        while (b < len) {
            int cp = Utf8CodepointNext(s, len, b);
            if (cp <= 0) {
                break;
            }
            if (cp <= 32 || cp == 0x3000) {
                continue;
            }
            nGlyph++;
            if (CpIsCidMappedJunk(cp)) {
                nJunk++;
            }
            if (CpIsHanUnified(cp)) {
                nHan++;
                if (CpIsCommonCnProse(cp)) {
                    nCommon++;
                }
            }
        }
    }
    if (nMash >= 2 && nMarker >= 2) {
        return true;
    }
    if (nGlyph < 12) {
        return false;
    }
    if (nJunk >= 6 && nJunk * 2 >= nCommon + 1) {
        return true;
    }
    // Landscape 一本账 / 报名表 tables have lots of Han and almost no 的/是/了.
    // That is not Identity-H garbage; extract must not OCR those pages.
    if (nGlyph >= 80 && nJunk < 3 && nMash < 1) {
        return false;
    }
    if (nHan >= 20 && nCommon < 2) {
        return true;
    }
    if (nHan >= 40 && nCommon * 10 < nHan) {
        return true;
    }
    return false;
}

static int CidGarbageOcrFrontPageCap(int nPages) {
    // Short 公文/问答 (≤24pp) must OCR every CID page; 19. on p.13 is not "front matter".
    if (nPages <= 24) {
        return nPages;
    }
    int cap = nPages * kExtractPdfToc.tocSearchPct / 100;
    if (cap < kExtractPdfToc.tocSearchMinPages) {
        cap = kExtractPdfToc.tocSearchMinPages;
    }
    if (cap < 12) {
        cap = 12;
    }
    if (cap > 16) {
        cap = 16;
    }
    if (nPages < cap) {
        return nPages;
    }
    return cap;
}

static void CollectPageScanLines(EngineBase* engine, int pageNo, Vec<ScanLine>& out) {
    Vec<ScanLine> page;
    Vec<EngineMupdfPageLine> raw;
    bool gotRaw = EngineMupdfCollectPageLines(engine, pageNo, raw);
    if (gotRaw) {
        for (int i = 0; i < raw.Size(); i++) {
            ScanLine sl;
            sl.text = raw[i].text;
            raw[i].text = nullptr;
            sl.srcPage = pageNo;
            sl.x = raw[i].x;
            sl.y = raw[i].y;
            sl.dx = raw[i].dx;
            sl.dy = raw[i].dy;
            sl.fontSize = raw[i].fontSize;
            sl.bold = raw[i].bold;
            if (!sl.text || LooksLikeArchiveJunk(sl.text)) {
                str::Free(sl.text);
                continue;
            }
            page.Append(sl);
        }
    }
    EngineMupdfFreePageLines(raw);
    // File stext we just collected. Do not use PageHasUsableText here — that
    // only looks at the text cache (empty at extract start, or filled by OCR).
    bool fewNative = ScanLinesGlyphCount(page) < 20;
    bool cidGarbage = ScanLinesLookLikeCidFontGarbage(page);
    bool fileLayerOk = !fewNative && !cidGarbage;
    int cidCap = engine ? CidGarbageOcrFrontPageCap(engine->PageCount()) : 0;
    // Full-document OCR is scheduled before asynchronous TOC extraction. Do
    // not OCR again here: a long table-heavy PDF would be recognized twice,
    // making bookmark extraction slower than the original document scan.
    if (!fileLayerOk && engine && engine->HasCachedOcrText(pageNo)) {
        for (int i = 0; i < page.Size(); i++) {
            str::Free(page[i].text);
            page[i].text = nullptr;
        }
        page.Reset();
        int len = 0;
        Rect* coords = nullptr;
        const char* text = nullptr;
        if (engine->TryGetTextForPageUtf8(pageNo, &len, &coords, &text) && text && coords && len > 0) {
            CollectLinesFromUtf8(text, coords, len, pageNo, page);
        }
    }
    if (page.Size() < 1 && engine) {
        int len = 0;
        Rect* coords = nullptr;
        const char* text = nullptr;
        if (engine->TryGetTextForPageUtf8(pageNo, &len, &coords, &text) && text && coords && len > 0) {
            CollectLinesFromUtf8(text, coords, len, pageNo, page);
        }
    }
    if (cidGarbage && !(engine && engine->HasCachedOcrText(pageNo))) {
        // If the page already carries some Han glyphs (OCR text was merged
        // into searchStext), do not drop. Mixed Identity-H + OCR pages like
        // the 附件4/5 sheets must keep their OCR titles.
        int nHanHere = 0;
        for (int i = 0; i < page.Size(); i++) {
            const char* s = page[i].text;
            if (!s) continue;
            int len = (int)str::Len(s), b = 0;
            while (b < len) {
                int cp = Utf8CodepointNext(s, len, b);
                if (cp <= 0) break;
                if (CpIsHanUnified(cp)) nHanHere++;
            }
        }
        if (nHanHere >= 5) {
            // Keep page — has enough OCR Han to be useful.
        } else if (pageNo <= cidCap) {
            for (int i = 0; i < page.Size(); i++) {
                str::Free(page[i].text);
                page[i].text = nullptr;
            }
            page.Reset();
            return;
        }
    }
    if (page.Size() < 1) {
        return;
    }
    char tracePath[MAX_PATH]{};
    if (pageNo == 4 && GetEnvironmentVariableA("SUMATRA_TOC_TRACE", tracePath, dimof(tracePath)) > 0) {
        str::BufAppend(tracePath, dimof(tracePath), ".raw");
        FILE* trace = _wfopen(ToWStrTemp(tracePath), L"w");
        if (trace) {
            fprintf(trace, "MuPDF text lines before RebuildVisualLines, page=%d count=%d\n", pageNo, page.Size());
            for (int i = 0; i < page.Size(); i++) {
                const ScanLine& line = page[i];
                fprintf(trace, "R idx=%d x=%.1f y=%.1f dx=%.1f dy=%.1f text=%s\n", i, line.x, line.y, line.dx, line.dy,
                        line.text ? line.text : "");
            }
            fclose(trace);
        }
    }
    RebuildVisualLines(page);
    for (int i = 0; i < page.Size(); i++) {
        RewriteOcrAppendixBang(&page[i].text);
        RewriteOcrLetterAsListOne(&page[i].text);
        RewriteOcrDashAsYiDunhao(&page[i].text);
        RewriteOcrGraveAsDunhao(&page[i].text);
    }
    // #region agent log
    for (int i = 0; i < page.Size(); i++) {
        const char* t = page[i].text;
        if (!Dbg92Interesting(t)) {
            continue;
        }
        char cps[256];
        Dbg92Cps(cps, (int)sizeof(cps), t, 14);
        char extra[320];
        snprintf(extra, (int)sizeof(extra), "p=%d cps=%s file=%s", pageNo, cps,
                 engine && engine->FilePath() ? engine->FilePath() : "");
        Dbg92a48e("A", "ExtractPdfToc.cpp:CollectPageScanLines", t, extra);
    }
    for (int i = 0; i < page.Size(); i++) {
        const char* t = page[i].text;
        if (!DbgFace09Hit(t)) {
            continue;
        }
        char extra[192];
        snprintf(extra, (int)sizeof(extra), "p=%d x=%.1f y=%.1f dx=%.1f dy=%.1f fs=%.1f", pageNo, page[i].x, page[i].y,
                 page[i].dx, page[i].dy, page[i].fontSize);
        DbgFace09("A", "ExtractPdfToc.cpp:CollectPageScanLines", t, extra);
    }
    // #endregion
    for (int i = 0; i < page.Size(); i++) {
        out.Append(page[i]);
        page[i].text = nullptr;
    }
}

static int MapPrintedPage(EngineBase* engine, int printed, const Vec<char*>& labels) {
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", printed);
    for (int i = 0; i < labels.Size(); i++) {
        if (labels[i] && str::Eq(labels[i], buf)) {
            return i + 1;
        }
    }
    if (printed >= 1 && engine && printed <= engine->PageCount()) {
        return printed;
    }
    return 0;
}

static void FindDestOnPage(const Vec<ScanLine>& lines, int destPage, const char* title, float* x, float* y) {
    *x = 0;
    *y = 0;
    if (!title || destPage < 1) {
        return;
    }
    int best = -1;
    for (int i = 0; i < lines.Size(); i++) {
        const ScanLine& sl = lines[i];
        if (sl.srcPage != destPage || !sl.text) {
            continue;
        }
        if (str::StartsWith(sl.text, title) || str::Find(sl.text, title)) {
            best = i;
            break;
        }
    }
    if (best >= 0) {
        *x = lines[best].x;
        *y = lines[best].y;
    }
}

static void StripLeadingListBullet(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int bulletStart = i;
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsListBulletCp(cp)) {
        return;
    }
    SkipSpacesUtf8(s, len, i);
    if (i <= bulletStart || ParseHeadingMarker(s + i).rank < 1) {
        return;
    }
    memmove(s + bulletStart, s + i, (size_t)(len - i + 1));
}

static void StripGluedBodyAfterHeading(char* s);

static ExtractedTocItem* NewItem(const char* title, int pageNo, float x, float y, int level, int confidence = 0) {
    auto* n = new ExtractedTocItem;
    n->title = DupTrimmed(title);
    RewriteOcrYiDashesInParenTitle(&n->title);
    RewriteOcrLetterAsListOne(&n->title);
    RewriteOcrDashAsYiDunhao(&n->title);
    RewriteOcrGraveAsDunhao(&n->title);
    StripLeadingListBullet(&n->title);
    HeadingMarker nm = ParseHeadingMarker(n->title);
    bool keepOfficialApTitle = false;
    if (nm.type == MarkerType::Appendix && nm.prefixLength > 0) {
        const char* rest = n->title + nm.prefixLength;
        int rlen = (int)str::Len(rest);
        int ri = 0;
        SkipSpacesUtf8(rest, rlen, ri);
        rest += ri;
        keepOfficialApTitle =
            rest[0] && (OfficialTitleHasDocSuffix(rest) || OfficialDocTitleNeedsWrap(rest) ||
                        LooksLikeOfficialAppendixHeadingName(rest) || LooksLikeOfficialDraftParen(rest) ||
                        str::Find(rest, "工作要点") || str::Find(rest, "征求意见稿"));
    }
    if (!keepOfficialApTitle) {
        TrimAtNextEmbeddedHeading(n->title);
        TrimTitleToFirstSentence(n->title);
        StripGluedBodyAfterHeading(n->title);
        TrimAtNextDiHeading(n->title);
    }
    StripTrailingOcrTitleJunk(n->title);
    ShortenOfficialUrlListTitle(n->title);
    NormalizeTocNumberingParens(&n->title);
    NormalizeTocNumberingDots(&n->title);
    StripNumberingTitleSpace(&n->title);
    n->pageNo = pageNo;
    n->x = x;
    n->y = y;
    n->level = level < 1 ? 1 : level;
    n->confidence = confidence;
    if (n->confidence < 0) {
        n->confidence = 0;
    }
    if (n->confidence > 100) {
        n->confidence = 100;
    }
    return n;
}

static int EnforceMonotonicPages(Vec<ExtractedTocItem*>& flat) {
    int nFix = 0;
    int prev = 0;
    for (int i = 0; i < flat.Size(); i++) {
        ExtractedTocItem* it = flat[i];
        if (!it) {
            continue;
        }
        int p = it->pageNo;
        if (p < 1) {
            if (prev > 0) {
                it->pageNo = prev;
                nFix++;
            }
            continue;
        }
        if (prev > 0 && p < prev) {
            it->pageNo = prev;
            nFix++;
            p = prev;
        }
        prev = p;
    }
    return nFix;
}

static void BuildTreeFromFlat(Vec<ExtractedTocItem*>& flat, Vec<ExtractedTocItem*>& roots) {
    Vec<ExtractedTocItem*> stack;
    for (int i = 0; i < flat.Size(); i++) {
        ExtractedTocItem* n = flat[i];
        while (stack.Size() > 0 && stack.Last()->level >= n->level) {
            stack.RemoveLast();
        }
        if (stack.Size() == 0) {
            roots.Append(n);
        } else {
            stack.Last()->children.Append(n);
        }
        stack.Append(n);
    }
    flat.Reset();
}

static int CountExtracted(const Vec<ExtractedTocItem*>& roots) {
    int n = 0;
    for (ExtractedTocItem* r : roots) {
        n++;
        n += CountExtracted(r->children);
    }
    return n;
}

static int ExtractedCountAppendixNum(const Vec<ExtractedTocItem*>& nodes, int num) {
    int n = 0;
    for (int i = 0; i < nodes.Size(); i++) {
        if (!nodes[i] || !nodes[i]->title) {
            continue;
        }
        HeadingMarker m = ParseHeadingMarker(nodes[i]->title);
        if (m.type == MarkerType::Appendix && m.number == num) {
            n++;
        }
        n += ExtractedCountAppendixNum(nodes[i]->children, num);
    }
    return n;
}

static bool IsPrintedPageParenOpen(int cp) {
    return cp == '(' || cp == 0xFF08;
}

static bool IsPrintedPageParenClose(int cp) {
    return cp == ')' || cp == 0xFF09;
}

static bool LineLooksLikePageNumber(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int afterSpace = i;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 0 && IsLeaderCp(cp) && !IsDigitCp(cp) && cp != '-' && cp != 0x2013 && cp != 0x2014) {
            continue;
        }
        i = save;
        break;
    }
    bool hadLead = i > afterSpace;
    if (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (IsPrintedPageParenOpen(cp)) {
            hadLead = true;
            SkipSpacesUtf8(s, len, i);
        } else {
            i = save;
        }
    }
    int nDigit = 0;
    while (i < len) {
        int save = i;
        if (nDigit > 0) {
            SkipSpacesUtf8(s, len, i);
        }
        int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (!IsDigitCp(cp)) {
            i = save;
            break;
        }
        nDigit++;
        if (nDigit > 4) {
            return false;
        }
    }
    if (nDigit < 1) {
        return false;
    }
    int afterDigits = i;
    SkipSpacesUtf8(s, len, i);
    if (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (!IsPrintedPageParenClose(cp)) {
            i = save;
        }
    }
    SkipSpacesUtf8(s, len, i);
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 0 && IsLeaderCp(cp) && !IsDigitCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    SkipSpacesUtf8(s, len, i);
    if (i < len) {
        return false;
    }
    // Scan footer leftover "60—" / "0—" is still a page number after leaders are eaten.
    if (!hadLead && afterDigits < len && i < len) {
        return false;
    }
    return true;
}

static bool LineLooksLikeRomanPage(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int n = 0;
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (cp <= 32 || cp == 0x3000) {
            continue;
        }
        if (cp >= 'A' && cp <= 'Z') {
            cp += 32;
        }
        if (cp != 'i' && cp != 'v' && cp != 'x' && cp != 'l' && cp != 'c' && cp != 'm') {
            return false;
        }
        n++;
        if (n > 8) {
            return false;
        }
    }
    return n >= 2 && n <= 8;
}

static int ParseBarePrintedPage(const char* s) {
    int v = 0;
    int n = 0;
    if (!s) {
        return 0;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int afterSpace = i;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 0 && IsLeaderCp(cp) && !IsDigitCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    bool hadLead = i > afterSpace;
    if (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (IsPrintedPageParenOpen(cp)) {
            hadLead = true;
            SkipSpacesUtf8(s, len, i);
        } else {
            i = save;
        }
    }
    while (i < len) {
        int save = i;
        if (n > 0) {
            SkipSpacesUtf8(s, len, i);
        }
        int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (IsDigitCp(cp)) {
            v = v * 10 + DigitValue(cp);
            n++;
            if (n > 4) {
                return 0;
            }
            continue;
        }
        i = save;
        break;
    }
    int afterDigits = i;
    SkipSpacesUtf8(s, len, i);
    if (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (!IsPrintedPageParenClose(cp)) {
            i = save;
        }
    }
    SkipSpacesUtf8(s, len, i);
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 0 && IsLeaderCp(cp) && !IsDigitCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    SkipSpacesUtf8(s, len, i);
    if (i < len || n < 1 || v < 1 || v > 9999) {
        return 0;
    }
    if (!hadLead && afterDigits < len) {
        return 0;
    }
    return v;
}

static bool HasLetterOrCjk(const char* s) {
    if (!s) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if ((cp >= 'A' && cp <= 'Z') || (cp >= 'a' && cp <= 'z')) {
            return true;
        }
        if (cp >= 0x4E00 && cp <= 0x9FFF) {
            return true;
        }
    }
    return false;
}

static int CountCjkGlyphs(const char* s) {
    if (!s) {
        return 0;
    }
    int n = 0;
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (cp >= 0x4E00 && cp <= 0x9FFF) {
            n++;
        }
    }
    return n;
}

static bool LooksLikeUrlStart(const char* s) {
    if (!s) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    return str::StartsWithI(s + i, "http://") || str::StartsWithI(s + i, "https://") ||
           str::StartsWithI(s + i, "ftp://");
}

static bool IsKnownDnsTld(const char* s, int n) {
    if (!s || n < 2 || n > 6) {
        return false;
    }
    char buf[8];
    memcpy(buf, s, (size_t)n);
    buf[n] = 0;
    return str::EqI(buf, "com") || str::EqI(buf, "cn") || str::EqI(buf, "net") || str::EqI(buf, "org") ||
           str::EqI(buf, "gov") || str::EqI(buf, "edu") || str::EqI(buf, "info") || str::EqI(buf, "cc") ||
           str::EqI(buf, "co") || str::EqI(buf, "me") || str::EqI(buf, "tv") || str::EqI(buf, "mil");
}

// OCR wraps emails as "yc7116 @" / "126. com" — not "126. 工作安排".
static bool LooksLikeSpacedDnsName(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    if (i >= len) {
        return false;
    }
    const char* lastLab = nullptr;
    int lastN = 0;
    int nLab = 0;
    while (i < len) {
        SkipSpacesUtf8(s, len, i);
        if (i >= len) {
            break;
        }
        int start = i;
        while (i < len) {
            int save = i;
            int cp = Utf8CodepointNext(s, len, i);
            if ((cp >= 'A' && cp <= 'Z') || (cp >= 'a' && cp <= 'z') || IsDigitCp(cp) || cp == '-') {
                continue;
            }
            i = save;
            break;
        }
        int n = i - start;
        if (n < 1) {
            return false;
        }
        lastLab = s + start;
        lastN = n;
        nLab++;
        SkipSpacesUtf8(s, len, i);
        if (i >= len) {
            break;
        }
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp == '.' || cp == 0xFF0E) {
            continue;
        }
        i = save;
        return false;
    }
    return nLab >= 1 && IsKnownDnsTld(lastLab, lastN);
}

static bool LooksLikeDomainOrEmailFragment(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (str::Find(s, "@")) {
        // "yc7116 @qq.com" crumb vs "请各设区…发送至490034849@qq.com" task line.
        int g = GlyphCount(s);
        int len = (int)str::Len(s);
        int i = 0;
        SkipSpacesUtf8(s, len, i);
        int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (cp >= 0x4E00 && cp <= 0x9FFF && g >= 8) {
            return false;
        }
        return true;
    }
    // Numbered https:// list items are real headings; only reject email/TLD crumbs.
    if (LooksLikeUrlStart(s) || str::Find(s, "/")) {
        return false;
    }
    return LooksLikeSpacedDnsName(s);
}

// "1、https://pan.baidu.com/s/xxx" → "1、pan.baidu.com/s/xxx" (keep 1/2/3, drop the scheme).
static void ShortenOfficialUrlListTitle(char* s) {
    if (!s || !s[0]) {
        return;
    }
    CompactSpacedUrlInTitle(s);
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.prefixLength < 1) {
        return;
    }
    int len = (int)str::Len(s);
    int i = m.prefixLength;
    SkipSpacesUtf8(s, len, i);
    if (!LooksLikeUrlStart(s + i)) {
        return;
    }
    const char* scheme = str::FindI(s + i, "://");
    if (!scheme) {
        return;
    }
    const char* host = scheme + 3;
    int hlen = (int)str::Len(host);
    int hi = 0;
    int g = 0;
    int cut = 0;
    while (hi < hlen) {
        int save = hi;
        int cp = Utf8CodepointNext(host, hlen, hi);
        if (cp <= 32 || cp == '?' || cp == '#') {
            break;
        }
        g++;
        if (g > 28) {
            cut = save;
            break;
        }
        cut = hi;
    }
    if (cut < 4) {
        return;
    }
    int dest = i;
    int hostOff = (int)(host - s);
    memmove(s + dest, s + hostOff, (size_t)cut);
    if (g > 28) {
        memcpy(s + dest + cut, "\xE2\x80\xA6", 3);
        s[dest + cut + 3] = 0;
    } else {
        s[dest + cut] = 0;
    }
    str::TrimWSInPlace(s, str::TrimOpt::Both);
    // #region agent log
    DbgFace09("O", "ExtractPdfToc.cpp:ShortenOfficialUrlListTitle", s, "shorten-url");
    // #endregion
}

static bool CpIsUrlSafeAscii(int cp) {
    return (cp >= 'A' && cp <= 'Z') || (cp >= 'a' && cp <= 'z') || IsDigitCp(cp) || cp == ':' || cp == '/' ||
           cp == '.' || cp == '-' || cp == '_' || cp == '~' || cp == '?' || cp == '&' || cp == '=' || cp == '%' ||
           cp == '+' || cp == '#' || cp == '@';
}

static bool TextIsUrlSafeAscii(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    int n = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32) {
            continue;
        }
        if (!CpIsUrlSafeAscii(cp)) {
            return false;
        }
        n++;
    }
    return n >= 1;
}

static bool EndsLikeUrlHead(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    const char* rest = (m.type == MarkerType::ArabicDot && m.prefixLength > 0) ? s + m.prefixLength : s;
    int len = (int)str::Len(rest);
    int i = 0;
    SkipSpacesUtf8(rest, len, i);
    if (i >= len) {
        return false;
    }
    const char* r = rest + i;
    if (str::StartsWithI(r, "http") || str::Find(r, "://") || str::Find(r, "//")) {
        return true;
    }
    return TextIsUrlSafeAscii(r) && (str::Find(r, ".") || str::Find(r, "/") || str::Find(r, ":"));
}

static bool StartsLikeUrlTail(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    return TextIsUrlSafeAscii(s);
}

static bool ShouldJoinUrlLineFragments(const char* a, const char* b) {
    return EndsLikeUrlHead(a) && StartsLikeUrlTail(b);
}

static bool LooksLikeArchiveJunk(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (str::Find(s, "扫描全能王") || str::FindI(s, "camscanner")) {
        return true;
    }
    if (str::FindI(s, "annas_archive") || str::FindI(s, "original_files")) {
        return true;
    }
    return str::EndsWithI(s, ".zst") || str::EndsWithI(s, ".json") || str::EndsWithI(s, ".tar") ||
           str::EndsWithI(s, ".zip") || str::EndsWithI(s, ".json.zst") || str::EndsWithI(s, ".tar.zst");
}

static bool OfficialTitleFindGuanYu(const char* s) {
    return s && (str::Find(s, "关于") || str::Find(s, "关千") || str::Find(s, "美于印发"));
}

static bool OfficialTitleIsIssuerBanner(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 4 || g > 28) {
        return false;
    }
    if (OfficialTitleFindGuanYu(s)) {
        return false;
    }
    return str::StartsWith(s, "中共") || (str::Find(s, "省委") && str::Find(s, "人民政府"));
}

// 红头 like 江西省…厅…领导小组办公室 — not a 3-line 意见 issuer, not a title.
static bool LooksLikeOfficialHongtouLetterhead(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (OfficialTitleFindGuanYu(s) || str::Find(s, "印发") || str::Find(s, "转发") || str::Find(s, "批转")) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 6 || g > 36) {
        return false;
    }
    if (!str::EndsWith(s, "办公室")) {
        return false;
    }
    return str::Find(s, "厅") || str::Find(s, "局") || str::Find(s, "政府") || str::Find(s, "领导小组");
}

// Sidebar is narrow: drop 发文单位 so the bookmark starts at 关于 / 印发 / 转发.
static const char* OfficialFindEarliestSubjectStart(const char* s) {
    if (!s) {
        return nullptr;
    }
    const char* best = nullptr;
    const char* needles[] = {"关于", "关千", "美于印发", "印发", "转发", "批转", "《"};
    for (int i = 0; i < (int)dimof(needles); i++) {
        const char* p = str::Find(s, needles[i]);
        if (p && (!best || p < best)) {
            best = p;
        }
    }
    return best;
}

static bool OfficialTitlePrefixLooksLikeIssuer(const char* s, int byteLen) {
    if (!s || byteLen < 2) {
        return false;
    }
    char buf[192];
    if (byteLen >= (int)sizeof(buf)) {
        byteLen = (int)sizeof(buf) - 1;
    }
    memcpy(buf, s, (size_t)byteLen);
    buf[byteLen] = 0;
    str::TrimWSInPlace(buf, str::TrimOpt::Both);
    int n = (int)str::Len(buf);
    while (n > 0) {
        int idx = n;
        int cp = Utf8CodepointPrev(buf, n, idx);
        if (cp == ',' || cp == 0x3001 || cp == 0xFF0C || cp == 0x3000 || cp == ' ' || cp == '\t') {
            buf[idx] = 0;
            n = idx;
            continue;
        }
        break;
    }
    if (OfficialTitleFindGuanYu(buf) || str::Find(buf, "印发") || str::Find(buf, "转发") || str::Find(buf, "批转")) {
        return false;
    }
    int g = GlyphCount(buf);
    if (g < 2 || g > 40) {
        return false;
    }
    if (str::Find(buf, "中共") || str::Find(buf, "省委") || str::Find(buf, "市委") || str::Find(buf, "县委") ||
        str::Find(buf, "区委") || str::Find(buf, "人民政府") || str::Find(buf, "办公厅") || str::Find(buf, "国务院") ||
        str::Find(buf, "人大常委会") || str::Find(buf, "纪委") || str::Find(buf, "监委") ||
        str::Find(buf, "领导小组")) {
        return true;
    }
    return str::EndsWith(buf, "厅") || str::EndsWith(buf, "局") || str::EndsWith(buf, "党组") ||
           str::EndsWith(buf, "部") || str::EndsWith(buf, "委员会") || str::EndsWith(buf, "管理局") ||
           str::EndsWith(buf, "办公室");
}

static void StripOfficialIssuerPrefixInPlace(char* title) {
    if (!title || !title[0]) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(title);
    char* body = title + m.prefixLength;
    if (!body[0]) {
        return;
    }
    if (str::StartsWith(body, "关于") || str::StartsWith(body, "关千") || str::StartsWith(body, "印发") ||
        str::StartsWith(body, "转发") || str::StartsWith(body, "批转") || str::StartsWith(body, "《")) {
        return;
    }
    const char* sub = OfficialFindEarliestSubjectStart(body);
    if (!sub || sub == body) {
        return;
    }
    int prefixLen = (int)(sub - body);
    if (!OfficialTitlePrefixLooksLikeIssuer(body, prefixLen)) {
        return;
    }
    if (GlyphCount(sub) < 4) {
        return;
    }
    memmove(body, sub, str::Len(sub) + 1);
}

static bool LooksLikeOfficialDocDateLine(const char* s) {
    if (!s || !s[0] || GlyphCount(s) > 18) {
        return false;
    }
    return str::Find(s, "年") && str::Find(s, "月") && str::Find(s, "日");
}

static bool LooksLikeOfficialBoilerplate(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (HeadingLevelFromText(s) > 0) {
        return false;
    }
    // 中共江西省委 江西省人民政府 is the first line of a 意见 title, not 红头.
    if (OfficialTitleIsIssuerBanner(s)) {
        return false;
    }
    if (str::Find(s, "抄送") || str::Find(s, "签发人") || str::Find(s, "主题词") || str::Find(s, "此件") ||
        str::Find(s, "公开属性") || str::StartsWith(s, "主送")) {
        return true;
    }
    if (str::Eq(s, "紧急") || str::Eq(s, "特急") || str::Eq(s, "加急") || str::Eq(s, "内部") || str::Eq(s, "机密") ||
        str::Eq(s, "文件") || str::Eq(s, "明电") || str::Find(s, "等级平急")) {
        return true;
    }
    int g = GlyphCount(s);
    if (g <= 18 && (str::Find(s, "人民政府") || str::Find(s, "办公厅") || str::Find(s, "委员会")) &&
        str::Find(s, "文件")) {
        return true;
    }
    if (g >= 4 && g <= 22 && !str::StartsWith(s, "关于") &&
        (str::EndsWith(s, "厅") || str::EndsWith(s, "局") || str::EndsWith(s, "党组") || str::EndsWith(s, "人民政府") ||
         str::EndsWith(s, "管理局") || str::EndsWith(s, "委员会") || str::EndsWith(s, "办公厅"))) {
        return true;
    }
    if (LooksLikeOfficialHongtouLetterhead(s)) {
        return true;
    }
    return false;
}

static bool LooksLikeUrlListTitle(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    const char* rest = m.prefixLength > 0 ? s + m.prefixLength : s;
    return str::FindI(rest, "http") || LooksLikeUrlStart(rest) || str::Find(rest, "://");
}

static void CompactSpacedUrlInTitle(char* s) {
    if (!s || !LooksLikeUrlListTitle(s)) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    int dest = m.prefixLength > 0 ? m.prefixLength : 0;
    int len = (int)str::Len(s);
    for (int i = dest; i < len; i++) {
        if (s[i] != ' ' && s[i] != '\t') {
            s[dest++] = s[i];
        }
    }
    s[dest] = 0;
}

static bool LooksLikeLeaderTitle(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    // URL paths are full of / and . — not TOC leaders.
    if (LooksLikeUrlListTitle(s)) {
        return false;
    }
    if (str::Find(s, "......") || str::Find(s, "．．．．") || str::Find(s, "····")) {
        return true;
    }
    int nLead = 0;
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (IsLeaderCp(cp) && cp > 32 && cp != 0x3000) {
            nLead++;
            if (nLead >= 5) {
                return true;
            }
        }
    }
    return false;
}

static bool LooksLikeDocNumberLine(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 4 || g > 28) {
        return false;
    }
    if (str::StartsWith(s, "关于") || str::Find(s, "通知") || str::Find(s, "印发")) {
        return false;
    }
    bool hasHao = str::Find(s, "号") != nullptr;
    bool hasBracket = str::Find(s, "〔") || str::Find(s, "[") || str::Find(s, "［");
    return hasHao && hasBracket;
}

// Some RAZ / scanned fonts report a bbox several times taller than the
// actual glyphs. Using that dy as line height glues consecutive TOC rows.
static float ScanLineVisualHeight(const ScanLine& sl) {
    float h = sl.dy;
    if (sl.fontSize > 4.f && sl.dy > sl.fontSize * 1.75f) {
        h = sl.fontSize;
    }
    if (h < 4.f) {
        h = 4.f;
    }
    return h;
}

static float ScanLineMidY(const ScanLine& sl) {
    return sl.y + ScanLineVisualHeight(sl) * 0.5f;
}

static bool SamePrintedTocRow(const ScanLine& a, const ScanLine& b) {
    float dy = ScanLineVisualHeight(a);
    float bh = ScanLineVisualHeight(b);
    if (bh > dy) {
        dy = bh;
    }
    if (dy < 6) {
        dy = 6;
    }
    float d = ScanLineMidY(a) - ScanLineMidY(b);
    if (d < 0) {
        d = -d;
    }
    return d <= dy * 1.15f;
}

static void SortScanLinesVisual(Vec<ScanLine>& v) {
    for (int i = 0; i < v.Size(); i++) {
        for (int j = i + 1; j < v.Size(); j++) {
            float yi = ScanLineMidY(v[i]);
            float yj = ScanLineMidY(v[j]);
            bool less = false;
            if (v[j].srcPage != v[i].srcPage) {
                less = v[j].srcPage < v[i].srcPage;
            } else if (yj + 0.5f < yi) {
                less = true;
            } else if (yj <= yi + 0.5f && v[j].x < v[i].x) {
                less = true;
            }
            if (less) {
                ScanLine t = v[i];
                v[i] = v[j];
                v[j] = t;
            }
        }
    }
}

static void JoinScanLineFragment(ScanLine& acc, const ScanLine& add) {
    if (!add.text || !add.text[0]) {
        return;
    }
    bool tight = false;
    if (acc.text && acc.text[0]) {
        int alen = (int)str::Len(acc.text);
        int ai = alen;
        int last = Utf8CodepointPrev(acc.text, alen, ai);
        int bi = 0;
        int blen = (int)str::Len(add.text);
        int first = Utf8CodepointNext(add.text, blen, bi);
        if (IsDigitCp(last) && IsDigitCp(first)) {
            tight = true;
        }
        if ((last == '.' || last == 0xFF0E) && IsDigitCp(first)) {
            int before = Utf8CodepointPrev(acc.text, alen, ai);
            if (IsDigitCp(before)) {
                tight = true;
            }
        }
        if (IsDigitCp(last) && (first == '.' || first == 0xFF0E || first == 0x3002)) {
            tight = true;
        }
        if (IsCnNumeral(last) && IsDunhaoSepCp(first)) {
            tight = true;
        }
        if (ShouldJoinUrlLineFragments(acc.text, add.text)) {
            tight = true;
        }
    }
    char* n = nullptr;
    if (!acc.text || !acc.text[0]) {
        n = str::Dup(add.text);
    } else if (tight) {
        n = str::Join(acc.text, add.text);
    } else {
        n = str::Join(acc.text, " ", add.text);
    }
    str::Free(acc.text);
    acc.text = n;
    float ax2 = acc.x + acc.dx;
    float ay2 = acc.y + acc.dy;
    float bx2 = add.x + add.dx;
    float by2 = add.y + add.dy;
    float nx = acc.x < add.x ? acc.x : add.x;
    float ny = acc.y < add.y ? acc.y : add.y;
    float nx2 = ax2 > bx2 ? ax2 : bx2;
    float ny2 = ay2 > by2 ? ay2 : by2;
    acc.x = nx;
    acc.y = ny;
    acc.dx = nx2 - nx;
    acc.dy = ny2 - ny;
}

static void CompactScanLines(Vec<ScanLine>& lines) {
    int i = 0;
    while (i < lines.Size()) {
        if (!lines[i].text || !lines[i].text[0]) {
            str::Free(lines[i].text);
            lines[i].text = nullptr;
            lines.RemoveAt(i);
            continue;
        }
        i++;
    }
}

static bool LineIsBareLessonOrChapter(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if ((m.type == MarkerType::Chapter || m.type == MarkerType::Section) && m.prefixLength >= 1) {
        return GlyphCount(s + m.prefixLength) <= 2;
    }
    return false;
}

static bool TitleIsNumberingOnly(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.prefixLength < 1) {
        return false;
    }
    if (m.type != MarkerType::Chapter && m.type != MarkerType::Section && m.type != MarkerType::Article) {
        return false;
    }
    return GlyphCount(s + m.prefixLength) < 2;
}

static bool TitleNeedsWrapContinuation(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = len;
    int last = 0;
    while (i > 0) {
        last = Utf8CodepointPrev(s, len, i);
        if (last <= 32 || last == 0x3000 || IsLeaderCp(last)) {
            continue;
        }
        break;
    }
    if (last == 0xFF0C || last == ',' || last == 0x3001 || last == 0xFF1F || last == '?' || last == 0xFF01 ||
        last == '!') {
        return true;
    }
    if (last == 0x89C1) { // 见 — "（见附件N）" wrap
        return true;
    }
    if (last == 0x5C0F) { // 小 — "领导小" / "小组" split
        return true;
    }
    if (last == 0x5404) { // 各 — "请各" leftover of 请各编报单位
        int prev = Utf8CodepointPrev(s, len, i);
        if (prev == 0x8BF7) { // 请
            return true;
        }
    }
    return str::Find(s, "《") && !str::Find(s, "》");
}

static bool LineIsPrintedTocContinuation(const char* s) {
    if (!s || !s[0] || LooksLikePrintedTocHeading(s) || LooksLikeArchiveJunk(s) || LineLooksLikePageNumber(s) ||
        LineLooksLikeRomanPage(s)) {
        return false;
    }
    if (BookTitleIsSpine(s) || HeadingLevelFromText(s) >= 1) {
        return false;
    }
    int g = GlyphCount(s);
    return HasLetterOrCjk(s) && g >= 2 && g <= 40;
}

static int BestPrintedTocGlueSlot(const Vec<ScanLine>& pageLines, int i, bool wrap) {
    int best = -1;
    float bestScore = 1e9f;
    for (int j = 0; j < pageLines.Size(); j++) {
        if (i == j || !pageLines[j].text) {
            continue;
        }
        if (!LineIsPrintedTocContinuation(pageLines[j].text)) {
            continue;
        }
        if (pageLines[j].srcPage != pageLines[i].srcPage) {
            continue;
        }
        bool sameRow = SamePrintedTocRow(pageLines[i], pageLines[j]) && pageLines[j].x > pageLines[i].x + 4;
        float gapY = pageLines[j].y - (pageLines[i].y + pageLines[i].dy);
        float lim = pageLines[i].dy > 6 ? pageLines[i].dy * 1.85f : 16;
        bool wrapBelow = wrap && gapY >= -4 && gapY <= lim && pageLines[j].x + 1 >= pageLines[i].x;
        if (!sameRow && !wrapBelow) {
            continue;
        }
        float score = sameRow ? (pageLines[j].x - pageLines[i].x) : (1000.f + gapY);
        if (score < bestScore) {
            bestScore = score;
            best = j;
        }
    }
    return best;
}

static void RepairXinDeOcrDash(char* s) {
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int c1 = i < len ? Utf8CodepointNext(s, len, i) : 0;
    int c2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (c1 != 0x5FC3 || c2 != 0x5F97) {
        return;
    }
    SkipSpacesUtf8(s, len, i);
    int dashPos = i;
    int dash = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (dash != 0xFF0D && dash != 0x2013 && dash != 0x2014 && dash != 0x2015) {
        return;
    }
    if (dashPos + 2 >= len) {
        return;
    }
    // 一 and the OCR dashes are all 3-byte UTF-8.
    s[dashPos] = '\xE4';
    s[dashPos + 1] = '\xB8';
    s[dashPos + 2] = '\x80';
}

static void RepairOcrDiUnits(Vec<ScanLine>& pageLines) {
    for (int i = 0; i < pageLines.Size(); i++) {
        char* s = pageLines[i].text;
        if (!s || !s[0]) {
            continue;
        }
        RepairXinDeOcrDash(s);
        int len = (int)str::Len(s);
        int iCp = 0;
        while (iCp < len) {
            int save = iCp;
            int cp = Utf8CodepointNext(s, len, iCp);
            if (cp != 0x7B2C) {
                continue;
            }
            SkipSpacesUtf8(s, len, iCp);
            if (ConsumeOfficialNumber(s, len, iCp) < 0) {
                iCp = save;
                Utf8CodepointNext(s, len, iCp);
                continue;
            }
            SkipSpacesUtf8(s, len, iCp);
            int markPos = iCp;
            int mark = iCp < len ? Utf8CodepointNext(s, len, iCp) : 0;
            if (mark == 0x7AE5 && markPos + 2 < len && (unsigned char)s[markPos] == 0xE7 &&
                (unsigned char)s[markPos + 1] == 0xAB) {
                s[markPos + 2] = '\xA0';
            }
        }
    }
}

static void GluePrintedTocWraps(Vec<ScanLine>& pageLines) {
    bool any = true;
    int guard = 0;
    while (any && guard < 64) {
        any = false;
        guard++;
        SortScanLinesVisual(pageLines);
        for (int i = 0; i < pageLines.Size(); i++) {
            if (!pageLines[i].text) {
                continue;
            }
            bool bare = LineIsBareLessonOrChapter(pageLines[i].text);
            bool wrap = TitleNeedsWrapContinuation(pageLines[i].text) && HeadingLevelFromText(pageLines[i].text) >= 1;
            if (!bare && !wrap) {
                continue;
            }
            int j = BestPrintedTocGlueSlot(pageLines, i, wrap);
            if (j < 0) {
                continue;
            }
            JoinScanLineFragment(pageLines[i], pageLines[j]);
            str::Free(pageLines[j].text);
            pageLines[j].text = nullptr;
            CompactScanLines(pageLines);
            any = true;
            break;
        }
    }
}

static void GlueSplitPrintedPageNums(Vec<ScanLine>& pageLines) {
    bool any = true;
    int guard = 0;
    while (any && guard < 32) {
        any = false;
        guard++;
        SortScanLinesVisual(pageLines);
        for (int i = 0; i < pageLines.Size(); i++) {
            if (!LineLooksLikePageNumber(pageLines[i].text)) {
                continue;
            }
            int best = -1;
            float bestX = 1e9f;
            for (int j = 0; j < pageLines.Size(); j++) {
                if (i == j || !LineLooksLikePageNumber(pageLines[j].text)) {
                    continue;
                }
                if (pageLines[j].srcPage != pageLines[i].srcPage) {
                    continue;
                }
                if (!SamePrintedTocRow(pageLines[i], pageLines[j])) {
                    continue;
                }
                if (pageLines[j].x <= pageLines[i].x + 2) {
                    continue;
                }
                float gap = pageLines[j].x - (pageLines[i].x + pageLines[i].dx);
                if (gap > 28) {
                    continue;
                }
                if (pageLines[j].x < bestX) {
                    bestX = pageLines[j].x;
                    best = j;
                }
            }
            if (best < 0) {
                continue;
            }
            JoinScanLineFragment(pageLines[i], pageLines[best]);
            str::Free(pageLines[best].text);
            pageLines[best].text = nullptr;
            CompactScanLines(pageLines);
            any = true;
            break;
        }
    }
}

static bool IsLoneListBulletText(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    if (i >= len) {
        return false;
    }
    int cp = Utf8CodepointNext(s, len, i);
    if (!IsListBulletCp(cp)) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    return i >= len;
}

static bool LooksLikeBodyContinuationStart(const char* s);
static bool LineIsBareCnNumeral(const char* s);
static bool LineStartsWithDunhaoThenTitle(const char* s);

static void RebuildVisualLines(Vec<ScanLine>& pageLines) {
    int n = pageLines.Size();
    if (n < 2) {
        return;
    }
    SortScanLinesVisual(pageLines);
    Vec<float> hs;
    for (int i = 0; i < n; i++) {
        float h = ScanLineVisualHeight(pageLines[i]);
        if (h > 1) {
            hs.Append(h);
        }
    }
    float med = MedianPositive(hs);
    if (med < 4) {
        med = 8;
    }
    float tol = med * (float)kExtractPdfToc.lineYTolPct / 100.0f;
    float maxGap = med * (float)kExtractPdfToc.lineMaxGapEm;
    float numGap = med * (float)kExtractPdfToc.lineNumTitleGapEm;
    Vec<int> used;
    for (int i = 0; i < n; i++) {
        used.Append(0);
    }
    Vec<ScanLine> out;
    for (int i = 0; i < n; i++) {
        if (used[i] || !pageLines[i].text) {
            continue;
        }
        Vec<int> grp;
        grp.Append(i);
        used[i] = 1;
        for (int j = 0; j < n; j++) {
            if (used[j] || !pageLines[j].text) {
                continue;
            }
            float ah = ScanLineVisualHeight(pageLines[i]);
            float bh = ScanLineVisualHeight(pageLines[j]);
            float ay2 = pageLines[i].y + ah;
            float by2 = pageLines[j].y + bh;
            float top = pageLines[i].y > pageLines[j].y ? pageLines[i].y : pageLines[j].y;
            float bot = ay2 < by2 ? ay2 : by2;
            float ov = bot - top;
            float mh = ah < bh ? ah : bh;
            if (mh < 4) {
                mh = 4;
            }
            float d = ScanLineMidY(pageLines[i]) - ScanLineMidY(pageLines[j]);
            if (d < 0) {
                d = -d;
            }
            if (ov < mh * 0.35f && d > tol) {
                continue;
            }
            grp.Append(j);
            used[j] = 1;
        }
        for (int a = 0; a < grp.Size(); a++) {
            for (int b = a + 1; b < grp.Size(); b++) {
                float ya = ScanLineMidY(pageLines[grp[a]]);
                float yb = ScanLineMidY(pageLines[grp[b]]);
                bool less = false;
                if (yb + 0.5f < ya) {
                    less = true;
                } else if (yb <= ya + 0.5f && pageLines[grp[b]].x < pageLines[grp[a]].x) {
                    less = true;
                }
                if (less) {
                    int t = grp[a];
                    grp[a] = grp[b];
                    grp[b] = t;
                }
            }
        }
        ScanLine acc = pageLines[grp[0]];
        pageLines[grp[0]].text = nullptr;
        for (int g = 1; g < grp.Size(); g++) {
            ScanLine& add = pageLines[grp[g]];
            if (IsLoneListBulletText(acc.text) && add.text && ParseHeadingMarker(add.text).rank >= 1 &&
                (acc.dx < 8 || acc.dx <= add.dy * 0.55f || acc.dy <= add.dy * 0.7f)) {
                str::Free(acc.text);
                acc = add;
                add.text = nullptr;
                continue;
            }
            float gap = add.x - (acc.x + acc.dx);
            bool numTitle = LooksLikeTocNumToken(acc.text) && add.text && HasLetterOrCjk(add.text);
            float lim = numTitle ? numGap : maxGap;
            bool bothHeadings = HeadingLevelFromText(acc.text) > 0 && HeadingLevelFromText(add.text) > 0;
            bool addHeading = HeadingLevelFromText(add.text) > 0;
            bool accHeading = HeadingLevelFromText(acc.text) > 0;
            bool bodyStart = LooksLikeBodyContinuationStart(add.text);
            bool underHeading = accHeading && gap < 0 && !numTitle;
            bool stacked = gap < -8;
            bool tocHeadJoin = LooksLikePrintedTocHeading(acc.text) || LooksLikePrintedTocHeading(add.text);
            bool urlFrag = ShouldJoinUrlLineFragments(acc.text, add.text);
            bool splitDunhao = LineIsBareCnNumeral(acc.text) && LineStartsWithDunhaoThenTitle(add.text);
            bool doJoin = urlFrag || splitDunhao ||
                          (!stacked && gap <= lim && !bothHeadings && (!addHeading || numTitle) && !bodyStart &&
                           !underHeading && !tocHeadJoin);
            // #region agent log
            if (urlFrag && (DbgFace09Hit(acc.text) || DbgFace09Hit(add.text))) {
                char extra[160];
                snprintf(extra, (int)sizeof(extra), "urlFrag gap=%.1f stacked=%d", gap, stacked ? 1 : 0);
                DbgFace09("R", "ExtractPdfToc.cpp:RebuildVisualLines.urlFrag", acc.text, extra);
                DbgFace09("R", "ExtractPdfToc.cpp:RebuildVisualLines.urlAdd", add.text, extra);
            }
            // #endregion
            if (doJoin) {
                JoinScanLineFragment(acc, add);
                str::Free(add.text);
                add.text = nullptr;
            } else {
                out.Append(acc);
                acc = add;
                add.text = nullptr;
            }
        }
        out.Append(acc);
    }
    pageLines.Reset();
    for (int i = 0; i < out.Size(); i++) {
        pageLines.Append(out[i]);
    }
}

static bool LooksLikeBodyContinuationStart(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    const char* t = s + i;
    return str::StartsWith(t, "为了") || str::StartsWith(t, "根据") || str::StartsWith(t, "按照") ||
           str::StartsWith(t, "请各") ||
           (str::StartsWith(t, "各") && !str::StartsWith(t, "各地") && !str::StartsWith(t, "各级")) ||
           str::StartsWith(t, "坚持") || str::StartsWith(t, "通过") || str::StartsWith(t, "充分") ||
           str::StartsWith(t, "进一步") || str::StartsWith(t, "今后") || str::StartsWith(t, "今") ||
           str::StartsWith(t, "我厅") || str::StartsWith(t, "我局");
}

// Page-top wrap of a 公文 paragraph: "财政局、赣江新区…还应报送本地区纸质年报"
static bool LooksLikeOfficialOutlineWrapBody(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (str::StartsWith(s, "财政局、") || str::StartsWith(s, "区市财政局") || str::StartsWith(s, "编报单位") ||
        str::StartsWith(s, "金融局还应") || str::StartsWith(s, "金融局应对")) {
        return true;
    }
    return str::Find(s, "还应报送") || str::Find(s, "还应当报送");
}

static bool BodyContinuationAt(const char* s, int len, int i) {
    if (!s || i < 0 || i >= len || !LooksLikeBodyContinuationStart(s + i)) {
        return false;
    }
    if (i <= 0) {
        return true;
    }
    int prevI = i;
    int prev = Utf8CodepointPrev(s, len, prevI);
    if (prev <= 32 || prev == 0x3000 || prev == 0x3002 || prev == 0xFF0C || prev == 0xFF1B) {
        return true;
    }
    // "1.全省人社各业务…" — 各 is part of the heading, not glued body.
    const char* t = s + i;
    if (str::StartsWith(t, "各") || str::StartsWith(t, "今")) {
        return false;
    }
    return true;
}

// "四、下一步工作计划 今后" / "计划今后"：标题后面粘上的正文开头。
static void StripGluedBodyAfterHeading(char* s) {
    if (!s || !s[0]) {
        return;
    }
    // GB 问答: "1.为贯彻落实…，各地应…哪些？" — 各地 is the question, not glued 各 body.
    if (str::Find(s, "\xEF\xBC\x9F") || str::Find(s, "?")) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.rank < 1 || m.prefixLength < 1) {
        return;
    }
    // 第N条 is already one sentence; "应按照…" is the article, not glued 一、 body.
    if (m.type == MarkerType::Article) {
        return;
    }
    int len = (int)str::Len(s);
    int i = m.prefixLength;
    SkipSpacesUtf8(s, len, i);
    int body0 = i;
    while (i < len) {
        if (GlyphCountRange(s, body0, i) >= 4 && BodyContinuationAt(s, len, i)) {
            // #region agent log
            if (Dbg92Interesting(s)) {
                char extra[96];
                snprintf(extra, (int)sizeof(extra), "cutAt=%d type=%d num=%d", i, (int)m.type, m.number);
                Dbg92a48e("V", "ExtractPdfToc.cpp:StripGluedBodyAfterHeading", s, extra);
            }
            // #endregion
            s[i] = 0;
            str::TrimWSInPlace(s, str::TrimOpt::Both);
            return;
        }
        int before = i;
        Utf8CodepointNext(s, len, i);
        if (i <= before) {
            break;
        }
    }
}

static bool LineEndsWithPeriod(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = len;
    int last = Utf8CodepointPrev(s, len, i);
    while (last > 0 && (last <= 32 || last == 0x3000)) {
        last = Utf8CodepointPrev(s, len, i);
    }
    return last == 0x3002;
}

static bool LineEndsLikeBodyContinuation(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = len;
    int last = Utf8CodepointPrev(s, len, i);
    while (last > 0 && (last <= 32 || last == 0x3000)) {
        last = Utf8CodepointPrev(s, len, i);
    }
    if (last == 0x3002 || last == 0xFF1B || last == ';') {
        return false;
    }
    return last >= 0x4E00 && last <= 0x9FFF;
}

static bool IsIdiomGlueCp(int cp) {
    return cp == 0x53CD || cp == 0x5408 || cp == 0x4E3A || cp == 0x4E0D || cp == 0x8FDE || cp == 0x6570 ||
           cp == 0x77E5; // 反 合 为 不 连 数 知
}

// "举一反" / "三口合" — last char glues a numeral idiom, and a numeral sits nearby.
static bool LineEndsLikeIdiomNumeralWrap(const char* s) {
    if (!LineEndsLikeBodyContinuation(s)) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = len;
    int last = Utf8CodepointPrev(s, len, i);
    while (last > 0 && (last <= 32 || last == 0x3000)) {
        last = Utf8CodepointPrev(s, len, i);
    }
    if (!IsIdiomGlueCp(last)) {
        return false;
    }
    bool hasNum = false;
    for (int n = 0; n < 3 && i > 0; n++) {
        int cp = Utf8CodepointPrev(s, len, i);
        if (IsCnNumeral(cp)) {
            hasNum = true;
            break;
        }
    }
    // "多报合" + "一、信息共享”" — 一 is on the next line, unlike 举一反.
    return hasNum || last == 0x5408;
}

// "实，回归备案事项本质属性" — wrapped "之实，回归…", not a title.
static bool LooksLikeSingleGlyphThenComma(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp < 0x4E00 || cp > 0x9FFF) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    int comma = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return comma == 0xFF0C || comma == ',';
}

// "信息共享”，严防…" — closing quote then comma/period, not 「一、“放管服”改革」.
static bool LooksLikeClosingQuoteThenPause(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp != 0x201D && cp != '"' && cp != 0x201C) {
            continue;
        }
        SkipSpacesUtf8(s, len, i);
        int next = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (next == 0xFF0C || next == ',' || next == 0x3002 || next == 0x3001) {
            return true;
        }
    }
    return false;
}

// "三、逐一解决；同时…" is a wrapped sentence, not 三、.
// "二、实，回归…" / "一、信息共享”，严防…" are the same class.
static bool LooksLikeDunhaoBodyRun(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::ChineseDunhao || m.prefixLength < 1) {
        return false;
    }
    const char* rest = s + m.prefixLength;
    if (str::Find(rest, "\xEF\xBC\x9B") || str::Find(rest, ";")) {
        return true;
    }
    return LooksLikeSingleGlyphThenComma(rest) || LooksLikeClosingQuoteThenPause(rest);
}

// "第二条第（二）款第2点规定执行" wrap is a citation, not （二）.
static bool LooksLikeOfficialTiaoKuanCite(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if ((m.type != MarkerType::ChineseParen && m.type != MarkerType::ArabicParen) || m.prefixLength < 1) {
        return false;
    }
    const char* rest = s + m.prefixLength;
    // "款第2点" / "款第2 点规定执行" / "项规定"
    if (str::StartsWith(rest, "款") || str::StartsWith(rest, "项")) {
        return true;
    }
    return str::StartsWith(rest, "点规定") || str::Find(rest, "款第") || str::Find(rest, "点规定执行");
}

static bool OfficialTitlesOverlapPrefix(const char* a, const char* b) {
    if (!a || !b || !a[0] || !b[0]) {
        return false;
    }
    return str::StartsWith(a, b) || str::StartsWith(b, a);
}

static void DedupOfficialOverlappingNumberedFlat(Vec<ExtractedTocItem*>& flat) {
    Vec<ExtractedTocItem*> keep;
    for (int i = 0; i < flat.Size(); i++) {
        ExtractedTocItem* a = flat[i];
        if (!a) {
            continue;
        }
        ExtractedTocItem* b = i + 1 < flat.Size() ? flat[i + 1] : nullptr;
        if (b && a->title && b->title && a->pageNo == b->pageNo) {
            HeadingMarker ma = ParseHeadingMarker(a->title);
            HeadingMarker mb = ParseHeadingMarker(b->title);
            if (ma.type == mb.type && ma.number == mb.number && ma.rank >= 1 && ma.type != MarkerType::None &&
                OfficialTitlesOverlapPrefix(a->title, b->title)) {
                // Prefer the longer title; skip only the duplicate, not the next sibling.
                if ((int)str::Len(a->title) >= (int)str::Len(b->title)) {
                    delete b;
                    i++;
                    keep.Append(a);
                } else {
                    delete a;
                    keep.Append(b);
                    i++;
                }
                continue;
            }
        }
        keep.Append(a);
    }
    flat.Reset();
    for (int i = 0; i < keep.Size(); i++) {
        flat.Append(keep[i]);
    }
}

// "…三口合" + "一、电子证照…" / "…举一反" + "三、逐一解决；"
// 折行把成语里的「一、」「三、」拆成假标题。
static bool ShouldMergeFalseYiDunhaoWrap(const ScanLine& a, const ScanLine& b) {
    if (a.srcPage != b.srcPage || !a.text || !b.text) {
        return false;
    }
    HeadingMarker mb = ParseHeadingMarker(b.text);
    if (mb.type != MarkerType::ChineseDunhao || mb.number < 1 || mb.number > 10 || mb.prefixLength < 1) {
        return false;
    }
    HeadingMarker ma = ParseHeadingMarker(a.text);
    if (ma.type == MarkerType::ChineseDunhao && ma.rank <= 2) {
        return false;
    }
    bool listOrPara = (ma.type == MarkerType::ArabicDot && ma.rank >= 3) || ma.rank < 1 ||
                      (ma.type == MarkerType::ArabicDot && GlyphCount(a.text) >= 8);
    if (!listOrPara || !LineEndsLikeBodyContinuation(a.text)) {
        return false;
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text)) {
        return false;
    }
    bool idiom = LineEndsLikeIdiomNumeralWrap(a.text);
    int last = LastNonSpaceCp(a.text);
    if (!idiom && last == 0x5408 && mb.number == 1) {
        idiom = true;
    }
    if (!idiom && last == 0x53CD && mb.number == 3) {
        idiom = true;
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * 1.55f : 14;
    float maxDx = 48;
    if (idiom) {
        lim = a.dy > 6 ? a.dy * 3.4f : 52;
        if (lim < 52) {
            lim = 52;
        }
        maxDx = 110;
    }
    if (gap < -a.dy * 0.35f || gap > lim) {
        return false;
    }
    float dx = a.x - b.x;
    if (dx < 0) {
        dx = -dx;
    }
    return dx <= maxDx;
}

// Table 序号 row "1 对照全国数据共享清单，根据…" is not 附件4-1 / a 清单 title.
static bool OfficialNameStartsWithTableSerial(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int n = ConsumeOfficialNumber(s, len, i);
    if (n < 1 || n > 80) {
        return false;
    }
    int sub = 0;
    int save = i;
    if (ConsumeOfficialAttachSubNumber(s, len, save, &sub) && sub >= 1) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return cp >= 0x4E00 && cp <= 0x9FFF;
}

static bool OfficialNameLooksLikeAttachmentIndex(const char* name) {
    if (!name || !name[0]) {
        return false;
    }
    if (OfficialNameStartsWithTableSerial(name)) {
        return false;
    }
    int g = GlyphCount(name);
    if (g < 2 || g > 48) {
        return false;
    }
    return str::EndsWith(name, "清单") || str::EndsWith(name, "名单") || str::EndsWith(name, "名册") ||
           str::EndsWith(name, "联系表") || str::EndsWith(name, "需求表") || str::EndsWith(name, "一览表") ||
           str::EndsWith(name, "统计表") || str::EndsWith(name, "明细表") || str::EndsWith(name, "流程图") ||
           str::EndsWith(name, "说明函") || str::EndsWith(name, "承诺书") || str::EndsWith(name, "申请书") ||
           str::EndsWith(name, "确认表") || str::EndsWith(name, "意见表") || str::EndsWith(name, "申请表") ||
           str::EndsWith(name, "合规性要求") || str::EndsWith(name, "程序") || str::EndsWith(name, "模板") ||
           str::EndsWith(name, "说明") || str::EndsWith(name, "流程") || str::EndsWith(name, "规范") ||
           str::EndsWith(name, "须知") || str::EndsWith(name, "指引") || str::EndsWith(name, "表");
}

// Bare 附件 + next line: 申请表, or an unmarked title such as 浙江省…“一本账S1”.
static bool LooksLikeOfficialAppendixHeadingName(const char* s) {
    if (OfficialNameLooksLikeAttachmentIndex(s)) {
        return true;
    }
    if (!s || !s[0] || OfficialNameStartsWithTableSerial(s) || LooksLikeOfficialBoilerplate(s) ||
        LooksLikeOfficialSpecOrFormLine(s) || LooksLikeOfficialFillNotesHeader(s) || LineLooksLikePageNumber(s) ||
        LooksLikeOfficialTableNoiseTitle(s)) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.rank >= 1) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 4 || g > 48) {
        return false;
    }
    if (str::Find(s, "。") || str::Find(s, "；") || str::Find(s, "，") || str::Find(s, ",")) {
        return false;
    }
    if (!HasLetterOrCjk(s)) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int first = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (first == 0x5BF9 || first == 0x9A7B) { // 对 驻 — table body
        return false;
    }
    if (str::Eq(s, "序号") || str::StartsWith(s, "序号") || str::Eq(s, "姓名") || str::Eq(s, "单位") ||
        str::Eq(s, "备注")) {
        return false;
    }
    return true;
}

// Body "1.报送《…》（见附件1）" is a task that cites 附件N, not 函末 "1.申请表".
static bool OfficialArabicDotLooksLikeAppendixCiteTask(const char* rest) {
    if (!rest || !rest[0]) {
        return false;
    }
    if (str::Find(rest, "见附件") || str::Find(rest, "详见附件") || str::Find(rest, "（见") || str::Find(rest, "(见")) {
        return true;
    }
    if (str::StartsWith(rest, "报送") || str::StartsWith(rest, "填报") || str::StartsWith(rest, "结合") ||
        str::StartsWith(rest, "开展") || str::StartsWith(rest, "总结")) {
        return true;
    }
    return TitleNeedsWrapContinuation(rest);
}

static bool OfficialAttachLineNameComplete(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    const char* rest = s;
    if (m.prefixLength > 0) {
        rest = s + m.prefixLength;
        int len = (int)str::Len(rest);
        int i = 0;
        SkipSpacesUtf8(rest, len, i);
        rest += i;
    }
    if (!rest[0]) {
        return false;
    }
    return OfficialNameLooksLikeAttachmentIndex(rest);
}

static bool LooksLikeOfficialTemplateParen(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    return str::Eq(s, "（模板）") || str::Eq(s, "(模板)") || str::Eq(s, "（模版）") || str::Eq(s, "(模版)");
}

// Lone title line "(征求意见稿）" / "（试行）" — glue onto the previous 附件 / 函 title.
static bool LooksLikeOfficialDraftParen(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (LooksLikeOfficialTemplateParen(s)) {
        return true;
    }
    int g = GlyphCount(s);
    if (g < 3 || g > 14) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int open = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (open != '(' && open != 0xFF08) {
        return false;
    }
    SkipSpacesUtf8(s, len, i);
    const char* mid = s + i;
    int midLen = (int)str::Len(mid);
    int j = midLen;
    int close = midLen > 0 ? Utf8CodepointPrev(mid, midLen, j) : 0;
    if (close != ')' && close != 0xFF09) {
        return false;
    }
    char* body = str::Dup(mid, j);
    if (!body) {
        return false;
    }
    str::TrimWSInPlace(body, str::TrimOpt::Both);
    bool ok = str::Eq(body, "征求意见稿") || str::Eq(body, "试行") || str::Eq(body, "暂行") ||
              str::Eq(body, "修订稿") || str::Eq(body, "讨论稿") || str::Eq(body, "草案");
    str::Free(body);
    return ok;
}

static bool ParseAppendixColonArabicList(const char* s, HeadingMarker* innerOut, const char** nameOut) {
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::Appendix || m.prefixLength < 1) {
        return false;
    }
    const char* rest = s + m.prefixLength;
    int len = (int)str::Len(rest);
    int i = 0;
    SkipSpacesUtf8(rest, len, i);
    int cp = i < len ? Utf8CodepointNext(rest, len, i) : 0;
    if (cp != ':' && cp != 0xFF1A) {
        return false;
    }
    SkipSpacesUtf8(rest, len, i);
    HeadingMarker inner = ParseHeadingMarker(rest + i);
    if (inner.type == MarkerType::ArabicDot && inner.number >= 1 && inner.prefixLength >= 1) {
        if (innerOut) {
            *innerOut = inner;
        }
        if (nameOut) {
            const char* name = rest + i + inner.prefixLength;
            int nlen = (int)str::Len(name);
            int ni = 0;
            SkipSpacesUtf8(name, nlen, ni);
            *nameOut = name + ni;
        }
        return true;
    }
    int serialMaj = 0;
    int serialSub = 0;
    const char* serialName = nullptr;
    if (!ParseOfficialAttachFormSerial(rest + i, &serialMaj, &serialSub, &serialName) || !serialName ||
        !serialName[0]) {
        return false;
    }
    inner = {};
    inner.type = MarkerType::ArabicDot;
    inner.number = serialMaj;
    inner.subNumber = serialSub;
    inner.prefixLength = (int)(serialName - (rest + i));
    inner.rank = 3;
    if (innerOut) {
        *innerOut = inner;
    }
    if (nameOut) {
        *nameOut = serialName;
    }
    return true;
}

// 函末「附件：全省…报名表」has no 1. — a manifest cite, not 附件1.
static const char* OfficialUnnumberedAppendixColonName(const char* s) {
    if (!s || !s[0] || ParseAppendixColonArabicList(s, nullptr, nullptr)) {
        return nullptr;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::Appendix || m.prefixLength < 1) {
        return nullptr;
    }
    const char* rest = s + m.prefixLength;
    int len = (int)str::Len(rest);
    int i = 0;
    SkipSpacesUtf8(rest, len, i);
    int cp = i < len ? Utf8CodepointNext(rest, len, i) : 0;
    if (cp != ':' && cp != 0xFF1A) {
        return nullptr;
    }
    SkipSpacesUtf8(rest, len, i);
    if (!rest[i]) {
        return nullptr;
    }
    HeadingMarker inner = ParseHeadingMarker(rest + i);
    if (inner.type == MarkerType::ArabicDot && inner.number >= 1) {
        return nullptr;
    }
    int g = GlyphCount(rest + i);
    if (g < 2 || g > 60 || str::Find(rest + i, "。")) {
        return nullptr;
    }
    return rest + i;
}

static bool LooksLikeOfficialUnnumberedAppendixColonCite(const char* s) {
    return OfficialUnnumberedAppendixColonName(s) != nullptr;
}

// True when "YYYY年…" is a 落款 date (2022年7月18日), not a title year (2026年工作要点).
static bool OfficialYearHitIsIssuerDate(const char* yhit) {
    if (!yhit || !yhit[0]) {
        return false;
    }
    int len = (int)str::Len(yhit);
    int i = 0;
    int nDig = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(yhit, len, i);
        if (!IsDigitCp(cp)) {
            i = save;
            break;
        }
        nDig++;
        if (nDig > 4) {
            return false;
        }
    }
    if (nDig < 4) {
        return false;
    }
    if (i >= len || !str::StartsWith(yhit + i, "\xE5\xB9\xB4")) { // 年
        return false;
    }
    i += (int)str::Len("\xE5\xB9\xB4");
    SkipSpacesUtf8(yhit, len, i);
    if (i >= len) {
        return true;
    }
    // Title years: 2026年工作要点 / 2021年网络安全…汇总表 / 2024年度考核
    if (str::StartsWith(yhit + i, "工作") || str::StartsWith(yhit + i, "度") || str::StartsWith(yhit + i, "计划") ||
        str::StartsWith(yhit + i, "规划") || str::StartsWith(yhit + i, "考核") || str::StartsWith(yhit + i, "要点") ||
        str::StartsWith(yhit + i, "网络") || str::StartsWith(yhit + i, "数据") || str::StartsWith(yhit + i, "政府")) {
        return false;
    }
    int save = i;
    int cp = Utf8CodepointNext(yhit, len, i);
    if (IsDigitCp(cp)) {
        while (i < len) {
            save = i;
            cp = Utf8CodepointNext(yhit, len, i);
            if (!IsDigitCp(cp)) {
                i = save;
                break;
            }
        }
        if (i < len && str::StartsWith(yhit + i, "\xE6\x9C\x88")) { // 月
            return true;
        }
        return false;
    }
    // Glued issuer after the year token is rare; keep cutting only for 中共.
    return str::StartsWith(yhit + i, "中共");
}

// RebuildVisualLines can glue 函末「附件：…」to 中共…办公厅 / 2022年7月18日.
static void TrimOfficialAppendixIssuerTail(char* s) {
    if (!s || !s[0]) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    char* body = s;
    if (m.type == MarkerType::Appendix && m.prefixLength > 0) {
        body = s + m.prefixLength;
        int blen = (int)str::Len(body);
        int bi = 0;
        SkipSpacesUtf8(body, blen, bi);
        int cp = bi < blen ? Utf8CodepointNext(body, blen, bi) : 0;
        if (cp == ':' || cp == 0xFF1A) {
            SkipSpacesUtf8(body, blen, bi);
            body += bi;
        }
    }
    if (!body[0]) {
        return;
    }
    const char* cut = str::Find(body, "中共");
    const char* yhit = nullptr;
    for (int y = 1990; y <= 2040; y++) {
        char buf[16];
        snprintf(buf, (int)sizeof(buf), "%d\xE5\xB9\xB4", y);
        const char* h = str::Find(body, buf);
        if (h && OfficialYearHitIsIssuerDate(h) && (!yhit || h < yhit)) {
            yhit = h;
        }
    }
    if (yhit && (!cut || yhit < cut)) {
        cut = yhit;
    }
    // 「2021年网络安全…汇总表」starts with a year — that is the title, not a 落款.
    int preG = 0;
    if (cut && cut > body) {
        char save = *cut;
        *(char*)cut = 0;
        preG = GlyphCount(body);
        *(char*)cut = save;
    }
    if (cut && cut != body && preG >= 8) {
        s[(int)(cut - s)] = 0;
        str::TrimWSInPlace(s, str::TrimOpt::Both);
    }
}

// Last 函末「附件：浙江省…一本账」name before a later bare 附件 heading.
static const char* OfficialAppendixCiteNameBefore(const Vec<ScanLine>& lines, int beforeIdx, int beforePage) {
    const char* best = nullptr;
    int lim = (beforeIdx >= 0 && beforeIdx <= lines.Size()) ? beforeIdx : lines.Size();
    for (int k = 0; k < lim; k++) {
        if (!lines[k].text) {
            continue;
        }
        if (beforePage >= 1 && lines[k].srcPage >= beforePage) {
            continue;
        }
        const char* name = OfficialUnnumberedAppendixColonName(lines[k].text);
        if (name && LooksLikeOfficialAppendixHeadingName(name)) {
            best = name;
        }
    }
    return best;
}

static bool LooksLikeOfficialFubiaoTitleLine(const char* s) {
    if (!s || !s[0] || LooksLikeOfficialBoilerplate(s) || LooksLikeOfficialSpecOrFormLine(s) ||
        LooksLikeOfficialFillNotesHeader(s) || LineLooksLikePageNumber(s)) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.rank >= 1) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 2 || g > 18) {
        return false;
    }
    if (str::Find(s, "。") || str::Find(s, "；")) {
        return false;
    }
    return HasLetterOrCjk(s);
}

static bool LooksLikeOfficialFubiaoTitleLine(const char* s);
static bool OfficialDocTitleNeedsWrap(const char* s);
static bool ShouldMergeOfficialAppendixTitleWrap(const ScanLine& a, const ScanLine& b) {
    if (a.srcPage != b.srcPage || !a.text || !b.text) {
        return false;
    }
    HeadingMarker mb = ParseHeadingMarker(b.text);
    if (mb.rank >= 1) {
        return false;
    }
    HeadingMarker ma = ParseHeadingMarker(a.text);
    bool colonList = ParseAppendixColonArabicList(a.text, nullptr, nullptr);
    if (ma.type != MarkerType::Appendix && ma.type != MarkerType::ArabicDot && ma.type != MarkerType::FormTable &&
        !colonList) {
        return false;
    }
    if (ma.type == MarkerType::ArabicDot && ma.number < 1) {
        return false;
    }
    int restG = ma.prefixLength > 0 ? GlyphCount(a.text + ma.prefixLength) : GlyphCount(a.text);
    bool aBare = (ma.type == MarkerType::Appendix || ma.type == MarkerType::FormTable) && restG < 2;
    bool aIndex = colonList || ma.type == MarkerType::ArabicDot;
    bool aFubiaoNeedName =
        ma.type == MarkerType::FormTable && restG >= 2 && restG <= 16 && !OfficialNameLooksLikeAttachmentIndex(a.text);
    const char* aRest = a.text + (ma.prefixLength > 0 ? ma.prefixLength : 0);
    int aRestLen = (int)str::Len(aRest);
    int aRi = 0;
    SkipSpacesUtf8(aRest, aRestLen, aRi);
    aRest += aRi;
    bool aNeedsTitleWrap =
        ma.type == MarkerType::Appendix && restG >= 2 &&
        (OfficialDocTitleNeedsWrap(aRest) || TitleNeedsWrapContinuation(a.text) || LooksLikeOfficialDraftParen(b.text));
    if (!aBare && !aIndex && !aFubiaoNeedName && !aNeedsTitleWrap) {
        return false;
    }
    // 9.…（模板） already complete: do not glue the next 表/承诺书 as a wrap.
    if (!aBare && OfficialAttachLineNameComplete(a.text) && !LooksLikeOfficialDraftParen(b.text) && !aNeedsTitleWrap) {
        return false;
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text)) {
        return false;
    }
    if (aBare && ma.type == MarkerType::FormTable) {
        if (!LooksLikeOfficialFubiaoTitleLine(b.text) && !OfficialNameLooksLikeAttachmentIndex(b.text)) {
            return false;
        }
    } else if (aFubiaoNeedName) {
        if (!LooksLikeOfficialFubiaoTitleLine(b.text) && !OfficialNameLooksLikeAttachmentIndex(b.text)) {
            return false;
        }
    } else if (aNeedsTitleWrap) {
        if (LooksLikeOfficialDraftParen(b.text)) {
            // ok
        } else if (!HasLetterOrCjk(b.text) || GlyphCount(b.text) > 36) {
            return false;
        }
    } else if (!OfficialNameLooksLikeAttachmentIndex(b.text) &&
               !(aBare && ma.type == MarkerType::Appendix && LooksLikeOfficialAppendixHeadingName(b.text))) {
        int bMajor = 0;
        int bSub = 0;
        const char* bName = nullptr;
        if (!(aBare && ma.type == MarkerType::Appendix &&
              ParseOfficialAttachFormSerial(b.text, &bMajor, &bSub, &bName) &&
              (ma.number < 1 || bMajor == ma.number))) {
            return false;
        }
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * (aBare || aFubiaoNeedName || aNeedsTitleWrap ? 3.2f : 1.55f) : 14;
    if ((aBare || aFubiaoNeedName || aNeedsTitleWrap) && lim < 36) {
        lim = 36;
    }
    if (gap < -a.dy * 0.85f || gap > lim) {
        return false;
    }
    float dx = a.x - b.x;
    if (dx < 0) {
        dx = -dx;
    }
    return dx <= (aBare || aFubiaoNeedName || aNeedsTitleWrap ? 220.f : 48.f);
}

static bool ScanLineLooksVerticalRun(const ScanLine& sl) {
    if (!sl.text || sl.dx < 1.f || sl.dy < 1.f) {
        return false;
    }
    return sl.dy > sl.dx * 2.2f && GlyphCount(sl.text) >= 6;
}

// Landscape 附件 is often left of a tall vertical title (一本账S1); y-gap wrap fails.
static int FindOfficialAppendixHeadingNameNear(const Vec<ScanLine>& lines, int markIdx) {
    if (markIdx < 0 || markIdx >= lines.Size() || !lines[markIdx].text) {
        return -1;
    }
    const ScanLine& a = lines[markIdx];
    HeadingMarker ma = ParseHeadingMarker(a.text);
    int restG = ma.prefixLength > 0 ? GlyphCount(a.text + ma.prefixLength) : GlyphCount(a.text);
    if (ma.type != MarkerType::Appendix || restG >= 2) {
        return -1;
    }
    int best = -1;
    float bestScore = -1e9f;
    for (int j = 0; j < lines.Size(); j++) {
        if (j == markIdx || !lines[j].text || lines[j].srcPage != a.srcPage) {
            continue;
        }
        int g = GlyphCount(lines[j].text);
        if (!LooksLikeOfficialAppendixHeadingName(lines[j].text) || g < 8) {
            continue;
        }
        float dx = a.x - lines[j].x;
        if (dx < 0) {
            dx = -dx;
        }
        bool vert = ScanLineLooksVerticalRun(lines[j]) || ScanLineLooksVerticalRun(a);
        if (dx > (vert ? 80.f : 220.f)) {
            continue;
        }
        if (!vert && !ShouldMergeOfficialAppendixTitleWrap(a, lines[j])) {
            // After /Rotate the title sits below 附件 with a gap wider than wrap.
            if (g < 10 || dx > 120.f) {
                continue;
            }
        }
        float score = (float)g * 2.f - dx;
        if (vert) {
            score += 40.f;
        }
        if (lines[j].fontSize > a.fontSize + 0.05f) {
            score += 15.f;
        }
        if (OfficialNameLooksLikeAttachmentIndex(lines[j].text)) {
            score += 80.f;
        }
        if (OfficialNameStartsWithTableSerial(lines[j].text)) {
            score -= 80.f;
        }
        float gapY = lines[j].y - a.y;
        if (gapY > 0 && gapY < 90.f) {
            score += 25.f;
        }
        if (score > bestScore) {
            bestScore = score;
            best = j;
        }
    }
    return best;
}

static bool LineLooksLikeQaAnswerStart(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    return str::StartsWith(s, "答") || str::StartsWith(s, "一是") || str::StartsWith(s, "二是") ||
           str::StartsWith(s, "三是") || str::StartsWith(s, "另外");
}

// 1. 2. 3. Q&A titles often wrap at 、， or mid-word; ？ means the question is complete.
static bool OfficialArabicDotTitleIncomplete(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::ArabicDot || m.rank < 3 || m.number < 1) {
        return false;
    }
    if (str::Find(s, "？") || str::Find(s, "?") || str::Find(s, "。") || str::Find(s, "！")) {
        return false;
    }
    if (TitleNeedsWrapContinuation(s)) {
        return true;
    }
    return LineEndsLikeBodyContinuation(s);
}

// Body wrap "坚持…和自我革新相结合" OCR'd as "1.和自我革新相结合、".
static bool OfficialArabicDotLooksLikeBodyWrap(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::ArabicDot || m.number < 1 || m.prefixLength < 1) {
        return false;
    }
    const char* rest = s + m.prefixLength;
    int rlen = (int)str::Len(rest);
    int ri = 0;
    SkipSpacesUtf8(rest, rlen, ri);
    rest += ri;
    if (!(str::StartsWith(rest, "和") || str::StartsWith(rest, "与") || str::StartsWith(rest, "及") ||
          str::StartsWith(rest, "或"))) {
        return false;
    }
    return TitleNeedsWrapContinuation(s) || GlyphCount(rest) <= 14;
}

// Unmarked wrap "和自我革新相结合、" — salvage must not invent "1.和…".
static bool OfficialLineLooksLikeConjunctionBodyWrap(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (OfficialArabicDotLooksLikeBodyWrap(s)) {
        return true;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    const char* rest = m.prefixLength > 0 ? s + m.prefixLength : s;
    int rlen = (int)str::Len(rest);
    int ri = 0;
    SkipSpacesUtf8(rest, rlen, ri);
    rest += ri;
    if (!(str::StartsWith(rest, "和") || str::StartsWith(rest, "与") || str::StartsWith(rest, "及") ||
          str::StartsWith(rest, "或"))) {
        return false;
    }
    return TitleNeedsWrapContinuation(s) || GlyphCount(rest) <= 14;
}

static bool ShouldMergeOfficialArabicDotTitleWrap(const ScanLine& a, const ScanLine& b) {
    if (!a.text || !b.text) {
        return false;
    }
    if (a.srcPage != b.srcPage && a.srcPage + 1 != b.srcPage) {
        return false;
    }
    if (!OfficialArabicDotTitleIncomplete(a.text)) {
        return false;
    }
    HeadingMarker mb = ParseHeadingMarker(b.text);
    if (mb.rank >= 1) {
        return false;
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text) || LineLooksLikeQaAnswerStart(b.text) ||
        LooksLikeDunhaoBodyRun(b.text)) {
        return false;
    }
    int gb = GlyphCount(b.text);
    if (gb < 2 || gb > 40) {
        return false;
    }
    if (a.srcPage != b.srcPage) {
        return b.y < 220.f;
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * 2.4f : 22;
    if (gap < -a.dy * 0.85f || gap > lim) {
        return false;
    }
    float dx = a.x - b.x;
    if (dx < 0) {
        dx = -dx;
    }
    return dx <= 80.f;
}

// Wrap leftover of 关于征求《…》的函: "征求〈江西省…王作要点" is not a bookmark.
static bool LooksLikeOfficialCoverTitleFragment(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (str::StartsWith(s, "关于") || str::StartsWith(s, "关千")) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 6 || g > 48) {
        return false;
    }
    bool openBook = (str::Find(s, "《") && !str::Find(s, "》")) || (str::Find(s, "〈") && !str::Find(s, "〉"));
    bool solicit = str::StartsWith(s, "征求") || str::StartsWith(s, "印发") || str::StartsWith(s, "转发");
    if (str::Find(s, "》") && (str::EndsWith(s, "的函") || str::EndsWith(s, "通知") || str::EndsWith(s, "意见") ||
                               str::EndsWith(s, "决定"))) {
        return false;
    }
    return solicit && (openBook || (!str::EndsWith(s, "的函") && !str::EndsWith(s, "通知") &&
                                    !str::EndsWith(s, "意见") && !str::EndsWith(s, "决定")));
}

static bool OfficialDocTitleNeedsWrap(const char* s);
static bool OfficialTitleHasDocSuffix(const char* s);

static bool OfficialDocTitleNeedsWrap(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (str::StartsWith(s, "根据") || str::StartsWith(s, "为做好") || str::StartsWith(s, "现将")) {
        return false;
    }
    if ((str::Find(s, "《") && !str::Find(s, "》")) || (str::Find(s, "〈") && !str::Find(s, "〉"))) {
        return true;
    }
    if (OfficialTitleIsIssuerBanner(s)) {
        return true;
    }
    // Split 规章 title: "江西省…国有资产" + "配置管理暂行办法"
    // Also "…数字政府建设" + "领导小组2026年工作要点" / "…领导小" + "组2026…"
    if (!OfficialTitleHasDocSuffix(s) && !str::Find(s, "。") && GlyphCount(s) >= 8 && GlyphCount(s) <= 40 &&
        (str::StartsWith(s, "江西") || str::StartsWith(s, "关于") || str::Find(s, "行政事业") ||
         str::Find(s, "国有资产") || str::Find(s, "数字政府") || str::Find(s, "政府职能") || str::EndsWith(s, "资产") ||
         str::EndsWith(s, "单位") || str::EndsWith(s, "机关") || str::EndsWith(s, "建设") ||
         str::EndsWith(s, "领导小") || str::EndsWith(s, "和"))) {
        return true;
    }
    if ((str::Find(s, "关于印发") || str::Find(s, "印发《") || str::StartsWith(s, "关于") ||
         str::StartsWith(s, "关千") ||
         (OfficialTitleFindGuanYu(s) && (str::StartsWith(s, "中共") || str::StartsWith(s, "江西省") ||
                                         str::StartsWith(s, "国务院") || str::StartsWith(s, "人力资源")))) &&
        !str::EndsWith(s, "通知") && !str::EndsWith(s, "的函") && !str::EndsWith(s, "请示") &&
        !str::EndsWith(s, "通报") && !str::EndsWith(s, "批复") && !str::EndsWith(s, "意见") &&
        !str::EndsWith(s, "决定")) {
        return true;
    }
    return false;
}

static bool OfficialDocTitleLooksComplete(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (!str::Find(s, "关于印发") && !str::Find(s, "印发《")) {
        return false;
    }
    if (str::Find(s, "《") && !str::Find(s, "》")) {
        return false;
    }
    return str::EndsWith(s, "通知") || str::EndsWith(s, "的函") || str::EndsWith(s, "请示") ||
           str::EndsWith(s, "通报") || str::EndsWith(s, "批复");
}

static bool OfficialDocTitleWrapTailLooksLikeBody(const char* s) {
    return str::StartsWith(s, "为确保") || str::StartsWith(s, "现将") || str::StartsWith(s, "现印发") ||
           str::StartsWith(s, "根据") || str::StartsWith(s, "为贯彻") || str::StartsWith(s, "为完善") ||
           str::StartsWith(s, "为规范") || str::StartsWith(s, "为做好") || str::StartsWith(s, "按照") ||
           str::StartsWith(s, "各省") || str::StartsWith(s, "国家税务总局各省");
}

// Body after a 规章 title: "…的部署要求，结合…制定本方案". Not a bookmark.
static bool LooksLikeOfficialDocPreamble(const char* s) {
    if (!s || !s[0] || ParseHeadingMarker(s).rank >= 1) {
        return false;
    }
    if (str::Find(s, "制定本方案") || str::Find(s, "制定本办法") || str::Find(s, "制定本细则") ||
        str::Find(s, "制定本规定") || str::Find(s, "的部署要求")) {
        return true;
    }
    return str::Find(s, "结合") && str::Find(s, "实际") && str::Find(s, "制定本");
}

// A line such as 《……通知》（国办发〔2015〕18号） is a citation of
// another document in the body, not the title of the document being read.
// Distinguishing patterns:
//   A. Starts with 《 / 〈 and carries a doc-number bracket after 》/〉.
//   B. Contains 《…》〔…〕号 + trailing body verb "要求"/"规定".
//   C. Truncated half-title that ends mid-doc-number like 〔2014〕 with
//      no closing 〕数字号 — a real title on its own line never ends
//      with a dangling bracket; this is always a body paragraph split
//      across OCR lines where we only grabbed the first fragment.
static bool LooksLikeOfficialQuotedDocumentCitation(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    // Pattern A: starts with 《 and carries a doc-number bracket after 》
    if (str::StartsWith(s, "《") || str::StartsWith(s, "〈")) {
        const char* close = str::Find(s, str::StartsWith(s, "《") ? "》" : "〉");
        if (close && close[3]) {
            const char* suffix = close + 3;
            if (str::Find(suffix, "〔") && (str::Find(suffix, "号") || str::Find(suffix, "发"))) {
                return true;
            }
        }
    }
    // Pattern B: 《…》〔…〕号 followed by body verb
    const char* open = str::Find(s, "《");
    if (!open) {
        open = str::Find(s, "〈");
    }
    if (open && str::Find(s, "〔") && str::Find(s, "号")) {
        if (str::Find(s, "要求") || str::Find(s, "规定") || str::Find(s, "等要求") ||
            str::Find(s, "有关要求") || str::Find(s, "有关规定")) {
            return true;
        }
    }
    // Pattern C (truncation): string contains 〔 but the final 〕 is not
    // followed by a digit — a real doc-number always continues with
    // 〕28号; if it ends right after 〕 we only got the first chunk of a
    // body paragraph split across OCR lines.
    int len = (int)str::Len(s);
    if (str::Find(s, "〔")) {
        // walk backwards from end looking for the final 〕
        int lastCloseIdx = -1;
        for (int idx = len - 1; idx >= 0; ) {
            int prev = idx;
            int cp = Utf8CodepointPrev(s, len, prev); // prev updated to start of prev codepoint
            if (cp == 0x3015 /* 〕 */) {
                lastCloseIdx = prev;
                break;
            }
            if (prev <= 0) break;
            idx = prev - 1;
        }
        if (lastCloseIdx >= 0) {
            if (lastCloseIdx + 3 >= len) {
                // 〕 is at the very end — truncated, no doc number
                return true;
            }
            char nc = s[lastCloseIdx + 3];
            if (!(nc >= '0' && nc <= '9')) {
                // 〕 followed by non-digit — doc number is incomplete
                return true;
            }
        }
    }
    return false;
}

static bool ShouldMergeOfficialDocTitleWrap(const ScanLine& a, const ScanLine& b) {
    if (!a.text || !b.text) {
        return false;
    }
    if (a.srcPage != b.srcPage && a.srcPage + 1 != b.srcPage) {
        return false;
    }
    if (!OfficialDocTitleNeedsWrap(a.text)) {
        return false;
    }
    if (ParseHeadingMarker(b.text).rank >= 1) {
        return false;
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text) || LooksLikeOfficialDocDateLine(b.text) ||
        OfficialDocTitleWrapTailLooksLikeBody(b.text) || LooksLikeOfficialDocPreamble(b.text) ||
        LooksLikeOfficialBoilerplate(b.text) || LooksLikeDocNumberLine(b.text)) {
        return false;
    }
    int gb = GlyphCount(b.text);
    if (gb < 2 || gb > 48) {
        return false;
    }
    if (a.srcPage != b.srcPage) {
        return b.y < 220.f;
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * 2.8f : 28;
    if (a.fontSize >= 16 && a.dy * 2.2f > lim) {
        lim = a.dy * 2.2f;
    }
    if (gap < -a.dy * 0.85f || gap > lim) {
        return false;
    }
    float dx = a.x - b.x;
    if (dx < 0) {
        dx = -dx;
    }
    float dc = (a.x + a.dx * 0.5f) - (b.x + b.dx * 0.5f);
    if (dc < 0) {
        dc = -dc;
    }
    return dx <= 100.f || dc <= 80.f;
}

static bool ShouldContinueOfficialFormTableTitle(const ScanLine& a, const ScanLine& b) {
    if (a.srcPage != b.srcPage || !a.text || !b.text) {
        return false;
    }
    if (ParseHeadingMarker(b.text).rank >= 1) {
        return false;
    }
    if (!LooksLikeOfficialFubiaoTitleLine(b.text)) {
        return false;
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * 2.4f : 22;
    if (gap < -a.dy * 0.5f || gap > lim) {
        return false;
    }
    return true;
}

static char* JoinAppendixNumberTitle(int n, const char* name, int sub = 0) {
    if (!name || !name[0] || n < 1) {
        return nullptr;
    }
    char prefix[40];
    if (sub >= 1) {
        snprintf(prefix, (int)sizeof(prefix), "\xE9\x99\x84\xE4\xBB\xB6%d-%d ", n, sub);
    } else {
        snprintf(prefix, (int)sizeof(prefix), "\xE9\x99\x84\xE4\xBB\xB6%d ", n);
    }
    return str::Join(prefix, name);
}

static char* JoinBareAppendixTitle(const char* name) {
    if (!name || !name[0]) {
        return nullptr;
    }
    return str::Format("附件 %s", name);
}

static char* RewriteAppendixColonListTitle(const char* s);

// "附件1 1-1.财政支出…" / leftover "-1.标题" after 附件1 → "附件1-1 财政支出…"
static void RewriteOfficialAppendixCompoundTitle(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type != MarkerType::Appendix || m.prefixLength < 1) {
        return;
    }
    if (m.number < 1) {
        char* rw = RewriteAppendixColonListTitle(s);
        if (rw) {
            str::Free(s);
            *titleOut = rw;
        }
        return;
    }
    const char* rest = s + m.prefixLength;
    int rlen = (int)str::Len(rest);
    int ri = 0;
    SkipSpacesUtf8(rest, rlen, ri);
    int colonAt = ri;
    int colon = ri < rlen ? Utf8CodepointNext(rest, rlen, ri) : 0;
    if (colon == ':' || colon == 0xFF1A) {
        SkipSpacesUtf8(rest, rlen, ri);
    } else {
        ri = colonAt;
    }
    int major = 0;
    int sub = 0;
    const char* name = nullptr;
    int useSub = m.subNumber;
    if (ParseOfficialAttachFormSerial(rest + ri, &major, &sub, &name) && name && name[0]) {
        if (major != m.number && !(m.subNumber >= 1 && major == m.subNumber)) {
            return;
        }
        useSub = sub >= 1 ? sub : m.subNumber;
    } else if (m.subNumber >= 1 && rest[ri]) {
        name = rest + ri;
    } else {
        return;
    }
    if (useSub < 1 || !name || !name[0]) {
        return;
    }
    char* joined = JoinAppendixNumberTitle(m.number, name, useSub);
    if (!joined) {
        return;
    }
    if (str::Eq(s, joined)) {
        str::Free(joined);
        return;
    }
    str::Free(s);
    *titleOut = joined;
}

static char* RewriteAppendixColonListTitle(const char* s) {
    HeadingMarker inner;
    const char* name = nullptr;
    if (!ParseAppendixColonArabicList(s, &inner, &name) || !name || !name[0]) {
        return nullptr;
    }
    if (!OfficialNameLooksLikeAttachmentIndex(name) && GlyphCount(name) < 6) {
        return nullptr;
    }
    return JoinAppendixNumberTitle(inner.number, name, inner.subNumber);
}

static char* RewriteArabicDotAsAppendixTitle(const char* s, int n) {
    HeadingMarker m = ParseHeadingMarker(s);
    const char* name = s;
    if (m.type == MarkerType::ArabicDot && m.prefixLength > 0) {
        name = s + m.prefixLength;
        int len = (int)str::Len(name);
        int i = 0;
        SkipSpacesUtf8(name, len, i);
        name += i;
    }
    return JoinAppendixNumberTitle(n, name);
}

// "二、…（填写" / "…填写附" — wrap before 附表N / 表三）.
static bool LineEndsWithFillFormWrap(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int last = LastNonSpaceCp(s);
    if (IsParenOpenCp(last)) {
        return true;
    }
    int len = (int)str::Len(s);
    int i = len;
    int g[3] = {};
    int n = 0;
    while (i > 0 && n < 3) {
        int cp = Utf8CodepointPrev(s, len, i);
        if (cp <= 32 || cp == 0x3000) {
            continue;
        }
        g[n++] = cp;
    }
    if (n >= 2 && g[1] == 0x586B && g[0] == 0x5199) { // 填写
        return true;
    }
    return n >= 3 && g[2] == 0x586B && g[1] == 0x5199 && g[0] == 0x9644; // 填写附
}

// "附表二），总结…" / "表三）。" — continuation of （填写附表N）, not a form heading.
static bool LineStartsWithWrappedFubiaoRef(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp == 0x9644) { // 附
        int cp2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (cp2 != 0x8868) { // 表
            return false;
        }
        ConsumeOfficialNumber(s, len, i);
        return NextNonSpaceIsParenClose(s, len, i);
    }
    if (cp != 0x8868) { // 表
        return false;
    }
    int n = ConsumeOfficialNumber(s, len, i);
    if (n < 1 || n > 40) {
        return false;
    }
    return NextNonSpaceIsParenClose(s, len, i);
}

static bool ShouldMergeOfficialFillFormWrap(const ScanLine& a, const ScanLine& b) {
    if (a.srcPage != b.srcPage || !a.text || !b.text) {
        return false;
    }
    HeadingMarker ma = ParseHeadingMarker(a.text);
    if (ma.type != MarkerType::ChineseDunhao && ma.type != MarkerType::ChineseParen &&
        ma.type != MarkerType::ArabicDot) {
        return false;
    }
    if (!LineEndsWithFillFormWrap(a.text) || !LineStartsWithWrappedFubiaoRef(b.text)) {
        return false;
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text)) {
        return false;
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * 1.55f : 14;
    if (gap < -a.dy * 0.35f || gap > lim) {
        return false;
    }
    float dx = a.x - b.x;
    if (dx < 0) {
        dx = -dx;
    }
    return dx <= 48;
}

// "2.填报《…表》（见" + "附件2)。" / "（模板" + "见附件1）。"
static bool LineEndsWithSeeAppendixWrap(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (str::Find(s, "见附件") || str::Find(s, "详见附件")) {
        return false;
    }
    int last = LastNonSpaceCp(s);
    if (last == 0x89C1) { // 见
        return true;
    }
    if (IsParenOpenCp(last)) {
        return true;
    }
    return str::EndsWith(s, "模板") && str::Find(s, "（");
}

static bool LineStartsWithSeeAppendixCite(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (LooksLikeOfficialAppendixCiteFragment(s)) {
        return true;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (cp == 0x8BE6) { // 详
        cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    }
    if (cp != 0x89C1) { // 见
        HeadingMarker m = ParseHeadingMarker(s);
        if (m.type == MarkerType::Appendix && m.number >= 1 && m.prefixLength > 0) {
            const char* rest = s + m.prefixLength;
            int rlen = (int)str::Len(rest);
            int ri = 0;
            return NextNonSpaceIsParenClose(rest, rlen, ri);
        }
        return false;
    }
    int fu = i < len ? Utf8CodepointNext(s, len, i) : 0;
    int jian = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return fu == 0x9644 && jian == 0x4EF6; // 附件
}

static bool ShouldMergeOfficialSeeAppendixWrap(const ScanLine& a, const ScanLine& b) {
    if (!a.text || !b.text) {
        return false;
    }
    if (b.srcPage < a.srcPage || b.srcPage > a.srcPage + 1) {
        return false;
    }
    HeadingMarker ma = ParseHeadingMarker(a.text);
    if (ma.type != MarkerType::ChineseDunhao && ma.type != MarkerType::ChineseParen &&
        ma.type != MarkerType::ArabicDot) {
        return false;
    }
    if (!LineEndsWithSeeAppendixWrap(a.text) || !LineStartsWithSeeAppendixCite(b.text)) {
        return false;
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text)) {
        return false;
    }
    if (b.srcPage == a.srcPage) {
        float gap = b.y - (a.y + a.dy);
        float lim = a.dy > 6 ? a.dy * 2.8f : 22;
        if (lim < 28) {
            lim = 28;
        }
        // Visual boxes are often taller than the leading, so "（模板" / "见附件"
        // overlap (gap negative). Still wrap if the next line is not above.
        if (b.y + 1.f < a.y || gap > lim) {
            return false;
        }
        float dx = a.x - b.x;
        if (dx < 0) {
            dx = -dx;
        }
        if (dx > 48) {
            return false;
        }
    } else if (b.y > 220) {
        return false;
    }
    return true;
}

static bool ShouldMergeHeadingLines(const ScanLine& a, const ScanLine& b) {
    if (a.srcPage != b.srcPage || !a.text || !b.text) {
        return false;
    }
    int ga = GlyphCount(a.text);
    int gb = GlyphCount(b.text);
    if (ga < 1 || ga > 36 || gb < 2 || gb > 40) {
        return false;
    }
    if (HeadingLevelFromText(a.text) < 1 || HeadingLevelFromText(b.text) > 0) {
        return false;
    }
    HeadingMarker ma = ParseHeadingMarker(a.text);
    if (ma.rank >= 1 && ma.prefixLength > 0) {
        int rest = GlyphCount(a.text + ma.prefixLength);
        // Wrapped titles are short fragments ("体系建设"). A complete heading
        // plus another title ("关于选择确定采购方式") is a sequence gap, not a wrap.
        if (rest >= 4 && gb > 5) {
            return false;
        }
    }
    if (!HasLetterOrCjk(b.text) || LineLooksLikePageNumber(b.text)) {
        return false;
    }
    if (LooksLikeBodyContinuationStart(b.text) || LineEndsWithPeriod(b.text)) {
        return false;
    }
    float gap = b.y - (a.y + a.dy);
    float lim = a.dy > 6 ? a.dy * 1.35f : 10;
    if (gap < -a.dy * 0.25f || gap > lim) {
        return false;
    }
    float dx = a.x - b.x;
    if (dx < 0) {
        dx = -dx;
    }
    float em = a.dy > 6.f ? a.dy : 12.f;
    // 正文首行缩进两字：不是标题折行。
    if (b.x >= a.x + em * 1.2f) {
        return false;
    }
    return dx <= 36;
}

static char* CandidateHeadingText(const Vec<ScanLine>& lines, int i) {
    if (i >= 0 && i + 1 < lines.Size() && ShouldMergeHeadingLines(lines[i], lines[i + 1])) {
        return str::Join(lines[i].text, " ", lines[i + 1].text);
    }
    return str::Dup(lines[i].text);
}

static bool LineInPageHeaderFooterBand(const ScanLine& sl, float yMin, float yMax) {
    float span = yMax - yMin;
    if (span < 8) {
        return false;
    }
    float top = yMin + span * 0.12f;
    float bot = yMax - span * 0.12f;
    return sl.y <= top || sl.y >= bot;
}

static void CollectHeaderTexts(const Vec<ScanLine>& lines, int nPages, StrVec& headers) {
    Vec<float> yMin;
    Vec<float> yMax;
    for (int p = 0; p <= nPages; p++) {
        yMin.Append(1e9f);
        yMax.Append(-1e9f);
    }
    for (int i = 0; i < lines.Size(); i++) {
        int p = lines[i].srcPage;
        if (p < 1 || p > nPages) {
            continue;
        }
        if (lines[i].y < yMin[p]) {
            yMin[p] = lines[i].y;
        }
        float y1 = lines[i].y + lines[i].dy;
        if (y1 > yMax[p]) {
            yMax[p] = y1;
        }
    }
    for (int i = 0; i < lines.Size(); i++) {
        const char* t = lines[i].text;
        if (!t || GlyphCount(t) > 18 || GlyphCount(t) < 2) {
            continue;
        }
        if (headers.Find(t) >= 0) {
            continue;
        }
        int nBand = 0;
        for (int j = 0; j < lines.Size(); j++) {
            if (!lines[j].text || !str::Eq(lines[j].text, t)) {
                continue;
            }
            int p = lines[j].srcPage;
            if (p < 1 || p > nPages) {
                continue;
            }
            if (!LineInPageHeaderFooterBand(lines[j], yMin[p], yMax[p])) {
                continue;
            }
            bool seen = false;
            for (int k = 0; k < j; k++) {
                if (lines[k].srcPage == p && lines[k].text && str::Eq(lines[k].text, t) &&
                    LineInPageHeaderFooterBand(lines[k], yMin[p], yMax[p])) {
                    seen = true;
                    break;
                }
            }
            if (!seen) {
                nBand++;
            }
        }
        int need = nPages >= 24 ? 4 : 3;
        if (nBand >= need) {
            headers.Append(t);
        }
    }
}

static bool IsHeaderText(StrVec& headers, const char* t) {
    return t && headers.Find(t) >= 0;
}

struct PrintedHit {
    char* title = nullptr;
    int printed = 0;
    int destPage = 0;
    int srcPage = 0;
    float x = 0;
    float y = 0;
    float srcX = 0;
    float srcY = 0;
    float indent = 0;
    float fontSize = 0;
    bool bold = false;
    int level = 1;
};

static void SortPrintedHits(Vec<PrintedHit>& hits);
static char* CleanTocTitle(const char* raw);

static bool HitLooksLikeBookBanner(const PrintedHit& h, float medFont, int nPaged, const PrintedHit* prev) {
    (void)nPaged;
    if (!h.title || !h.title[0] || h.printed > 0) {
        return false;
    }
    HeadingMarker m = ParseHeadingMarker(h.title);
    ParsedNumbering num;
    ParseHeadingNumbering(h.title, &num);
    if (m.type != MarkerType::None || num.nComp >= 1 || BookTitleIsSpine(h.title)) {
        return false;
    }
    if (prev && BookTitleIsSpine(prev->title) && LineLooksLikeChapterSubtitle(h.title)) {
        return false;
    }
    if (LineLooksLikeBookPartTitle(h.title)) {
        return true;
    }
    if (LineLooksLikeChapterSubtitle(h.title)) {
        return false;
    }
    int g = GlyphCount(h.title);
    if (g < 2 || g > 20) {
        return false;
    }
    bool bigFont = h.fontSize > 1 && medFont > 1 && h.fontSize >= medFont * 1.12f;
    bool fat = h.bold && (h.fontSize < 1 || h.fontSize >= medFont * 0.98f);
    return bigFont || fat;
}

static void ClusterBookIndentBands(const Vec<PrintedHit>& hits, const Vec<int>& skip, Vec<int>& bandOut,
                                   int* nBandsOut) {
    const float kGap = 18.f;
    bandOut.Reset();
    Vec<float> xs;
    for (int i = 0; i < hits.Size(); i++) {
        bandOut.Append(0);
        if (i < skip.Size() && skip[i]) {
            continue;
        }
        xs.Append(hits[i].srcX);
    }
    int nx = xs.Size();
    for (int i = 0; i < nx; i++) {
        for (int j = i + 1; j < nx; j++) {
            if (xs[j] < xs[i]) {
                float t = xs[i];
                xs[i] = xs[j];
                xs[j] = t;
            }
        }
    }
    Vec<float> starts;
    for (int i = 0; i < nx; i++) {
        if (starts.Size() == 0 || xs[i] - starts.Last() > kGap) {
            starts.Append(xs[i]);
        }
    }
    if (nBandsOut) {
        *nBandsOut = starts.Size();
    }
    for (int i = 0; i < hits.Size(); i++) {
        if (i < skip.Size() && skip[i]) {
            continue;
        }
        int b = 0;
        for (int k = starts.Size() - 1; k >= 0; k--) {
            if (hits[i].srcX + 1.f >= starts[k]) {
                b = k;
                break;
            }
        }
        bandOut[i] = b;
    }
}

static void AssignBookPrintedLevels(Vec<PrintedHit>& hits) {
    int n = hits.Size();
    if (n < 1) {
        return;
    }
    Vec<float> fonts;
    int nPaged = 0;
    for (int i = 0; i < n; i++) {
        if (hits[i].fontSize > 1) {
            fonts.Append(hits[i].fontSize);
        }
        if (hits[i].printed > 0) {
            nPaged++;
        }
    }
    float medFont = MedianPositive(fonts);
    if (medFont < 1) {
        medFont = 12;
    }
    Vec<int> isBanner;
    int nBanners = 0;
    for (int i = 0; i < n; i++) {
        int b = HitLooksLikeBookBanner(hits[i], medFont, nPaged, i > 0 ? &hits[i - 1] : nullptr) ? 1 : 0;
        isBanner.Append(b);
        if (b) {
            nBanners++;
        }
    }
    Vec<int> band;
    int nBands = 0;
    ClusterBookIndentBands(hits, isBanner, band, &nBands);
    int lastLevelForKey[90];
    for (int k = 0; k < 90; k++) {
        lastLevelForKey[k] = 0;
    }
    int prevLevel = 1;
    int leftoverLvl = nBanners > 0 ? 2 : 1;
    for (int i = 0; i < n; i++) {
        if (isBanner[i]) {
            hits[i].level = 1;
            prevLevel = 1;
            leftoverLvl = 2;
            for (int k = 0; k < 90; k++) {
                lastLevelForKey[k] = 0;
            }
            continue;
        }
        int numVal = 0;
        int key = BookPrintedSchemeKey(hits[i].title, &numVal);
        ParsedNumbering pn;
        ParseHeadingNumbering(hits[i].title, &pn);
        bool isChap = BookTitleIsSpine(hits[i].title);
        if (isChap) {
            hits[i].level = 1;
            prevLevel = 1;
            leftoverLvl = 2;
            for (int k = 0; k < 90; k++) {
                lastLevelForKey[k] = 0;
            }
            if (key > 0 && key < 90) {
                lastLevelForKey[key] = 1;
            }
            continue;
        }
        int lvl = leftoverLvl;
        if (key > 0 && nBands >= 2) {
            lvl = band[i] + leftoverLvl;
        }
        if (pn.nComp >= 2) {
            int fromNum = pn.nComp + (nBanners > 0 ? 1 : 0);
            if (fromNum > lvl) {
                lvl = fromNum;
            }
        }
        if (isChap && nBands < 2) {
            lvl = nBanners > 0 ? 2 : 1;
        }
        if (key > 0 && key < 90 && lastLevelForKey[key] > 0) {
            lvl = lastLevelForKey[key];
        } else if (key > 0 && i > 0 && !isChap) {
            bool prevChap = BookTitleIsSpine(hits[i - 1].title);
            int prevNum = 0;
            int prevKey = BookPrintedSchemeKey(hits[i - 1].title, &prevNum);
            if (prevChap || isBanner[i - 1] ||
                (nBands < 2 && numVal == 1 && prevKey != key && hits[i - 1].level >= 1)) {
                lvl = hits[i - 1].level + 1;
            }
        }
        if (lvl < 1) {
            lvl = 1;
        }
        if (lvl > prevLevel + 1) {
            lvl = prevLevel + 1;
        }
        if (lvl > 6) {
            lvl = 6;
        }
        hits[i].level = lvl;
        prevLevel = lvl;
        if (key > 0 && key < 90) {
            lastLevelForKey[key] = lvl;
        }
    }
}

static bool HitListHasSpineNumber(const Vec<PrintedHit>& hits, int n) {
    for (int i = 0; i < hits.Size(); i++) {
        if (BookSpineNumber(hits[i].title) == n) {
            return true;
        }
        HeadingMarker m = ParseHeadingMarker(hits[i].title);
        if (m.type == MarkerType::Chapter && m.number == n) {
            return true;
        }
    }
    return false;
}

static int BookSpineNumberFromLine(const char* s) {
    if (!s || !s[0]) {
        return 0;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type == MarkerType::Chapter && m.number > 0) {
        return m.number;
    }
    return BookSpineNumber(s);
}

static void RecoverMissingBookSpines(Vec<PrintedHit>& hits, const Vec<ScanLine>& lines, int tocStart, int nPages) {
    (void)tocStart;
    int nums[32];
    int nNums = 0;
    for (int i = 0; i < hits.Size(); i++) {
        int n = BookSpineNumberFromLine(hits[i].title);
        if (n < 1 || n > 30) {
            continue;
        }
        bool seen = false;
        for (int k = 0; k < nNums; k++) {
            if (nums[k] == n) {
                seen = true;
                break;
            }
        }
        if (!seen && nNums < 32) {
            nums[nNums++] = n;
        }
    }
    for (int i = 0; i < nNums; i++) {
        for (int j = i + 1; j < nNums; j++) {
            if (nums[j] < nums[i]) {
                int t = nums[i];
                nums[i] = nums[j];
                nums[j] = t;
            }
        }
    }
    for (int i = 0; i + 1 < nNums; i++) {
        for (int want = nums[i] + 1; want < nums[i + 1]; want++) {
            if (HitListHasSpineNumber(hits, want)) {
                continue;
            }
            int best = -1;
            for (int k = 0; k < lines.Size(); k++) {
                if (!lines[k].text || lines[k].srcPage < 1 || lines[k].srcPage > nPages) {
                    continue;
                }
                if (BookSpineNumberFromLine(lines[k].text) != want) {
                    continue;
                }
                if (best < 0 || lines[k].srcPage < lines[best].srcPage ||
                    (lines[k].srcPage == lines[best].srcPage && lines[k].y < lines[best].y)) {
                    best = k;
                }
            }
            if (best < 0) {
                continue;
            }
            PrintedHit h;
            h.title = CleanTocTitle(lines[best].text);
            if (!h.title || !h.title[0]) {
                str::Free(h.title);
                continue;
            }
            h.printed = 0;
            h.srcPage = lines[best].srcPage;
            h.srcX = lines[best].x;
            h.srcY = lines[best].y;
            h.indent = lines[best].x;
            h.fontSize = lines[best].fontSize;
            h.bold = lines[best].bold;
            hits.Append(h);
        }
    }
    SortPrintedHits(hits);
}

static void FreePrintedHits(Vec<PrintedHit>& hits) {
    for (int i = 0; i < hits.Size(); i++) {
        str::Free(hits[i].title);
    }
    hits.Reset();
}

static int EnforceMonotonicPrintedDests(Vec<PrintedHit>& hits) {
    int nFix = 0;
    int prev = 0;
    for (int i = 0; i < hits.Size(); i++) {
        int p = hits[i].destPage;
        if (p < 1) {
            if (prev > 0) {
                hits[i].destPage = prev;
                nFix++;
            }
            continue;
        }
        if (prev > 0 && p < prev) {
            hits[i].destPage = prev;
            nFix++;
            p = prev;
        }
        prev = p;
    }
    return nFix;
}

static char* CleanTocTitle(const char* raw) {
    char* s = DupTrimmed(raw);
    if (!s || !s[0]) {
        return s;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    int end = len;
    while (end > i) {
        int prev = end;
        int cp = Utf8CodepointPrev(s, len, prev);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            end = prev;
            continue;
        }
        break;
    }
    if (i > 0 || end < len) {
        int n = end - i;
        if (n < 1) {
            str::Free(s);
            return str::Dup("");
        }
        memmove(s, s + i, (size_t)n);
        s[n] = 0;
    }
    str::TrimWSInPlace(s, str::TrimOpt::Both);
    StripTrailingGluedPage(s);
    len = (int)str::Len(s);
    end = len;
    while (end > 0) {
        int prev = end;
        int cp = Utf8CodepointPrev(s, len, prev);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            end = prev;
            continue;
        }
        break;
    }
    if (end < len) {
        s[end] = 0;
    }
    str::TrimWSInPlace(s, str::TrimOpt::Both);
    StripTrailingOcrTitleJunk(s);
    return s;
}

static void SkipHeadingNumbering(const char* s, int len, int& i) {
    if (i >= len || !s) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s + i);
    if (m.rank > 0 && m.prefixLength > 0) {
        i += m.prefixLength;
        if (i > len) {
            i = len;
        }
    }
}

static void SkipWsUtf8(const char* s, int len, int& i) {
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 32 && cp != 0x3000) {
            i = save;
            return;
        }
    }
}

// Keep numbering + first clause. ，/： may start body, but a nearby 。/； means the
// comma is still inside the heading (（三）加强宣传引导，广泛推广应用。).
// 。/； always end the title (drop the mark and anything after, including a glued page number).
static bool IsLatinLetterCp(int cp) {
    return (cp >= 'A' && cp <= 'Z') || (cp >= 'a' && cp <= 'z') || (cp >= 0xFF21 && cp <= 0xFF3A) ||
           (cp >= 0xFF41 && cp <= 0xFF5A);
}

static int FirstNonSpaceCp(const char* s) {
    if (!s) {
        return 0;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp > 32 && cp != 0x3000) {
            return cp;
        }
    }
    return 0;
}

static int LastNonSpaceCp(const char* s) {
    if (!s || !s[0]) {
        return 0;
    }
    int len = (int)str::Len(s);
    int i = len;
    int cp = 0;
    while (i > 0) {
        cp = Utf8CodepointPrev(s, len, i);
        if (cp > 32 && cp != 0x3000) {
            return cp;
        }
    }
    return 0;
}

bool NeedsLatinJoinSpace(const char* left, const char* right) {
    if (!left || !right || !left[0] || !right[0]) {
        return false;
    }
    int last = LastNonSpaceCp(left);
    int first = FirstNonSpaceCp(right);
    if (last <= 32 || first <= 32) {
        return false;
    }
    if (first == '-' || first == 0x2013 || first == 0x2014) {
        return false;
    }
    return IsLatinLetterCp(last) && IsLatinLetterCp(first);
}

static bool EnglishParticleAt(const char* s, int* nOut) {
    if (nOut) {
        *nOut = 0;
    }
    const char* parts[] = {"the", "and", "of"};
    for (int p = 0; p < (int)dimof(parts); p++) {
        int n = (int)str::Len(parts[p]);
        if (!str::StartsWith(s, parts[p])) {
            continue;
        }
        unsigned char after = (unsigned char)s[n];
        if (after && after != ' ' && after != '-' && after != '.' && !(after >= 'A' && after <= 'Z')) {
            continue;
        }
        if (nOut) {
            *nOut = n;
        }
        return true;
    }
    return false;
}

// Restore Title Case word breaks when OCR/PDF dropped the narrow English spaces.
void InsertMissingEnglishWordSpaces(char** sOut) {
    char* s = sOut ? *sOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int latin = 0;
    int cjk = 0;
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (IsLatinLetterCp(cp)) {
            latin++;
        } else if (cp >= 0x4E00 && cp <= 0x9FFF) {
            cjk++;
        }
    }
    if (latin < 3 || cjk * 2 >= latin) {
        return;
    }
    char* dst = AllocArray<char>(len * 2 + 8);
    if (!dst) {
        return;
    }
    int o = 0;
    i = 0;
    int prevCp = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        int add = i - save;
        bool insert = false;
        if (prevCp >= 'a' && prevCp <= 'z' && cp >= 'A' && cp <= 'Z') {
            insert = true;
        }
        if (prevCp >= 'A' && prevCp <= 'Z' && cp >= 'A' && cp <= 'Z') {
            int peek = i;
            int nextCp = peek < len ? Utf8CodepointNext(s, len, peek) : 0;
            if (nextCp >= 'a' && nextCp <= 'z') {
                insert = true;
            }
        }
        if (prevCp >= 'a' && prevCp <= 'z') {
            int nPart = 0;
            if (EnglishParticleAt(s + save, &nPart)) {
                insert = true;
            }
        }
        if (insert) {
            dst[o++] = ' ';
        }
        if (add > 0) {
            memcpy(dst + o, s + save, (size_t)add);
            o += add;
        }
        prevCp = cp;
    }
    dst[o] = 0;
    str::Free(s);
    *sOut = dst;
}

static bool IsOcrPeriodLookalikeCp(int cp) {
    return cp == 'o' || cp == 'O' || cp == 0xFF4F || cp == 0xFF2F ||     // o O ｏ Ｏ
           cp == 0x25CB || cp == 0x3007 || cp == 0x25EF ||               // ○ 〇 ◯
           cp == 0x00B0 || cp == 0x00BA || cp == 0x2218 || cp == 0x25E6; // ° º ∘ ◦
}

static bool IsOcrMisreadPeriodO(const char* s, int len, int oStart, int afterO, int cp) {
    if (!IsOcrPeriodLookalikeCp(cp)) {
        return false;
    }
    bool latinO = cp == 'o' || cp == 'O' || cp == 0xFF4F || cp == 0xFF2F;
    if (!latinO) {
        return true;
    }
    int prevI = oStart;
    int prevCp = Utf8CodepointPrev(s, len, prevI);
    int nextCp = 0;
    if (afterO < len) {
        int t = afterO;
        nextCp = Utf8CodepointNext(s, len, t);
    }
    if (IsLatinLetterCp(prevCp) || IsLatinLetterCp(nextCp)) {
        return false;
    }
    return true;
}

// Trailing OCR speckle after a CJK title: "政策 o" / "工作 c" / "政策○".
static void StripTrailingOcrTitleJunk(char* s) {
    if (!s || !s[0]) {
        return;
    }
    for (int guard = 0; guard < 4; guard++) {
        int len = (int)str::Len(s);
        if (len < 1) {
            return;
        }
        int end = len;
        int cp = Utf8CodepointPrev(s, len, end);
        if (cp <= 32 || cp == 0x3000) {
            s[end] = 0;
            continue;
        }
        if (IsOcrPeriodLookalikeCp(cp) || cp == 0x3002) {
            int prevI = end;
            int prevCp = Utf8CodepointPrev(s, len, prevI);
            if (IsLatinLetterCp(prevCp)) {
                return;
            }
            s[end] = 0;
            str::TrimWSInPlace(s, str::TrimOpt::Both);
            continue;
        }
        if (IsLatinLetterCp(cp)) {
            int prevI = end;
            int prevCp = Utf8CodepointPrev(s, len, prevI);
            if (prevCp >= 0x4E00 && prevCp <= 0x9FFF) {
                s[end] = 0;
                str::TrimWSInPlace(s, str::TrimOpt::Both);
                continue;
            }
        }
        return;
    }
}

static bool IsTitleClauseBreak(const char* s, int len, int colonStart, int afterColon, int cp) {
    if (cp == 0x3002 || cp == 0xFF1B || cp == ';' || cp == 0xFF0C || cp == ',' || cp == 0xFF1F || cp == '?') {
        return true;
    }
    if (IsOcrMisreadPeriodO(s, len, colonStart, afterColon, cp)) {
        return true;
    }
    if (cp == 0xFF1A || cp == ':') { // ： :  only with a long body (see TrimTitleToFirstSentence)
        if (afterColon + 1 < len && s[afterColon] == '/' && s[afterColon + 1] == '/') {
            return false;
        }
        int prevI = colonStart;
        int prevCp = Utf8CodepointPrev(s, len, prevI);
        int nextCp = 0;
        if (afterColon < len) {
            int t = afterColon;
            nextCp = Utf8CodepointNext(s, len, t);
        }
        if (IsDigitCp(prevCp) && IsDigitCp(nextCp)) {
            return false;
        }
        return true;
    }
    return false;
}

// True if 。/；/; (or OCR o-as-period) appears within maxGlyphs after `from`.
static bool SentenceEndWithinGlyphs(const char* s, int len, int from, int maxGlyphs) {
    int i = from;
    int g = 0;
    while (i < len && g < maxGlyphs) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if (cp == 0x3002 || cp == 0xFF1B || cp == ';' || cp == 0xFF1F || cp == '?' ||
            IsOcrMisreadPeriodO(s, len, save, i, cp)) {
            return true;
        }
        g++;
    }
    return false;
}

// "11月底前，完成…" — list item 1. plus a deadline, not section 1.11.
static bool BodyStartsWithDeadlineLead(const char* s, int len, int i) {
    if (!s || i >= len) {
        return false;
    }
    int nDig = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (IsDigitCp(cp) || IsCnNumeral(cp)) {
            nDig++;
            if (nDig > 4) {
                return false;
            }
            continue;
        }
        i = save;
        break;
    }
    if (nDig < 1) {
        return false;
    }
    int unit = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (unit != 0x6708 && unit != 0x5E74) { // 月 年
        return false;
    }
    return str::Find(s, "底前") || str::Find(s, "日前");
}

static void TrimTitleToFirstSentence(char* s) {
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipWsUtf8(s, len, i);
    SkipHeadingNumbering(s, len, i);
    SkipWsUtf8(s, len, i);
    int bodyStart = i;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            return;
        }
        if (!IsTitleClauseBreak(s, len, save, i, cp)) {
            continue;
        }
        if (save <= bodyStart) {
            continue;
        }
        int prefixG = GlyphCountRange(s, bodyStart, save);
        int suffixG = GlyphCountRange(s, i, len);
        bool sentenceEnd = cp == 0x3002 || cp == 0xFF1B || cp == ';' || cp == 0xFF1F || cp == '?' ||
                           IsOcrMisreadPeriodO(s, len, save, i, cp);
        int titleG = GlyphCountRange(s, 0, save);
        if (sentenceEnd) {
            if (titleG < 2 || titleG > kExtractPdfToc.headingMaxGlyphs) {
                continue;
            }
        } else if (prefixG < 1 || prefixG > 40) {
            continue;
        }
        bool colon = cp == 0xFF1A || cp == ':';
        bool comma = cp == 0xFF0C || cp == ',';
        bool cut = false;
        const char* reason = "keep";
        if (sentenceEnd) {
            cut = true;
            reason = "sentence-end";
        } else if (comma && SentenceEndWithinGlyphs(s, len, i, 24)) {
            reason = "comma-before-period";
        } else if (comma && str::StartsWith(s + i, "请各")) {
            cut = true;
            reason = "comma-qingge";
        } else if (suffixG >= 12) {
            cut = true;
            reason = "suffix-long";
        } else if (suffixG == 0 && !colon) {
            cut = true;
            reason = "suffix-empty";
        }
        if (cut && comma && BodyStartsWithDeadlineLead(s, len, bodyStart)) {
            cut = false;
            reason = "deadline-lead";
        }
        if (cut) {
            s[save] = 0;
            str::TrimWSInPlace(s, str::TrimOpt::Both);
            return;
        }
        continue;
    }
}

// Meeting-minute （一）会议就《…》事宜… body: keep the quoted title, drop the rest.
static void CapClosedBookQuoteInTitle(char* s) {
    if (!s || !s[0]) {
        return;
    }
    const char* open = str::Find(s, "《");
    if (!open) {
        return;
    }
    const char* close = str::Find(open, "》");
    if (!close) {
        return;
    }
    int after = (int)(close - s) + 3;
    if (str::StartsWith(s + after, "事宜")) {
        after += 6;
    }
    if (!s[after]) {
        return;
    }
    if (GlyphCount(s + after) < 6) {
        return;
    }
    s[after] = 0;
    str::TrimWSInPlace(s, str::TrimOpt::Both);
}

static void RewriteOcrYiDashesInParenTitle(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int openStart = i;
    int openCp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsParenOpenCp(openCp)) {
        return;
    }
    int innerStart = i;
    int nDash = 0;
    while (i < len && nDash < 3) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (!IsOcrYiDashCp(cp)) {
            i = save;
            break;
        }
        nDash++;
    }
    if (nDash < 1) {
        return;
    }
    int closeStart = i;
    int closeCp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsParenCloseCp(closeCp)) {
        return;
    }
    char buf[768];
    int o = 0;
    if (openStart > 0) {
        if (openStart >= (int)sizeof(buf) - 16) {
            return;
        }
        memcpy(buf, s, (size_t)openStart);
        o = openStart;
    }
    int openBytes = innerStart - openStart;
    memcpy(buf + o, s + openStart, (size_t)openBytes);
    o += openBytes;
    memcpy(buf + o, "\xE4\xB8\x80", 3);
    o += 3;
    int restLen = len - closeStart;
    if (o + restLen + 1 >= (int)sizeof(buf)) {
        return;
    }
    memcpy(buf + o, s + closeStart, (size_t)restLen + 1);
    char* neu = str::Dup(buf);
    if (!neu) {
        return;
    }
    str::Free(s);
    *titleOut = neu;
}

// OCR "—、体制机制" / "-、工作要求" → "一、…"
static void RewriteOcrDashAsYiDunhao(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int dashStart = i;
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsOcrYiDashCp(cp)) {
        return;
    }
    int dashEnd = i;
    SkipSpacesUtf8(s, len, i);
    int sep = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsDunhaoSepCp(sep)) {
        return;
    }
    char buf[768];
    int o = 0;
    if (dashStart > 0) {
        if (dashStart >= (int)sizeof(buf) - 16) {
            return;
        }
        memcpy(buf, s, (size_t)dashStart);
        o = dashStart;
    }
    buf[o++] = '\xE4';
    buf[o++] = '\xB8';
    buf[o++] = '\x80';
    int rest = (int)str::Len(s + dashEnd) + 1;
    if (o + rest > (int)sizeof(buf)) {
        return;
    }
    memcpy(buf + o, s + dashEnd, (size_t)rest);
    char* neu = str::Dup(buf);
    if (!neu) {
        return;
    }
    str::Free(s);
    *titleOut = neu;
}

// Table banners "二｀政策措施 (16 项）": 顿号 drawn as ｀ / backtick.
static void RewriteOcrGraveAsDunhao(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int numAt = i;
    int n = ConsumeOfficialNumber(s, len, i);
    if (n < 1) {
        return;
    }
    int peek = numAt;
    int first = peek < len ? Utf8CodepointNext(s, len, peek) : 0;
    if (!IsCnNumeral(first)) {
        return;
    }
    SkipSpacesUtf8(s, len, i);
    int sepStart = i;
    int sep = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsOcrDunhaoLookalikeCp(sep)) {
        return;
    }
    int sepEnd = i;
    char buf[768];
    int o = 0;
    if (sepStart > 0) {
        if (sepStart >= (int)sizeof(buf) - 8) {
            return;
        }
        memcpy(buf, s, (size_t)sepStart);
        o = sepStart;
    }
    buf[o++] = '\xE3';
    buf[o++] = '\x80';
    buf[o++] = '\x81';
    int rest = (int)str::Len(s + sepEnd) + 1;
    if (o + rest > (int)sizeof(buf)) {
        return;
    }
    memcpy(buf + o, s + sepEnd, (size_t)rest);
    char* neu = str::Dup(buf);
    if (!neu) {
        return;
    }
    str::Free(s);
    *titleOut = neu;
}

static void StripOcrJunkBeforeAppendix(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    if (ParseHeadingMarker(s).type == MarkerType::Appendix) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipWsUtf8(s, len, i);
    int nGlyph = 0;
    while (i < len && nGlyph < 2) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp == 0x9644) { // 附
            i = save;
            break;
        }
        if (cp == 0x89C1 || cp == 0x8BE6) { // 见 详 — "见附件1）。" wrap, not OCR junk
            return;
        }
        if (IsDigitCp(cp) || IsCnNumeral(cp) || IsParenOpenCp(cp)) {
            return;
        }
        nGlyph++;
    }
    if (nGlyph != 1 || i >= len) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s + i);
    if (m.type != MarkerType::Appendix || m.number < 1) {
        return;
    }
    char* neu = str::Dup(s + i);
    if (!neu) {
        return;
    }
    // #region agent log
    DbgFace09("A", "ExtractPdfToc.cpp:StripOcrJunkBeforeAppendix", s, neu);
    // #endregion
    str::Free(s);
    *titleOut = neu;
}

static void RewriteOcrAppendixBang(char** titleOut) {
    StripOcrJunkBeforeAppendix(titleOut);
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0] || !str::Find(s, "\xE9\x99\x84\xE4\xBB\xB6")) {
        RewriteOfficialAppendixCompoundTitle(titleOut);
        return;
    }
    int len = (int)str::Len(s);
    char buf[1024];
    int i = 0;
    int o = 0;
    bool hit = false;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (o + (i - save) + 8 >= (int)sizeof(buf)) {
            return;
        }
        if (cp != 0x9644) {
            memcpy(buf + o, s + save, (size_t)(i - save));
            o += i - save;
            continue;
        }
        int afterFu = i;
        int cp2 = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (cp2 != 0x4EF6) {
            memcpy(buf + o, s + save, (size_t)(afterFu - save));
            o += afterFu - save;
            i = afterFu;
            continue;
        }
        memcpy(buf + o, s + save, (size_t)(i - save));
        o += i - save;
        int sp = i;
        SkipSpacesUtf8(s, len, i);
        if (o + (i - sp) + 4 >= (int)sizeof(buf)) {
            return;
        }
        memcpy(buf + o, s + sp, (size_t)(i - sp));
        o += i - sp;
        int bangAt = i;
        int bang = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (bang == '!' || bang == 0xFF01) {
            buf[o++] = '1';
            hit = true;
            continue;
        }
        if (bang == 0x5DDD) { // 川：OCR of 11
            buf[o++] = '1';
            buf[o++] = '1';
            hit = true;
            continue;
        }
        i = bangAt;
    }
    if (!hit) {
        RewriteOfficialAppendixCompoundTitle(titleOut);
        return;
    }
    buf[o] = 0;
    char* neu = str::Dup(buf);
    if (!neu) {
        RewriteOfficialAppendixCompoundTitle(titleOut);
        return;
    }
    // #region agent log
    Dbg92a48e("P", "ExtractPdfToc.cpp:RewriteOcrAppendixBang", s, neu);
    // #endregion
    str::Free(s);
    *titleOut = neu;
    RewriteOfficialAppendixCompoundTitle(titleOut);
}

// PDF/OCR often emits "l ．标题" / "I.标题" for list item 1. Only rewrite when the rest is CJK.
static bool IsOcrDigitOneLookalikeCp(int cp) {
    return cp == 'l' || cp == 'I' || cp == '|' || cp == 0xFF4C || cp == 0xFF29 || cp == 0xFF5C || cp == 0x4E28 ||
           cp == 0x2502;
}

static bool RestHasCjkGlyph(const char* s) {
    if (!s) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
        if ((cp >= 0x4E00 && cp <= 0x9FFF) || (cp >= 0x3400 && cp <= 0x4DBF)) {
            return true;
        }
    }
    return false;
}

static void RewriteOcrLetterAsListOne(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int letStart = i;
    int cp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsOcrDigitOneLookalikeCp(cp)) {
        return;
    }
    int letEnd = i;
    SkipSpacesUtf8(s, len, i);
    int dot = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (dot != '.' && dot != 0xFF0E && dot != 0x3002) {
        return;
    }
    SkipSpacesUtf8(s, len, i);
    if (!RestHasCjkGlyph(s + i)) {
        return;
    }
    int prefix = letStart;
    int rest = letEnd;
    int neuLen = prefix + 1 + (len - rest) + 1;
    char* neu = AllocArray<char>(neuLen);
    if (!neu) {
        return;
    }
    if (prefix > 0) {
        memcpy(neu, s, (size_t)prefix);
    }
    neu[prefix] = '1';
    memcpy(neu + prefix + 1, s + rest, (size_t)(len - rest + 1));
    // #region agent log
    {
        char extra[96];
        snprintf(extra, (int)sizeof(extra), "lookalike=U+%04X", cp);
        DbgFace09("Q", "ExtractPdfToc.cpp:RewriteOcrLetterAsListOne", neu, extra);
    }
    // #endregion
    str::Free(s);
    *titleOut = neu;
}

static void CapNumberedHeadingTitle(char* s) {
    if (!s || !s[0]) {
        return;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type == MarkerType::ArabicDot && m.rank >= 3) {
        CapTitleAfterNumbering(s, 40);
    } else if (m.type == MarkerType::ChineseDunhao && GlyphCount(s) > 24) {
        CapTitleAfterNumbering(s, 16);
    } else if (m.type == MarkerType::Article) {
        CapTitleAfterNumbering(s, 32);
    } else if (m.type == MarkerType::ChineseParen) {
        CapClosedBookQuoteInTitle(s);
        if (GlyphCount(s) > 32) {
            CapTitleAfterNumbering(s, 32);
        }
    }
}

static void TrimAtNextDiHeading(char* s) {
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipWsUtf8(s, len, i);
    SkipHeadingNumbering(s, len, i);
    SkipWsUtf8(s, len, i);
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            return;
        }
        if (cp != 0x7B2C) {
            continue;
        }
        int nNum = 0;
        while (i < len) {
            int t = i;
            int n = Utf8CodepointNext(s, len, i);
            if (IsDigitCp(n) || IsCnNumeral(n)) {
                nNum++;
                continue;
            }
            i = t;
            break;
        }
        int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
        if (nNum > 0 && DepthFromDiUnit(mark) > 0 && save > 0) {
            s[save] = 0;
            str::TrimWSInPlace(s, str::TrimOpt::Both);
            return;
        }
    }
}

static bool IsEmbeddedHeadingBoundaryCp(int cp) {
    return cp <= 32 || cp == 0x3000 || cp == 0x3002 || cp == 0xFF1A || cp == ':' || cp == 0xFF1B || cp == ';' ||
           cp == 0xFF0C || cp == ',';
}

static int FindNextEmbeddedHeading(const char* s) {
    if (!s || !s[0]) {
        return -1;
    }
    HeadingMarker first = ParseHeadingMarker(s);
    int len = (int)str::Len(s);
    int bodyStart = 0;
    int firstRank = 0;
    int i = 0;
    if (first.rank >= 1 && first.prefixLength >= 1) {
        bodyStart = first.prefixLength;
        SkipWsUtf8(s, len, bodyStart);
        i = bodyStart;
        firstRank = first.rank;
    }
    while (i < len) {
        int save = i;
        HeadingMarker m = ParseHeadingMarker(s + save);
        if (m.rank >= 1 && m.number > 0 && m.number < 100 && m.prefixLength > 0 && save > 0) {
            int prevI = save;
            int prev = Utf8CodepointPrev(s, len, prevI);
            bool afterBoundary = IsEmbeddedHeadingBoundaryCp(prev);
            int leadG = GlyphCountRange(s, 0, save);
            int bodyG = firstRank >= 1 ? GlyphCountRange(s, bodyStart, save) : leadG;
            const char* rest = s + save + m.prefixLength;
            int restG = GlyphCount(rest);
            if (HasLetterOrCjk(rest) && restG >= 4 && !(m.type == MarkerType::FormTable && !afterBoundary)) {
                if (firstRank >= 1) {
                    bool spaceBefore = prev <= 32 || prev == 0x3000;
                    if (m.rank > firstRank && bodyG >= 4 && bodyG <= 40 && restG <= 80 && (spaceBefore || bodyG >= 6)) {
                        return save;
                    }
                    // Same-rank 公文 enumerations: "（1）…；（2）…；（3）…"
                    if (m.rank >= 1 && afterBoundary && bodyG >= 2) {
                        return save;
                    }
                } else if (afterBoundary && leadG >= 2) {
                    SkipWsUtf8(s, len, save);
                    return save;
                } else if (firstRank < 1 && leadG >= 6 && m.type == MarkerType::ChineseParen && restG >= 6 &&
                           !LooksLikeOfficialTiaoKuanCite(s + save)) {
                    // 财政局…本（一）地方政府… — wrap leftover glued onto the heading.
                    return save;
                }
            }
        }
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 0) {
            break;
        }
    }
    return -1;
}

static void TrimAtNextEmbeddedHeading(char* s) {
    int split = FindNextEmbeddedHeading(s);
    if (split < 1 || !s) {
        return;
    }
    s[split] = 0;
    str::TrimWSInPlace(s, str::TrimOpt::Both);
}

static void NormalizeTocNumberingParens(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipWsUtf8(s, len, i);
    int openStart = i;
    int openCp = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (!IsParenOpenCp(openCp)) {
        return;
    }
    int innerStart = i;
    int afterClose = innerStart;
    if (!ConsumeParenNumberingAfterOpen(s, len, afterClose)) {
        return;
    }
    int closeStart = afterClose;
    int closeCp = Utf8CodepointPrev(s, len, closeStart);
    if (!IsParenCloseCp(closeCp)) {
        return;
    }
    if (openCp == 0xFF08 && closeCp == 0xFF09) {
        return;
    }
    int innerLen = closeStart - innerStart;
    if (innerLen < 1) {
        return;
    }
    char buf[512];
    int o = 0;
    if (openStart > 0) {
        if (openStart >= (int)sizeof(buf) - 8) {
            return;
        }
        memcpy(buf, s, (size_t)openStart);
        o = openStart;
    }
    memcpy(buf + o, "\xEF\xBC\x88", 3);
    o += 3;
    if (o + innerLen + 4 >= (int)sizeof(buf)) {
        return;
    }
    memcpy(buf + o, s + innerStart, (size_t)innerLen);
    o += innerLen;
    memcpy(buf + o, "\xEF\xBC\x89", 3);
    o += 3;
    int restLen = len - afterClose;
    if (restLen > 0) {
        if (o + restLen + 1 >= (int)sizeof(buf)) {
            return;
        }
        memcpy(buf + o, s + afterClose, (size_t)restLen);
        o += restLen;
    }
    buf[o] = 0;
    char* neu = str::Dup(buf);
    if (!neu) {
        return;
    }
    str::Free(s);
    *titleOut = neu;
}

static bool IsNumberingDotCp(int cp) {
    return cp == '.' || cp == 0xFF0E || cp == 0x3002 || cp == 0x2024;
}

static bool IsHeadingNumTokenCp(int cp) {
    return IsDigitCp(cp) || IsCnNumeral(cp);
}

static int ReplaceAllFullwidthDotsInTocTitle(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return 0;
    }
    int n = 0;
    char* r = s;
    char* w = s;
    while (*r) {
        if ((unsigned char)r[0] == 0xEF && (unsigned char)r[1] == 0xBC && (unsigned char)r[2] == 0x8E) {
            *w++ = '.';
            r += 3;
            n++;
            continue;
        }
        *w++ = *r++;
    }
    *w = 0;
    return n;
}

static void ReplaceFullwidthDotsInExtractedTree(Vec<ExtractedTocItem*>& nodes) {
    for (int i = 0; i < nodes.Size(); i++) {
        ExtractedTocItem* n = nodes[i];
        if (!n) {
            continue;
        }
        ReplaceAllFullwidthDotsInTocTitle(&n->title);
        ReplaceFullwidthDotsInExtractedTree(n->children);
    }
}

// "1．2．3 标题" / "1。成绩册" / "一．主要任务" → halfwidth '.'
void NormalizeTocNumberingDotsHalfwidth(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipWsUtf8(s, len, i);
    int start = i;
    if (start >= len) {
        ReplaceAllFullwidthDotsInTocTitle(titleOut);
        return;
    }
    int peek = start;
    int first = Utf8CodepointNext(s, len, peek);
    if (!IsHeadingNumTokenCp(first)) {
        int nAll = ReplaceAllFullwidthDotsInTocTitle(titleOut);
        // #region agent log
        if (nAll > 0 || DbgFace09Hit(*titleOut)) {
            char extra[80];
            snprintf(extra, (int)sizeof(extra), "prefixSkip first=U+%04X globalN=%d", first, nAll);
            DbgFace09("P", "ExtractPdfToc.cpp:NormalizeTocNumberingDotsHalfwidth.prefixSkip", *titleOut, extra);
        }
        // #endregion
        return;
    }
    char buf[512];
    if (start >= (int)sizeof(buf) - 8) {
        ReplaceAllFullwidthDotsInTocTitle(titleOut);
        return;
    }
    int o = 0;
    if (start > 0) {
        memcpy(buf, s, (size_t)start);
        o = start;
    }
    bool sawNum = false;
    bool changed = false;
    int k = start;
    while (k < len) {
        if (o >= (int)sizeof(buf) - 8) {
            break;
        }
        int save = k;
        int cp = Utf8CodepointNext(s, len, k);
        if (cp <= 0) {
            break;
        }
        if (IsHeadingNumTokenCp(cp)) {
            int n = k - save;
            if (o + n >= (int)sizeof(buf) - 1) {
                break;
            }
            memcpy(buf + o, s + save, (size_t)n);
            o += n;
            sawNum = true;
            continue;
        }
        if (sawNum && IsNumberingDotCp(cp)) {
            buf[o++] = '.';
            if (cp != '.') {
                changed = true;
            }
            continue;
        }
        int rest = len - save;
        if (o + rest + 1 >= (int)sizeof(buf)) {
            break;
        }
        memcpy(buf + o, s + save, (size_t)rest);
        o += rest;
        break;
    }
    buf[o] = 0;
    if (changed) {
        char* neu = str::Dup(buf);
        if (neu) {
            str::Free(s);
            *titleOut = neu;
        }
    }
    int nAll = ReplaceAllFullwidthDotsInTocTitle(titleOut);
    // #region agent log
    if (nAll > 0 || DbgFace09Hit(*titleOut)) {
        char extra[96];
        snprintf(extra, (int)sizeof(extra), "first=U+%04X prefixChanged=%d globalN=%d", first, changed ? 1 : 0, nAll);
        DbgFace09("P", "ExtractPdfToc.cpp:NormalizeTocNumberingDotsHalfwidth.dots", *titleOut, extra);
    }
    // #endregion
}

static void NormalizeTocNumberingDots(char** titleOut) {
    NormalizeTocNumberingDotsHalfwidth(titleOut);
}

static void StripNumberingTitleSpace(char** titleOut) {
    char* s = titleOut ? *titleOut : nullptr;
    if (!s || !s[0]) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipWsUtf8(s, len, i);
    int digStart = i;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (!IsDigitCp(cp)) {
            i = save;
            break;
        }
    }
    int afterDig = i;
    int afterWs = afterDig;
    SkipWsUtf8(s, len, afterWs);
    if (afterDig > digStart && afterWs > afterDig) {
        int t = afterWs;
        int mark = t < len ? Utf8CodepointNext(s, len, t) : 0;
        if (IsSimpleArabicListSepCp(mark)) {
            memmove(s + afterDig, s + afterWs, (size_t)(len - afterWs + 1));
            len = (int)str::Len(s);
        }
    }
    i = 0;
    SkipWsUtf8(s, len, i);
    SkipHeadingNumbering(s, len, i);
    int prefixEnd = i;
    if (prefixEnd < 1) {
        return;
    }
    int prev = prefixEnd;
    int last = Utf8CodepointPrev(s, len, prev);
    if (!IsSimpleArabicListSepCp(last)) {
        return;
    }
    int body = prefixEnd;
    SkipWsUtf8(s, len, body);
    if (body <= prefixEnd) {
        return;
    }
    memmove(s + prefixEnd, s + body, (size_t)(len - body + 1));
}

static bool LooksLikeStandaloneNumbering(const char* s) {
    if (!s || HeadingLevelFromText(s) < 1) {
        return false;
    }
    int g = GlyphCount(s);
    if (g < 1 || g > 8) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    SkipHeadingNumbering(s, len, i);
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    return i >= len;
}

static char* TitleWithLeftNumbering(const Vec<ScanLine>& lines, const Vec<int>& idx, Vec<int>& used, int titleSlot,
                                    int* attachedOut) {
    if (attachedOut) {
        *attachedOut = 0;
    }
    char* cleaned = CleanTocTitle(lines[idx[titleSlot]].text);
    const ScanLine& title = lines[idx[titleSlot]];
    if (HeadingLevelFromText(cleaned) > 0) {
        return cleaned;
    }
    int best = -1;
    float bestX = -1e9f;
    for (int t = 0; t < idx.Size(); t++) {
        if (used[t] || t == titleSlot) {
            continue;
        }
        const ScanLine& n = lines[idx[t]];
        if (!LooksLikeStandaloneNumbering(n.text) || LineLooksLikePageNumber(n.text)) {
            continue;
        }
        if (!SamePrintedTocRow(n, title)) {
            continue;
        }
        if (n.x >= title.x - 2) {
            continue;
        }
        if (n.x > bestX) {
            bestX = n.x;
            best = t;
        }
    }
    if (best < 0) {
        return cleaned;
    }
    used[best] = 1;
    if (attachedOut) {
        *attachedOut = 1;
    }
    char* num = CleanTocTitle(lines[idx[best]].text);
    bool tight = false;
    if (num && num[0] && cleaned && cleaned[0]) {
        int nlen = (int)str::Len(num);
        int ni = nlen;
        int last = Utf8CodepointPrev(num, nlen, ni);
        int ci = 0;
        int clen = (int)str::Len(cleaned);
        int first = Utf8CodepointNext(cleaned, clen, ci);
        if ((last == '.' || last == 0xFF0E || IsDigitCp(last)) && IsDigitCp(first)) {
            tight = true;
        }
    }
    char* joined = tight ? str::Join(num, cleaned) : str::Join(num, " ", cleaned);
    str::Free(num);
    str::Free(cleaned);
    return joined;
}

static void AppendPairedTocHit(Vec<PrintedHit>& hits, EngineBase* engine, const Vec<char*>& labels,
                               const Vec<ScanLine>& lines, const Vec<int>& idx, Vec<int>& used, int titleSlot,
                               int printed, int* nSecAttach) {
    int dest = MapPrintedPage(engine, printed, labels);
    int attached = 0;
    PrintedHit h;
    h.title = TitleWithLeftNumbering(lines, idx, used, titleSlot, &attached);
    h.printed = printed;
    h.destPage = dest;
    h.srcPage = lines[idx[titleSlot]].srcPage;
    h.srcX = lines[idx[titleSlot]].x;
    h.srcY = lines[idx[titleSlot]].y;
    h.indent = lines[idx[titleSlot]].x;
    h.fontSize = lines[idx[titleSlot]].fontSize;
    h.bold = lines[idx[titleSlot]].bold;
    hits.Append(h);
    if (attached && nSecAttach) {
        (*nSecAttach)++;
    }
}

static void NormalizeTitle(const char* s, char* dst, int cap, bool stripNum) {
    dst[0] = 0;
    if (!s || cap < 8) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            continue;
        }
        i = save;
        break;
    }
    if (stripNum) {
        SkipHeadingNumbering(s, len, i);
        while (i < len) {
            int save = i;
            int cp = Utf8CodepointNext(s, len, i);
            if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
                continue;
            }
            i = save;
            break;
        }
    }
    char* out = dst;
    char* end = dst + cap - 2;
    while (i < len && out + 4 < end) {
        int cp = Utf8CodepointNext(s, len, i);
        if (cp <= 32 || cp == 0x3000 || IsLeaderCp(cp)) {
            continue;
        }
        if (cp >= 'A' && cp <= 'Z') {
            cp += 32;
        }
        if (cp >= 0xFF10 && cp <= 0xFF19) {
            cp = '0' + (cp - 0xFF10);
        }
        if (cp >= 0xFF21 && cp <= 0xFF3A) {
            cp = 'a' + (cp - 0xFF21);
        }
        if (cp >= 0xFF41 && cp <= 0xFF5A) {
            cp = 'a' + (cp - 0xFF41);
        }
        str::Utf8Encode(out, cp);
    }
    *out = 0;
}

static int TitleMatchScore(const char* a, const char* b) {
    if (!a || !b || !a[0] || !b[0]) {
        return 0;
    }
    if (str::Eq(a, b)) {
        return 100;
    }
    int ga = GlyphCount(a);
    int gb = GlyphCount(b);
    int mn = ga < gb ? ga : gb;
    if (mn < kExtractPdfToc.matchContainMinGlyphs) {
        return 0;
    }
    if (str::Find(a, b) || str::Find(b, a)) {
        return 80;
    }
    return 0;
}

// The generic printed-TOC parser can see two near-overlaid OCR rows as
// different rows when the page token was recognized differently. At this
// point destination resolution has completed, so (source TOC page,
// destination page, title match) is the reliable identity. This is narrower
// than raw-line de-duplication and deliberately leaves same-titled headings
// that lead to different document pages intact.
static void DropMappedDuplicatePrintedHits(Vec<PrintedHit>& hits) {
    int dropped = 0;
    for (int i = 0; i < hits.Size(); i++) {
        for (int j = i + 1; j < hits.Size();) {
            bool same = hits[i].srcPage == hits[j].srcPage && hits[i].destPage > 0 &&
                        hits[i].destPage == hits[j].destPage && TitleMatchScore(hits[i].title, hits[j].title) >= 80;
            if (!same) {
                j++;
                continue;
            }
            // For a dotted/garbled variant, retain the shorter clean title.
            int ni = GlyphCount(hits[i].title);
            int nj = GlyphCount(hits[j].title);
            if (nj < ni) {
                PrintedHit t = hits[i];
                hits[i] = hits[j];
                hits[j] = t;
            }
            logf("TOC printed-duplicate drop tocPage=%d dest=%d keep=%s drop=%s\n", hits[i].srcPage, hits[i].destPage,
                 hits[i].title ? hits[i].title : "", hits[j].title ? hits[j].title : "");
            str::Free(hits[j].title);
            hits.RemoveAt(j);
            dropped++;
        }
    }
    logf("TOC printed-duplicate dropped=%d remaining=%d\n", dropped, hits.Size());
}

static void CompleteTruncatedBookQuotes(const Vec<ScanLine>& lines, Vec<PrintedHit>& hits) {
    for (int i = 0; i < hits.Size(); i++) {
        char* t = hits[i].title;
        if (!t || !t[0]) {
            continue;
        }
        const char* open = str::Find(t, "《");
        if (!open || str::Find(t, "》")) {
            continue;
        }
        char inside[96];
        NormalizeTitle(open + 3, inside, (int)sizeof(inside), false);
        if (!inside[0] || GlyphCount(inside) < 2) {
            continue;
        }
        int dest = hits[i].destPage;
        for (int k = 0; k < lines.Size(); k++) {
            if (!lines[k].text || lines[k].srcPage == hits[i].srcPage) {
                continue;
            }
            if (dest > 0 && lines[k].srcPage != dest && lines[k].srcPage != dest + 1) {
                continue;
            }
            const char* q = str::Find(lines[k].text, "《");
            const char* close = str::Find(lines[k].text, "》");
            if (!q || !close || close <= q + 3) {
                continue;
            }
            int qlen = (int)(close - (q + 3));
            if (qlen < 2 || qlen >= 90) {
                continue;
            }
            char quoted[96];
            memcpy(quoted, q + 3, (size_t)qlen);
            quoted[qlen] = 0;
            char quotedN[96];
            NormalizeTitle(quoted, quotedN, (int)sizeof(quotedN), false);
            if (!quotedN[0] || !str::StartsWith(quotedN, inside)) {
                continue;
            }
            int gq = GlyphCount(quotedN);
            int gi = GlyphCount(inside);
            if (gq > 24 || gq <= gi) {
                continue;
            }
            int prefixLen = (int)(open - t);
            char prefix[400];
            if (prefixLen < 0 || prefixLen >= (int)sizeof(prefix)) {
                continue;
            }
            memcpy(prefix, t, (size_t)prefixLen);
            prefix[prefixLen] = 0;
            char* wrapped = str::Join("《", quotedN, "》");
            if (!wrapped) {
                continue;
            }
            char* neu = str::Join(prefix, wrapped);
            str::Free(wrapped);
            if (!neu) {
                continue;
            }
            str::Free(hits[i].title);
            hits[i].title = neu;
            PolishPrintedHitTitle(&hits[i].title);
            break;
        }
    }
}

static int MedianInt(Vec<int>& v) {
    int n = v.Size();
    if (n < 1) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (v[j] < v[i]) {
                int t = v[i];
                v[i] = v[j];
                v[j] = t;
            }
        }
    }
    return v[n / 2];
}

static void SortPrintedHits(Vec<PrintedHit>& hits) {
    for (int i = 0; i < hits.Size(); i++) {
        for (int j = i + 1; j < hits.Size(); j++) {
            bool less = false;
            if (hits[j].srcPage != hits[i].srcPage) {
                less = hits[j].srcPage < hits[i].srcPage;
            } else if (hits[j].srcY + 0.5f < hits[i].srcY) {
                less = true;
            } else if (hits[j].srcY <= hits[i].srcY + 0.5f && hits[j].srcX < hits[i].srcX) {
                less = true;
            }
            if (less) {
                PrintedHit t = hits[i];
                hits[i] = hits[j];
                hits[j] = t;
            }
        }
    }
}

static bool ParseLeadingSectionInt(const char* s, int* leadOut, const char** restOut) {
    *leadOut = 0;
    *restOut = s;
    if (!s) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    int cp = Utf8CodepointNext(s, len, i);
    while (cp > 0 && (cp <= 32 || cp == 0x3000)) {
        cp = Utf8CodepointNext(s, len, i);
    }
    if (!IsDigitCp(cp)) {
        return false;
    }
    int v = DigitValue(cp);
    int n = 1;
    while (i < len) {
        int save = i;
        int next = Utf8CodepointNext(s, len, i);
        if (!IsDigitCp(next)) {
            i = save;
            break;
        }
        v = v * 10 + DigitValue(next);
        n++;
        if (n > 3) {
            return false;
        }
    }
    int saveMark = i;
    int mark = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (mark == '.' || mark == 0xFF0E || mark == 0x3002) {
        return false;
    }
    i = saveMark;
    *leadOut = v;
    while (i < len) {
        int save = i;
        int next = Utf8CodepointNext(s, len, i);
        if (next <= 32 || next == 0x3000) {
            continue;
        }
        i = save;
        break;
    }
    *restOut = s + i;
    return v >= 1 && HasLetterOrCjk(*restOut);
}

static bool LooksLikeBracketTxnCodeTitle(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    int len = (int)str::Len(s);
    int i = 0;
    SkipSpacesUtf8(s, len, i);
    int open = i < len ? Utf8CodepointNext(s, len, i) : 0;
    if (open != 0x3010) {
        return false;
    }
    int nDig = 0;
    while (i < len) {
        int save = i;
        int d = Utf8CodepointNext(s, len, i);
        if (IsDigitCp(d)) {
            nDig++;
            if (nDig > 4) {
                return false;
            }
            continue;
        }
        i = save;
        break;
    }
    if (nDig < 3) {
        return false;
    }
    int close = i < len ? Utf8CodepointNext(s, len, i) : 0;
    return close == 0x3011;
}

static bool PrintedTitleHasExplicitListNumber(const char* s) {
    if (!s || !s[0]) {
        return false;
    }
    if (LooksLikeBracketTxnCodeTitle(s)) {
        return true;
    }
    if (StartsWithXinDeHeading(s)) {
        return true;
    }
    HeadingMarker m = ParseHeadingMarker(s);
    if (m.type == MarkerType::ArabicDot || m.type == MarkerType::ChineseDunhao || m.type == MarkerType::ChineseParen ||
        m.type == MarkerType::ArabicParen || m.type == MarkerType::YiShi) {
        return true;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    return num.nComp >= 1 && num.hadTrailingDot;
}

static void RepairPrintedHitTitles(Vec<PrintedHit>& hits) {
    int chap = 0;
    int lastSec = 0;
    int nRepairLog = 0;
    for (int i = 0; i < hits.Size(); i++) {
        int lvl = HeadingLevelFromText(hits[i].title);
        int len = hits[i].title ? (int)str::Len(hits[i].title) : 0;
        int ti = 0;
        int first = hits[i].title ? Utf8CodepointNext(hits[i].title, len, ti) : 0;
        if (first == 0x7B2C) {
            chap = 0;
            lastSec = 0;
            SkipSpacesUtf8(hits[i].title, len, ti);
            int n = 0;
            while (ti < len) {
                int save = ti;
                int next = Utf8CodepointNext(hits[i].title, len, ti);
                if (IsDigitCp(next)) {
                    n = n * 10 + DigitValue(next);
                    continue;
                }
                if (IsCnNumeral(next)) {
                    continue;
                }
                ti = save;
                break;
            }
            if (n > 0) {
                chap = n;
            }
            lastSec = 0;
            continue;
        }
        ParsedNumbering curNum;
        ParseHeadingNumbering(hits[i].title, &curNum);
        if (NumberingIsBareArabicChapter(curNum, hits[i].title)) {
            chap = curNum.comp[0];
            lastSec = 0;
            continue;
        }
        if (lvl >= 2 && IsDigitCp(first)) {
            int a = DigitValue(first);
            while (ti < len) {
                int save = ti;
                int next = Utf8CodepointNext(hits[i].title, len, ti);
                if (IsDigitCp(next)) {
                    a = a * 10 + DigitValue(next);
                    continue;
                }
                ti = save;
                break;
            }
            int mark = ti < len ? Utf8CodepointNext(hits[i].title, len, ti) : 0;
            if (mark == '.' || mark == 0xFF0E) {
                int b = 0;
                int nB = 0;
                while (ti < len) {
                    int save = ti;
                    int next = Utf8CodepointNext(hits[i].title, len, ti);
                    if (IsDigitCp(next)) {
                        b = b * 10 + DigitValue(next);
                        nB++;
                        continue;
                    }
                    ti = save;
                    break;
                }
                if (nB > 0) {
                    chap = a;
                    lastSec = b;
                }
            }
            continue;
        }
        if (PrintedTitleHasExplicitListNumber(hits[i].title)) {
            if (curNum.nComp >= 2) {
                chap = curNum.comp[0];
                lastSec = curNum.comp[1];
            } else if (curNum.nComp == 1) {
                lastSec = curNum.comp[0];
            }
            continue;
        }
        int lead = 0;
        const char* rest = nullptr;
        if (!ParseLeadingSectionInt(hits[i].title, &lead, &rest) || chap < 1) {
            continue;
        }
        bool repair = false;
        if (lastSec > 0 && lead == lastSec + 1) {
            repair = true;
        }
        if (lastSec == 0 && lead == 1) {
            repair = true;
        }
        if (i + 1 < hits.Size()) {
            int nlvl = HeadingLevelFromText(hits[i + 1].title);
            int nlen = hits[i + 1].title ? (int)str::Len(hits[i + 1].title) : 0;
            int nj = 0;
            int nf = hits[i + 1].title ? Utf8CodepointNext(hits[i + 1].title, nlen, nj) : 0;
            if (nlvl >= 2 && IsDigitCp(nf)) {
                int na = DigitValue(nf);
                while (nj < nlen) {
                    int save = nj;
                    int next = Utf8CodepointNext(hits[i + 1].title, nlen, nj);
                    if (IsDigitCp(next)) {
                        na = na * 10 + DigitValue(next);
                        continue;
                    }
                    nj = save;
                    break;
                }
                int mark = nj < nlen ? Utf8CodepointNext(hits[i + 1].title, nlen, nj) : 0;
                int nb = 0;
                if (mark == '.' || mark == 0xFF0E) {
                    while (nj < nlen) {
                        int save = nj;
                        int next = Utf8CodepointNext(hits[i + 1].title, nlen, nj);
                        if (IsDigitCp(next)) {
                            nb = nb * 10 + DigitValue(next);
                            continue;
                        }
                        nj = save;
                        break;
                    }
                    if (na == chap && nb == lead + 1) {
                        repair = true;
                    }
                }
            }
        }
        if (!repair || !rest) {
            continue;
        }
        char* old = hits[i].title;
        char* neu = str::Format("%d.%d %s", chap, lead, rest);
        str::Free(old);
        hits[i].title = neu;
        lastSec = lead;
    }
    for (int i = 0; i < hits.Size(); i++) {
        PolishPrintedHitTitle(&hits[i].title);
    }
    // Trace the generic printed-TOC path before any destination correction.
    // Unlike the book parser, this is the path selected for the 149-page
    // textbook, so this snapshot identifies the first stage containing a
    // duplicate pair.
    for (int i = 0; i < hits.Size(); i++) {
        const PrintedHit& h = hits[i];
        logf("TOC printed-hit stage=parsed idx=%d tocPage=%d x=%.1f y=%.1f printed=%d dest=%d title=%s\n", i, h.srcPage,
             h.srcX, h.srcY, h.printed, h.destPage, h.title ? h.title : "");
    }
}

static void PrefixSectionNumber(PrintedHit& h, int chap, int sec) {
    ParsedNumbering have;
    ParseHeadingNumbering(h.title, &have);
    if (!h.title || have.nComp >= 1 || have.isChapter || NumberingIsBareArabicChapter(have, h.title) ||
        PrintedTitleHasExplicitListNumber(h.title)) {
        return;
    }
    char* neu = str::Format("%d.%d %s", chap, sec, h.title);
    // #region agent log
    if (Dbg92Interesting(h.title) || str::Find(h.title, "【")) {
        char extra[192];
        snprintf(extra, (int)sizeof(extra), "prefix=%d.%d", chap, sec);
        Dbg92a48e("H", "ExtractPdfToc.cpp:PrefixSectionNumber", h.title, extra);
    }
    // #endregion
    str::Free(h.title);
    h.title = neu;
}

static void StripFalseSectionPrefixOnChapter(char** titleOut) {
    char* s = *titleOut;
    if (!s || !s[0]) {
        return;
    }
    ParsedNumbering num;
    ParseHeadingNumbering(s, &num);
    if (num.isChapter || num.nComp < 2) {
        return;
    }
    int len = (int)str::Len(s);
    int i = 0;
    while (i < len) {
        int save = i;
        int cp = Utf8CodepointNext(s, len, i);
        if (IsDigitCp(cp) || cp == '.' || cp == 0xFF0E || cp <= 32 || cp == 0x3000) {
            continue;
        }
        i = save;
        break;
    }
    if (i <= 0 || i >= len) {
        return;
    }
    ParsedNumbering rest;
    ParseHeadingNumbering(s + i, &rest);
    if (!rest.isChapter && !NumberingIsBareArabicChapter(rest, s + i)) {
        return;
    }
    char* neu = str::Dup(s + i);
    str::Free(s);
    *titleOut = neu;
}

static void PrefixBareChapterNumber(PrintedHit& h, int chap) {
    if (!h.title || chap < 1) {
        return;
    }
    ParsedNumbering have;
    ParseHeadingNumbering(h.title, &have);
    if (have.isChapter || NumberingIsBareArabicChapter(have, h.title) || have.nComp >= 2) {
        return;
    }
    char* neu = str::Format("%d %s", chap, h.title);
    str::Free(h.title);
    h.title = neu;
}

static void RepairMissingSectionNumbers(Vec<PrintedHit>& hits) {
    int chap = 0;
    int lastSec = 0;
    Vec<int> pending;
    int nFill = 0;
    for (int i = 0; i < hits.Size(); i++) {
        ParsedNumbering num;
        ParseHeadingNumbering(hits[i].title, &num);
        if (num.isChapter || NumberingIsBareArabicChapter(num, hits[i].title)) {
            if (pending.Size() > 0 && chap > 0) {
                for (int p = 0; p < pending.Size(); p++) {
                    PrefixSectionNumber(hits[pending[p]], chap, lastSec + 1 + p);
                    nFill++;
                }
            }
            pending.Reset();
            chap = num.comp[0];
            lastSec = 0;
            continue;
        }
        if (num.nComp >= 3 && num.comp[0] > 0) {
            int n = pending.Size();
            if (n > 0) {
                PrefixSectionNumber(hits[pending[n - 1]], num.comp[0], num.comp[1]);
                nFill++;
                for (int p = 0; p < n - 1; p++) {
                    PrefixSectionNumber(hits[pending[p]], num.comp[0], p + 1);
                    nFill++;
                }
                pending.Reset();
            }
            chap = num.comp[0];
            lastSec = num.comp[1];
            continue;
        }
        if (num.nComp == 2 && num.comp[0] > 0) {
            if (num.comp[1] == 1 && pending.Size() == 1) {
                PrefixBareChapterNumber(hits[pending[0]], num.comp[0]);
                pending.Reset();
            } else if (num.comp[1] == 1 && pending.Size() == 0 && i > 0) {
                ParsedNumbering prev;
                ParseHeadingNumbering(hits[i - 1].title, &prev);
                if (prev.nComp < 1 && !prev.isChapter && HeadingLevelFromText(hits[i - 1].title) < 1) {
                    PrefixBareChapterNumber(hits[i - 1], num.comp[0]);
                }
            }
            int n = pending.Size();
            int start = num.comp[1] - n;
            if (start < 1) {
                start = 1;
            }
            for (int p = 0; p < n; p++) {
                PrefixSectionNumber(hits[pending[p]], num.comp[0], start + p);
                nFill++;
            }
            pending.Reset();
            chap = num.comp[0];
            lastSec = num.comp[1];
            continue;
        }
        if (chap > 0 && num.nComp < 1 && !PrintedTitleHasExplicitListNumber(hits[i].title)) {
            pending.Append(i);
        }
    }
    if (pending.Size() > 0 && chap > 0) {
        for (int p = 0; p < pending.Size(); p++) {
            PrefixSectionNumber(hits[pending[p]], chap, lastSec + 1 + p);
            nFill++;
        }
    }
    for (int i = 0; i < hits.Size(); i++) {
        StripFalseSectionPrefixOnChapter(&hits[i].title);
    }
}

static PrintedHit MakeTestHit(const char* title, int srcPage, float srcY) {
    PrintedHit h;
    h.title = str::Dup(title);
    h.srcPage = srcPage;
    h.srcY = srcY;
    h.srcX = 40;
    h.fontSize = 12;
    return h;
}

static PrintedHit MakeBookHit(const char* title, int printed, float srcX, float srcY, float fontSize) {
    PrintedHit h;
    h.title = str::Dup(title);
    h.printed = printed;
    h.srcPage = 1;
    h.srcX = srcX;
    h.srcY = srcY;
    h.indent = srcX;
    h.fontSize = fontSize;
    h.bold = printed < 1 && fontSize >= 14;
    return h;
}

static void BookHitsToTree(Vec<PrintedHit>& hits, Vec<ExtractedTocItem*>& roots) {
    AssignBookPrintedLevels(hits);
    Vec<ExtractedTocItem*> flat;
    for (int i = 0; i < hits.Size(); i++) {
        int page = hits[i].destPage > 0 ? hits[i].destPage : hits[i].printed;
        flat.Append(NewItem(hits[i].title, page, 0, 0, hits[i].level));
    }
    BuildTreeFromFlat(flat, roots);
}

static bool TocTreeHasTitle(const Vec<ExtractedTocItem*>& nodes, const char* t) {
    for (int i = 0; i < nodes.Size(); i++) {
        if (nodes[i]->title && str::Eq(nodes[i]->title, t)) {
            return true;
        }
        if (TocTreeHasTitle(nodes[i]->children, t)) {
            return true;
        }
    }
    return false;
}

static ExtractedTocItem* TocTreeFind(const Vec<ExtractedTocItem*>& nodes, const char* t) {
    for (int i = 0; i < nodes.Size(); i++) {
        if (nodes[i]->title && str::Eq(nodes[i]->title, t)) {
            return nodes[i];
        }
        ExtractedTocItem* c = TocTreeFind(nodes[i]->children, t);
        if (c) {
            return c;
        }
    }
    return nullptr;
}

