            if (sp < 1) {
                parts[nParts++] = str::Dup(src);
                break;
            }
            parts[nParts] = str::Dup(src, (size_t)sp);
            str::TrimWSInPlace(parts[nParts], str::TrimOpt::Both);
            nParts++;
            src += sp;
